B.cvJ=s([B.kS,B.ka,B.k9,B.hpW],t.L)
B.cgh=s(["Growth hopes up \u2192 copper up faster than gold \u2192 ratio up \u2192 yields tend to follow.","Growth fears \u2192 the reverse."],t.s)
