B.ho8=new A.L("Formula","roll = 1200 * (front[1] / next[1] - 1) (annualized, contracts assumed one month apart)")
B.htZ=new A.L("Score (vote)","clamp(roll / 10, -1, 1); na -> 0")
B.hlJ=new A.L("How traders read it","In backwardation a long futures position rolls into a cheaper contract and earns the gap; in contango it pays it. Carry traders favour backwardated markets.")
B.hl6=new A.L("Caveats","Runs in TradingView only: the app has no second-month futures prices. The 1200 annualizer assumes monthly contract spacing (crude oil); change the symbols and span for other markets.")
B.d4b=s([B.ho8,B.htZ,B.hlJ,B.hl6],t.L)
B.dhJ=s(["Front and next continuous futures contracts.","Front / next - 1, annualized.","Backwardation votes up, contango votes down."],t.s)
B.cO5=s(["c-fxcarry","c-curvemom"],t.s)
B.fGQ=new A.e6("c-rollyield","Futures roll yield","Front vs next futures contract: backwardation (front above next) earns positive roll yield.","","","","","","","",B.d4b,B.dhJ,"",B.cL,B.cO5)
B.hm5=new A.L("Formula","diff = DGS10[1] - IRLTLT01JPM156N[1]")
B.hlu=new A.L("Score (vote)","clamp(diff / 3, -1, 1); na -> 0")
B.hlL=new A.L("How traders read it","Carry traders borrow in the low-yield currency and hold the high-yield one; a wide gap in favour of the dollar supports USD/JPY.")
B.hnK=new A.L("Caveats","A proxy: 10-year yields, not the short-term rates carry trades actually earn, and Japan's series is monthly. Meant for a USD/JPY chart; change both yields for another pair.")
B.da1=s([B.hm5,B.hlu,B.hlL,B.hnK],t.L)
B.cM3=s(["US 10-year yield minus Japan 10-year yield.","Scaled by 3 percentage points.","A positive gap votes for the dollar side."],t.s)
B.cLZ=s(["c-rollyield","c-curvemom"],t.s)
B.fGn=new A.e6("c-fxcarry","FX carry proxy (rate differential)","US minus Japan 10-year government yield: a wide differential favours the higher-yielding currency.","","","","","","","",B.da1,B.cM3,"",B.cL,B.cLZ)
B.hrk=new A.L("Formula","chg = T10Y2Y[1] - T10Y2Y[1 + 63]")
B.hpP=new A.L("Score (vote)","clamp(chg / 0.5, -1, 1): +0.5 pct points steepening = +1; na -> 0")
B.hpH=new A.L("How traders read it","Direction, not level: a steepening curve often follows rate cuts or rising long-term inflation worries; flattening follows hikes.")
B.hoK=new A.L("Caveats","A steepening after a long inversion has historically come close to recessions, so +1 is not automatically good news for stocks. Read it with the level (the inversion block).")
B.d2e=s([B.hrk,B.hpP,B.hpH,B.hoK],t.L)
B.cU6=s(["10-year minus 2-year Treasury spread.","Its change over 63 bars.","Steepening votes up, flattening votes down."],t.s)
B.cTd=s(["c-rollyield","c-fxcarry"],t.s)
B.fHv=new A.e6("c-curvemom","Curve slope momentum","Change in the 10-year minus 2-year spread over about 3 months (+1 = steepening).","","","","","","","",B.d2e,B.cU6,"",B.cL,B.cTd)
B.hre=new A.L("Formula","r = ln(close / close[1]); Y_k = sum_{j<=k}(r_j - mean(r)) over the last 100 returns (oldest first, Y_0 = 0); R = max(Y) - min(Y); S = stdev(r, 100); H = ln(R / S) / ln(100)")
B.hmm=new A.L("Score (vote)","H* = H - ln(1.2533) / ln(100) (removes the small-sample bias that makes a random walk read about 0.52); vote = sign(change(close, 100)) * clamp((H* - 0.5) * 5, 0, 1): random walk (H* <= 0.5) = 0, H* >= 0.7 = full vote in the move's direction")
B.hnM=new A.L("How traders read it","H near 0.5 looks like a random walk; above 0.5 suggests persistent moves (trends), below 0.5 mean reversion. The vote only counts when persistence is high.")
B.hpN=new A.L("Caveats","A single-window rescaled-range estimate: rough and biased upward on short samples (about 100 bars). Treat it as a persistence hint, not a measurement.")
B.cZZ=s([B.hre,B.hmm,B.hnM,B.hpN],t.L)
B.cRu=s(["Cumulative deviations of returns from their mean over 100 bars.","Range of that path / standard deviation of returns.","H = log of that ratio / log 100.","Above 0.5 votes in the direction of the 100-bar move."],t.s)
B.daz=s(["c-kaufer","c-frogpan"],t.s)
B.fGw=new A.e6("c-hurst","Hurst exponent (trend persistence)","Rescaled-range estimate of trend persistence, signed by the direction of the move.","","","","","","","",B.cZZ,B.cRu,"",B.cL,B.daz)
B.htj=new A.L("Formula","ER = (close - close[21]) / sum(|close - close[1]|, 21) (the sum as sma x 21)")
B.hm4=new A.L("Score (vote)","ER itself (signed, already within [-1, 1]; clamped for rounding); flat path = 0")
B.htP=new A.L("How traders read it","1 means price went straight there; near 0 means a lot of back and forth for little progress. Kaufman used it to speed up or slow down his adaptive average.")
B.hlr=new A.L("Caveats","Window length changes the reading a lot; very short windows look efficient by chance.")
B.d9y=s([B.htj,B.hm4,B.htP,B.hlr],t.L)
B.cRQ=s(["Net change over 21 bars.","Sum of every bar's absolute change (the path).","Net / path = the efficiency, with its sign."],t.s)
B.cX9=s(["c-hurst","c-frogpan"],t.s)
B.fGB=new A.e6("c-kaufer","Kaufman efficiency ratio","Net move divided by the path travelled (signed): a straight, clean trend scores near \xb11.","","","","","","","",B.d9y,B.cRQ,"",B.cL,B.cX9)
B.hri=new A.L("Formula","up = share of the last 252 bar changes > 0; dn = share < 0; FIP score = sign(close - close[252]) * (up - dn)")
B.hm_=new A.L("Score (vote)","as is, within [-1, 1] (the negative of the paper's information-discreteness measure)")
B.ho9=new A.L("How traders read it","The paper argues that a trend built from many small steps gets noticed late (like a frog in slowly heating water), so it tends to persist; a trend built from a few big jumps is priced quickly.")
B.hlk=new A.L("Caveats","Counts days, not their size. Flat days count in neither share.")
B.d_6=s([B.hri,B.hm_,B.ho9,B.hlk],t.L)
B.dgv=s(["Share of up bars and of down bars over 252 bars.","Up share minus down share.","Signed by the direction of the 252-bar move."],t.s)
B.a1Z=s(["c-hurst","c-kaufer"],t.s)
B.fHg=new A.e6("c-frogpan","Frog-in-the-pan smoothness","Share of up days minus down days, signed by the year's move: smooth trends score high.","","","","","","","",B.d_6,B.dgv,"",B.cL,B.a1Z)
B.hkC=new A.L("Formula","ret = 100 * (close[21] / close[252] - 1)")
B.hnv=new A.L("Score (vote)","clamp(ret / 25, -1, 1)")
B.hlv=new A.L("How traders read it","Skipping the latest month avoids the short-term reversal effect that researchers found in single-month returns.")
B.hth=new A.L("Caveats","Momentum has suffered sharp crashes after bear markets (see the crash-risk gate).")
B.cTf=s([B.hkC,B.hnv,B.hlv,B.hth],t.L)
B.dd2=s(["Price a month ago / price a year ago.","As a percent.","Scaled by 25%."],t.s)
B.fHw=new A.e6("c-mom121","12-1 momentum","The 12-month return skipping the latest month (the classic academic momentum measure).","","","","","","","",B.cTf,B.dd2,"",B.cL,B.a1Z)
B.hnL=new A.L("Formula","bear = roc(close, 252) < 0; hot = percentrank(stdev(ln(close / close[1]), 21), 252) >= 80; rebound = roc(close, 21) > 0")
B.hpI=new A.L("Score (vote)","gate = 0 if bear and hot and rebound; 0.5 if bear and hot; else 1; any na -> 1 (pass-through)")
B.ht5=new A.L("How traders read it",'Momentum crashes have clustered in "panic states": after a bear market, with high volatility, when the beaten-down losers rebound sharply.')
B.hoZ=new A.L("Caveats","A simplified, single-asset version of a cross-sectional finding. It cuts exposure; it does not predict the rebound.")
B.djn=s([B.hnL,B.hpI,B.ht5,B.hoZ],t.L)
B.cVX=s(["Is the past year's return negative?","Is volatility in its top fifth for the year?","Both: half size; plus a 21-bar rebound: flat."],t.s)
B.fGk=new A.e6("c-crashgate","Momentum crash-risk gate","Cuts exposure in the panic state (bear market + high volatility), to flat during a sharp rebound.","","","","","","","",B.djn,B.cVX,"",B.cL,B.a1Z)
B.hrt=new A.L("Formula","r = close / close[1] - 1 over 252 bars; p = share r > 0; W = mean win, L = mean |loss|; Kelly f = p/L - (1-p)/W = p(1-p)(1/sma(max(-r,0)) - 1/sma(max(r,0)))")
B.hpr=new A.L("Score (vote)","posScalar = clamp(0.5 * f, 0, 1) (sizing, not a vote); na -> 1 like voltarget")
B.hti=new A.L("How traders read it","Kelly sizing maximises long-run growth for a bet with known odds; traders use a fraction (often half) because the odds are only estimated.")
B.huR=new A.L("Caveats","Treats every bar as an independent two-outcome bet, which returns are not. Estimates from one year of history are noisy; the cap stops leverage.")
B.cG_=s([B.hrt,B.hpr,B.hti,B.huR],t.L)
B.cQS=s(["Hit rate and average win / loss of daily returns over 252 bars.","Kelly fraction for that bet.","Times 0.5, capped at 1: the position scalar."],t.s)
B.cVL=s(["c-invvol","c-rsharpe"],t.s)
B.fGJ=new A.e6("c-kelly","Kelly fraction (half-Kelly)","Position scalar from the rolling hit rate and payoff: half-Kelly by default, capped.","","","","","","","",B.cG_,B.cQS,"",B.cL,B.cVL)
B.hkE=new A.L("Formula","v_i = stdev(daily log returns, 63) of chart[1], TLT[1], GLD[1]; w = (1/v_0) / sum(1/v_i)")
B.hkF=new A.L("Score (vote)","posScalar = clamp(3 w, 0, 1): 1 = its equal-risk share; na -> 1")
B.hui=new A.L("How traders read it","Risk parity gives each asset the same risk budget, so a calmer asset gets more capital. Here the chart symbol's scalar falls when it is riskier than the bond and gold sleeves.")
B.hmf=new A.L("Caveats","Uses volatility only (no correlations). Three legs means three data requests on TradingView; in the app it needs both basket series.")
B.cvI=s([B.hkE,B.hkF,B.hui,B.hmf],t.L)
B.cK1=s(["63-bar volatility of the chart symbol, TLT and GLD.","Inverse-volatility weight of the chart symbol.","Times 3 (its equal share = 1), capped."],t.s)
B.cTU=s(["c-kelly","c-rsharpe"],t.s)
B.fHc=new A.e6("c-invvol","Risk-parity inverse-vol weight","This asset's inverse-volatility weight against a small basket (bonds, gold), as a position scalar.","","","","","","","",B.cvI,B.cK1,"",B.cL,B.cTU)
B.hs8=new A.L("Formula","SR = sma(r, 252) / stdev(r, 252) * sqrt(252), r = ln(close / close[1]) (no risk-free rate)")
B.hmF=new A.L("Score (vote)","clamp(SR / 2, -1, 1)")
B.hr7=new A.L("How traders read it","Return per unit of risk. Here it is a trailing description of the past year, not a forecast.")
B.ho0=new A.L("Caveats","No risk-free rate is subtracted (excess over zero). Penalises upside swings as much as downside ones.")
B.cVP=s([B.hs8,B.hmF,B.hr7,B.ho0],t.L)
B.diG=s(["Daily log returns over 252 bars.","Average / standard deviation, annualized.","Scaled by 2."],t.s)
B.Ew=s(["c-kelly","c-invvol"],t.s)
B.fGy=new A.e6("c-rsharpe","Rolling Sharpe ratio","Mean daily log return over its standard deviation, annualized, over the past year.","","","","","","","",B.cVP,B.diG,"",B.cL,B.Ew)
B.htn=new A.L("Formula","SO = sma(r, 252) / sqrt(sma(min(r, 0)^2, 252)) * sqrt(252) (target 0)")
B.hul=new A.L("Score (vote)","clamp(SO / 3, -1, 1); no down bars: +1 if mean > 0 else 0")
