B.dd7=s([B.huq,B.hlN],t.L)
B.cTp=s(["realyield","cpi","oil","c-real-nominal"],t.s)
B.fH0=new A.e6("breakeven","10-year breakeven inflation","The inflation rate the bond market is pricing over ten years: the 10-year Treasury yield minus the 10-year TIPS real yield.","The market expects higher inflation (or demands more protection).","The market expects lower inflation, or growth fears are dragging expectations down.","Inflation expectations rising.","Inflation expectations falling.","At {v}, the market expects inflation close to the Fed's goal.","At {v}, expectations are drifting away from the usual range.","At {v}, expectations are at an extreme \u2014 either de-anchored upward or signalling deflation fear.",B.d_V,B.daV,"Rising breakevens favour energy, materials and TIPS holders.",B.dd7,B.cTp)
