B.cOz=s(['prsPair = input.symbol("AMEX:SPY", "Pair symbol", group = "Formula library")','prsLen = input.int(63, "Spread window (bars)", minval = 2, group = "Formula library")','prsMinCorr = input.float(0.5, "Minimum return correlation", group = "Formula library")'],t.s)
B.d_r=s(["prsA = math.log(close[1])","prsB = math.log(f_sec(prsPair))","prsSpread = prsA - prsB","prsMean = ta.sma(prsSpread, prsLen)","prsSd = ta.stdev(prsSpread, prsLen)","prsCorr = ta.correlation(ta.change(prsA), ta.change(prsB), prsLen)","score_pairz = na(prsSd) or na(prsCorr) ? 0.0 : prsSd > 0 and prsCorr >= prsMinCorr ? math.max(math.min(-(prsSpread - prsMean) / prsSd / 2.0, 1.0), -1.0) : 0.0"],t.s)
B.aU1=new A.de("pairz","Pair spread z-score",B.cj,"score_pairz",u.dZ,B.cOz,B.d_r)
B.dhv=s(['rmrPair = input.symbol("AMEX:SPY", "Ratio denominator", group = "Formula library")','rmrLen = input.int(126, "Ratio average length (bars)", minval = 2, group = "Formula library")'],t.s)
B.dk8=s(["rmrRatio = close[1] / f_sec(rmrPair)","rmrMa = ta.sma(rmrRatio, rmrLen)","rmrSd = ta.stdev(rmrRatio, rmrLen)","score_ratiomr = na(rmrSd) ? 0.0 : rmrSd > 0 ? math.max(math.min(-(rmrRatio - rmrMa) / rmrSd / 2.0, 1.0), -1.0) : 0.0"],t.s)
B.aUf=new A.de("ratiomr","Ratio mean reversion",B.cj,"score_ratiomr",u.il,B.dhv,B.dk8)
B.cw6=s(['bspPair = input.symbol("AMEX:SPY", "Hedge symbol", group = "Formula library")','bspLen = input.int(63, "Beta and spread window (bars)", minval = 2, group = "Formula library")'],t.s)
B.cXZ=s(["bspA = math.log(close[1])","bspB = math.log(f_sec(bspPair))","bspRa = ta.change(bspA)","bspRb = ta.change(bspB)","bspCorr = ta.correlation(bspRa, bspRb, bspLen)","bspSdA = ta.stdev(bspRa, bspLen)","bspSdB = ta.stdev(bspRb, bspLen)","bspBeta = bspSdB > 0 ? bspCorr * bspSdA / bspSdB : na","bspSpread = bspA - bspBeta * bspB","bspMa = ta.sma(bspSpread, bspLen)","bspSd = ta.stdev(bspSpread, bspLen)","score_betaspread = na(bspSd) ? 0.0 : bspSd > 0 ? math.max(math.min(-(bspSpread - bspMa) / bspSd / 2.0, 1.0), -1.0) : 0.0"],t.s)
B.aU9=new A.de("betaspread","Beta-adjusted spread",B.cj,"score_betaspread",u.k_,B.cw6,B.cXZ)
