B.d8F=s(["rspRs = close[1] / f_sec(rspBench)","rspPr = ta.percentrank(ta.roc(rspRs, rspLen), rspRank)","score_rspct = na(rspPr) ? 0.0 : (rspPr - 50.0) / 50.0"],t.s)
