B.aUm=new A.de("rvol","Realized volatility",B.e5,"score_rvol",u.aY,B.dhE,B.cgb)
B.cV4=s(['pkvLen = input.int(21, "Volatility window (bars)", minval = 1, group = "Formula library")','pkvRef = input.float(20.0, "Reference annualized vol %", minval = 0.1, group = "Formula library")'],t.s)
B.cX0=s(["pkvHl = math.log(high / low)","pkvVol = math.sqrt(ta.sma(pkvHl * pkvHl, pkvLen) / (4.0 * math.log(2.0)) * 252.0) * 100.0","score_parkvol = na(pkvVol) ? na : math.max(math.min((pkvRef - pkvVol) / pkvRef, 1.0), -1.0)"],t.s)
B.aUe=new A.de("parkvol","Parkinson volatility",B.e5,"score_parkvol",u.mq,B.cV4,B.cX0)
