B.cRk=s(["gkvHl = math.log(high / low)","gkvCo = math.log(close / open)","gkvVar = ta.sma(0.5 * gkvHl * gkvHl - (2.0 * math.log(2.0) - 1.0) * gkvCo * gkvCo, gkvLen)","gkvVol = math.sqrt(gkvVar * 252.0) * 100.0","score_gkvol = na(gkvVol) ? na : math.max(math.min((gkvRef - gkvVol) / gkvRef, 1.0), -1.0)"],t.s)
