B.cK2=s(["vrpPx = f_sec(vrpRef)","vrpRv = ta.stdev(math.log(vrpPx / vrpPx[1]), vrpLen) * math.sqrt(252) * 100.0","vrpGap = f_sec(vrpVix) - vrpRv","score_vrp = na(vrpGap) ? 0.0 : math.max(math.min(vrpGap / vrpSpan, 1.0), -1.0)"],t.s)
