B.d1u=s(["vovRv = ta.stdev(math.log(close / close[1]), vovLen)","vovMean = ta.sma(vovRv, vovWin)","vovSd = ta.stdev(vovRv, vovWin)","vovCv = vovMean > 0 ? vovSd / vovMean : na","score_volofvol = na(vovCv) ? na : math.max(math.min((vovRef - vovCv) / vovRef, 1.0), -1.0)"],t.s)
