B.cRS=s(['atpLen = input.int(14, "ATR length (bars)", minval = 1, group = "Formula library")','atpRef = input.float(2.0, "Reference ATR % of price", minval = 0.01, group = "Formula library")'],t.s)
B.cNF=s(["atpTr = na(close[1]) ? high - low : math.max(high - low, math.max(math.abs(high - close[1]), math.abs(low - close[1])))","atpPct = 100.0 * ta.rma(atpTr, atpLen) / close","score_atrpct = na(atpPct) ? na : math.max(math.min((atpRef - atpPct) / atpRef, 1.0), -1.0)"],t.s)
