B.cWa=s(["rylFr = f_sec(rylFront)","rylNx = f_sec(rylNext)","rylRoll = rylNx > 0 ? 1200.0 * (rylFr / rylNx - 1.0) : na","score_rollyield = na(rylRoll) ? 0.0 : math.max(math.min(rylRoll / rylSpan, 1.0), -1.0)"],t.s)
B.aU0=new A.de("rollyield","Futures roll yield",B.cj,"score_rollyield",u.bq,B.c8X,B.cWa)
