B.d9h=s(["fxcDiff = f_sec(fxcHome) - f_sec(fxcForeign)","score_fxcarry = na(fxcDiff) ? 0.0 : math.max(math.min(fxcDiff / fxcSpan, 1.0), -1.0)"],t.s)
