B.cZV=s(["cvmChg = ta.change(f_sec(cvmSym), cvmLen)","score_curvemom = na(cvmChg) ? 0.0 : math.max(math.min(cvmChg / cvmSpan, 1.0), -1.0)"],t.s)
B.aTY=new A.de("curvemom","Curve slope momentum",B.cj,"score_curvemom",u.dl,B.cSy,B.cZV)
B.bXv=s(['hstLen = input.int(100, "Hurst window (bars)", minval = 8, group = "Formula library")'],t.s)
B.d9J=s(["hstRet = math.log(close / close[1])","hstMean = ta.sma(hstRet, hstLen)","hstSd = ta.stdev(hstRet, hstLen)","hstDir = math.sign(ta.change(close, hstLen))","float hstH = na","if not na(hstMean) and hstSd > 0","    float hstY = 0.0","    float hstHi = 0.0","    float hstLo = 0.0","    for i = hstLen - 1 to 0","        hstY += hstRet[i] - hstMean","        hstHi := math.max(hstHi, hstY)","        hstLo := math.min(hstLo, hstY)","    hstH := math.log((hstHi - hstLo) / hstSd) / math.log(hstLen)","score_hurst = na(hstH) or na(hstDir) ? na : hstDir * math.max(math.min((hstH - math.log(1.2533) / math.log(hstLen) - 0.5) * 5.0, 1.0), 0.0)"],t.s)
B.aUh=new A.de("hurst","Hurst exponent",B.e5,"score_hurst",u.oX,B.bXv,B.d9J)
