B.cTQ=s(["kerNet = ta.change(close, kerLen)","kerPath = ta.sma(math.abs(ta.change(close)), kerLen) * kerLen","score_kaufer = na(kerNet) or na(kerPath) ? na : kerPath > 0 ? math.max(math.min(kerNet / kerPath, 1.0), -1.0) : 0.0"],t.s)
B.aUp=new A.de("kaufer","Kaufman efficiency",B.e5,"score_kaufer",u.bX,B.dek,B.cTQ)
B.cZ5=s(['fipLen = input.int(252, "Window (bars)", minval = 2, group = "Formula library")'],t.s)
B.d3c=s(["fipRet = ta.change(close)","fipUp = ta.sma(na(fipRet) ? na : fipRet > 0 ? 1.0 : 0.0, fipLen)","fipDn = ta.sma(na(fipRet) ? na : fipRet < 0 ? 1.0 : 0.0, fipLen)","fipDir = math.sign(ta.change(close, fipLen))","score_frogpan = na(fipUp) or na(fipDn) or na(fipDir) ? na : fipDir * (fipUp - fipDn)"],t.s)
B.aUt=new A.de("frogpan","Frog in the pan",B.e5,"score_frogpan",u.ew,B.cZ5,B.d3c)
