B.dbn=s(["m121Ret = 100.0 * (close[m121Skip] / close[m121Long] - 1.0)","score_mom121 = na(m121Ret) ? na : math.max(math.min(m121Ret / m121Span, 1.0), -1.0)"],t.s)
