B.dcL=s(["crgPast = ta.roc(close, crgBear)","crgRv = ta.stdev(math.log(close / close[1]), crgVolLen)","crgPr = ta.percentrank(crgRv, 252)","crgUp = ta.roc(close, crgVolLen)","gate_crashgate = na(crgPast) or na(crgPr) or na(crgUp) ? 1.0 : crgPast < 0 and crgPr >= crgVolRank ? (crgUp > 0 ? 0.0 : 0.5) : 1.0"],t.s)
B.aUj=new A.de("crashgate","Momentum crash gate",B.lx,"gate_crashgate",u.oH,B.cNv,B.dcL)
B.d_h=s(['klyLen = input.int(252, "Kelly window (bars)", minval = 2, group = "Sizing")','klyFrac = input.float(0.5, "Kelly fraction (0.5 = half-Kelly)", minval = 0, maxval = 1, group = "Sizing")','klyMax = input.float(1.0, "Max position scalar", minval = 0, group = "Sizing")'],t.s)
B.djx=s(["klyRet = close / close[1] - 1.0","klyP = ta.sma(na(klyRet) ? na : klyRet > 0 ? 1.0 : 0.0, klyLen)","klyUp = ta.sma(na(klyRet) ? na : math.max(klyRet, 0.0), klyLen)","klyDn = ta.sma(na(klyRet) ? na : math.max(-klyRet, 0.0), klyLen)","klyF = klyUp > 0 and klyDn > 0 ? klyP * (1.0 - klyP) * (1.0 / klyDn - 1.0 / klyUp) : na","posScalar = na(klyF) ? 1.0 : math.max(math.min(klyFrac * klyF, klyMax), 0.0)"],t.s)
