B.cZc=s(['ivvA = input.symbol("NASDAQ:TLT", "Basket asset 1", group = "Sizing")','ivvB = input.symbol("AMEX:GLD", "Basket asset 2", group = "Sizing")','ivvLen = input.int(63, "Volatility window (bars)", minval = 2, group = "Sizing")','ivvMax = input.float(1.0, "Max position scalar", minval = 0, group = "Sizing")'],t.s)
B.cNp=s(["ivvC = close[1]","ivvPa = f_sec(ivvA)","ivvPb = f_sec(ivvB)","ivvV0 = ta.stdev(math.log(ivvC / ivvC[1]), ivvLen)","ivvVa = ta.stdev(math.log(ivvPa / ivvPa[1]), ivvLen)","ivvVb = ta.stdev(math.log(ivvPb / ivvPb[1]), ivvLen)","ivvW = ivvV0 > 0 and ivvVa > 0 and ivvVb > 0 ? (1.0 / ivvV0) / (1.0 / ivvV0 + 1.0 / ivvVa + 1.0 / ivvVb) : na","posScalar = na(ivvW) ? 1.0 : math.max(math.min(3.0 * ivvW, ivvMax), 0.0)"],t.s)
