B.djj=s(['shpLen = input.int(252, "Sharpe window (bars)", minval = 2, group = "Formula library")','shpRef = input.float(2.0, "Sharpe for a full vote", minval = 0.1, group = "Formula library")'],t.s)
B.cTr=s(["shpRet = math.log(close / close[1])","shpMu = ta.sma(shpRet, shpLen)","shpSd = ta.stdev(shpRet, shpLen)","shpRatio = shpSd > 0 ? shpMu / shpSd * math.sqrt(252) : na","score_rsharpe = na(shpRatio) ? na : math.max(math.min(shpRatio / shpRef, 1.0), -1.0)"],t.s)
