B.cTt=s(['sorLen = input.int(252, "Sortino window (bars)", minval = 2, group = "Formula library")','sorRef = input.float(3.0, "Sortino for a full vote", minval = 0.1, group = "Formula library")'],t.s)
B.cJO=s(["sorRet = math.log(close / close[1])","sorMu = ta.sma(sorRet, sorLen)","sorNeg = na(sorRet) ? na : math.min(sorRet, 0.0)","sorDd = math.sqrt(ta.sma(sorNeg * sorNeg, sorLen))","score_rsortino = na(sorMu) or na(sorDd) ? na : sorDd > 0 ? math.max(math.min(sorMu / sorDd * math.sqrt(252) / sorRef, 1.0), -1.0) : sorMu > 0 ? 1.0 : 0.0"],t.s)
