B.dc0=s(["calOk = not na(ta.sma(close, calLen + 1))","calAnn = math.pow(close / close[calLen], 252.0 / calLen) - 1.0","float calMdd = na","if calOk","    float calPk = close[calLen]","    float calDd = 0.0","    for i = calLen to 0","        calPk := math.max(calPk, close[i])","        calDd := math.max(calDd, 1.0 - close[i] / calPk)","    calMdd := calDd","score_rcalmar = na(calMdd) or na(calAnn) ? na : calMdd > 0 ? math.max(math.min(calAnn / calMdd / calRef, 1.0), -1.0) : calAnn > 0 ? 1.0 : 0.0"],t.s)
