B.ewe=new A.b(B.dz,['Green price = the score says "up-trend", red = "down-trend".','\ub179\uc0c9 \uac00\uaca9 = \uc810\uc218\uac00 "\uc0c1\uc2b9 \ucd94\uc138", \ube68\uac04\uc0c9 = "\ud558\ub77d \ucd94\uc138"\ub77c\ub294 \ub73b\uc785\ub2c8\ub2e4.',"\u4ef7\u683c\u4e3a\u7eff\u8272 = \u8bc4\u5206\u5224\u65ad\u201c\u4e0a\u5347\u8d8b\u52bf\u201d,\u7ea2\u8272 = \u201c\u4e0b\u964d\u8d8b\u52bf\u201d\u3002","\u7dd1\u306e\u4fa1\u683c = \u30b9\u30b3\u30a2\u304c\u300c\u4e0a\u6607\u30c8\u30ec\u30f3\u30c9\u300d\u3001\u8d64 = \u300c\u4e0b\u964d\u30c8\u30ec\u30f3\u30c9\u300d\u306e\u5224\u5b9a\u3067\u3059\u3002","Groene koers = de score zegt 'opwaartse trend', rood = 'neerwaartse trend'."],t.w)
B.ewA=new A.b(B.dz,["The \u25b2\u25bc marks under the middle pane are the moments a strategy would buy or sell.","\uac00\uc6b4\ub370 \ucc3d\uc758 \u25b2\u25bc \ud45c\uc2dc\uac00 \uc804\ub7b5\uc774 \uc0ac\uace0\ud30c\ub294 \uc21c\uac04\uc785\ub2c8\ub2e4.","\u4e2d\u95f4\u7a97\u683c\u4e0b\u65b9\u7684\u25b2\u25bc\u6807\u8bb0,\u662f\u7b56\u7565\u4e70\u5165\u6216\u5356\u51fa\u7684\u65f6\u70b9\u3002","\u4e2d\u592e\u30da\u30a4\u30f3\u306e\u4e0b\u306e\u25b2\u25bc\u30de\u30fc\u30af\u304c\u3001\u6226\u7565\u304c\u58f2\u8cb7\u3059\u308b\u30bf\u30a4\u30df\u30f3\u30b0\u3067\u3059\u3002","De \u25b2\u25bc-markeringen onder het middelste paneel zijn de momenten waarop een strategie zou kopen of verkopen."],t.w)
B.ewK=new A.b(B.dz,["Scroll on the chart to zoom, drag to pan, double-tap to reset.","\ucc28\ud2b8\uc5d0\uc11c \uc2a4\ud06c\ub864 = \ud655\ub300, \ub4dc\ub798\uadf8 = \uc774\ub3d9, \ub354\ube14\ud0ed = \ucd08\uae30\ud654.","\u5728\u56fe\u8868\u4e0a\u6eda\u52a8 = \u7f29\u653e,\u62d6\u52a8 = \u5e73\u79fb,\u53cc\u51fb = \u590d\u4f4d\u3002","\u30c1\u30e3\u30fc\u30c8\u4e0a\u3067\u30b9\u30af\u30ed\u30fc\u30eb = \u30ba\u30fc\u30e0\u3001\u30c9\u30e9\u30c3\u30b0 = \u79fb\u52d5\u3001\u30c0\u30d6\u30eb\u30bf\u30c3\u30d7 = \u30ea\u30bb\u30c3\u30c8\u3002","Scrol op de grafiek om te zoomen, sleep om te verschuiven, dubbeltik om te resetten."],t.w)
B.ew3=new A.b(B.dz,["Blue beating orange in the bottom pane = trend-following beat buy-and-hold here.","\ud558\ub2e8 \ucc3d\uc5d0\uc11c \ud30c\ub780 \uc120\uc774 \uc8fc\ud669 \uc120\uc744 \uc774\uae30\uba74 \ucd94\uc138\ucd94\uc885\uc774 \ubcf4\uc720\ub97c \uc774\uae34 \uac83\uc785\ub2c8\ub2e4.","\u5e95\u90e8\u7a97\u683c\u4e2d\u84dd\u7ebf\u8dd1\u8d62\u6a59\u7ebf = \u8d8b\u52bf\u8ddf\u8e2a\u5728\u8fd9\u91cc\u8dd1\u8d62\u4e86\u4e70\u5165\u5e76\u6301\u6709\u3002","\u4e0b\u6bb5\u30da\u30a4\u30f3\u3067\u9752\u3044\u7dda\u304c\u30aa\u30ec\u30f3\u30b8\u3092\u4e0a\u56de\u308c\u3070\u3001\u30c8\u30ec\u30f3\u30c9\u30d5\u30a9\u30ed\u30fc\u304c\u8cb7\u3044\u6301\u3061\u306b\u52dd\u3063\u305f\u3068\u3044\u3046\u3053\u3068\u3067\u3059\u3002","Blauw dat oranje verslaat in het onderste paneel = trendvolgen versloeg hier kopen-en-vasthouden."],t.w)
B.ews=new A.b(B.dz,["My first chart","\ub098\uc758 \uccab \ucc28\ud2b8","\u6211\u7684\u7b2c\u4e00\u5f20\u56fe\u8868","\u306f\u3058\u3081\u3066\u306e\u30c1\u30e3\u30fc\u30c8","Mijn eerste grafiek"],t.w)
B.ewi=new A.b(B.dz,['A price chart with a "market mood" score under it, and a test of whether following that mood would have beaten just holding. Demo data, so nothing is real yet \u2014 play freely.','\uac00\uaca9 \ucc28\ud2b8 \uc544\ub798\uc5d0 "\uc2dc\uc7a5 \ubd84\uc704\uae30" \uc810\uc218\uac00 \ud45c\uc2dc\ub418\uace0, \uadf8 \ubd84\uc704\uae30\ub97c \ub530\ub790\ub2e4\uba74 \ub2e8\uc21c \ubcf4\uc720\ubcf4\ub2e4 \ub098\uc558\uc744\uc9c0 \uac80\uc99d\ud569\ub2c8\ub2e4. \ub370\ubaa8 \ub370\uc774\ud130\uc774\ubbc0\ub85c \uc544\ubb34\uac83\ub3c4 \uc2e4\uc81c\uac00 \uc544\ub2d9\ub2c8\ub2e4 \u2014 \uc790\uc720\ub86d\uac8c \ub9cc\uc838\ubcf4\uc138\uc694.',"\u4ef7\u683c\u56fe\u4e0b\u65b9\u663e\u793a\u201c\u5e02\u573a\u60c5\u7eea\u201d\u8bc4\u5206,\u5e76\u68c0\u9a8c\u5982\u679c\u8ddf\u968f\u8fd9\u79cd\u60c5\u7eea,\u662f\u5426\u80fd\u8dd1\u8d62\u5355\u7eaf\u6301\u6709\u3002\u4f7f\u7528\u6f14\u793a\u6570\u636e,\u4e00\u5207\u90fd\u8fd8\u4e0d\u662f\u771f\u5b9e\u7684 \u2014 \u8bf7\u653e\u5fc3\u968f\u610f\u5c1d\u8bd5\u3002","\u4fa1\u683c\u30c1\u30e3\u30fc\u30c8\u306e\u4e0b\u306b\u300c\u5e02\u5834\u30e0\u30fc\u30c9\u300d\u30b9\u30b3\u30a2\u304c\u8868\u793a\u3055\u308c\u3001\u305d\u306e\u30e0\u30fc\u30c9\u306b\u5f93\u3063\u3066\u3044\u305f\u3089\u5358\u7d14\u306a\u8cb7\u3044\u6301\u3061\u3088\u308a\u826f\u304b\u3063\u305f\u304b\u3092\u691c\u8a3c\u3057\u307e\u3059\u3002\u30c7\u30e2\u30c7\u30fc\u30bf\u306a\u306e\u3067\u3001\u307e\u3060\u4f55\u3082\u672c\u7269\u3067\u306f\u3042\u308a\u307e\u305b\u3093 \u2014 \u81ea\u7531\u306b\u8a66\u3057\u3066\u307f\u3066\u304f\u3060\u3055\u3044\u3002","Een koersgrafiek met daaronder een 'marktstemming'-score, plus een test of het volgen van die stemming beter was geweest dan simpelweg aanhouden. Demodata, dus niets is nog echt \u2014 experimenteer vrijuit."],t.w)
B.ewM=new A.b(B.dz,["No experience needed: each one sets up the whole app and tells you how to read it.","\uacbd\ud5d8\uc774 \uc5c6\uc5b4\ub3c4 \ub429\ub2c8\ub2e4: \uac01 \ud56d\ubaa9\uc774 \uc571 \uc804\uccb4\ub97c \uc124\uc815\ud558\uace0 \uc77d\ub294 \ubc95\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4.","\u65e0\u9700\u4efb\u4f55\u7ecf\u9a8c:\u6bcf\u4e00\u9879\u90fd\u4f1a\u914d\u7f6e\u6574\u4e2a\u5e94\u7528,\u5e76\u6559\u4f60\u5982\u4f55\u89e3\u8bfb\u3002","\u7d4c\u9a13\u306f\u4e0d\u8981\u3067\u3059: \u5404\u9805\u76ee\u304c\u30a2\u30d7\u30ea\u5168\u4f53\u3092\u8a2d\u5b9a\u3057\u3001\u8aad\u307f\u65b9\u307e\u3067\u6559\u3048\u3066\u304f\u308c\u307e\u3059\u3002","Geen ervaring nodig: elk item richt de hele app in en legt uit hoe je hem leest."],t.w)
B.ewm=new A.b(B.dz,["Guided setups \u2014 start here","\uac00\uc774\ub4dc \uc124\uc815 \u2014 \uc5ec\uae30\uc11c \uc2dc\uc791\ud558\uc138\uc694","\u5f15\u5bfc\u5f0f\u8bbe\u7f6e \u2014 \u4ece\u8fd9\u91cc\u5f00\u59cb","\u30ac\u30a4\u30c9\u4ed8\u304d\u30bb\u30c3\u30c8\u30a2\u30c3\u30d7 \u2014 \u3053\u3053\u304b\u3089\u59cb\u3081\u307e\u3057\u3087\u3046","Begeleide configuraties \u2014 begin hier"],t.w)
B.fkA=new A.b(B.aE,[u.fg,"\uad50\uc721\uc6a9 \ub3c4\uad6c\uc774\uba70 \ud22c\uc790 \uc870\uc5b8\uc774 \uc544\ub2d9\ub2c8\ub2e4. \ubbf8\ub9ac\ubcf4\uae30\ub294 \ud569\uc131 \ub370\ubaa8 \ub370\uc774\ud130\ub85c \uc2e4\ud589\ub429\ub2c8\ub2e4.","Herramienta educativa, no es asesoramiento de inversi\xf3n. La vista previa usa datos de demostraci\xf3n sint\xe9ticos.","\u6559\u80b2\u5de5\u5177,\u5e76\u975e\u6295\u8d44\u5efa\u8bae\u3002\u9884\u89c8\u4f7f\u7528\u5408\u6210\u7684\u6f14\u793a\u6570\u636e\u8fd0\u884c\u3002","\u6559\u80b2\u7528\u30c4\u30fc\u30eb\u3067\u3042\u308a\u3001\u6295\u8cc7\u52a9\u8a00\u3067\u306f\u3042\u308a\u307e\u305b\u3093\u3002\u30d7\u30ec\u30d3\u30e5\u30fc\u306f\u5408\u6210\u30c7\u30e2\u30c7\u30fc\u30bf\u3067\u52d5\u4f5c\u3057\u307e\u3059\u3002","Lernwerkzeug \u2013 keine Anlageberatung. Die Vorschau l\xe4uft auf synthetischen Demodaten.","Educatief hulpmiddel \u2014 geen beleggingsadvies. De preview draait op synthetische demodata."],t.w)
