B.dUj=new A.b(B.aT,['Delete sheet "{name}"?','\xbfEliminar la hoja "{name}"?',"Supprimer la feuille \xab {name} \xbb ?","Blatt \u201e{name}\u201c l\xf6schen?",'Eliminare il foglio "{name}"?','Excluir a folha "{name}"?','Blad "{name}" verwijderen?','Ta bort bladet "{name}"?',"Smazat list \u201e{name}\u201c?","\u0394\u03b9\u03b1\u03b3\u03c1\u03b1\u03c6\u03ae \u03c4\u03bf\u03c5 \u03c6\u03cd\u03bb\u03bb\u03bf\u03c5 \xab{name}\xbb;","Usun\u0105\u0107 arkusz \u201e{name}\u201d?","\u0412\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0430\u0440\u043a\u0443\u0448 \xab{name}\xbb?","\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u043b\u0438\u0441\u0442 \xab{name}\xbb?",'"{name}" sayfas\u0131 silinsin mi?','X\xf3a trang t\xednh "{name}"?','"{name}" \uc2dc\ud2b8\ub97c \uc0ad\uc81c\ud560\uae4c\uc694?',"\u30b7\u30fc\u30c8\u300c{name}\u300d\u3092\u524a\u9664\u3057\u307e\u3059\u304b?","\u5220\u9664\u5de5\u4f5c\u8868\u201c{name}\u201d?",'\u0936\u0940\u091f "{name}" \u0939\u091f\u093e\u090f\u0901?','\u062d\u0630\u0641 \u0627\u0644\u0648\u0631\u0642\u0629 "{name}"\u061f',"\u0628\u0631\u06af\u0647 \xab{name}\xbb \u062d\u0630\u0641 \u0634\u0648\u062f\u061f"],t.w)
B.dSK=new A.b(B.aT,["The sheet and everything on it will be deleted. You can undo this.","Se eliminar\xe1 la hoja y todo su contenido. Puedes deshacerlo.","La feuille et tout son contenu seront supprim\xe9s. Vous pouvez annuler.","Das Blatt und sein gesamter Inhalt werden gel\xf6scht. Du kannst das r\xfcckg\xe4ngig machen.","Il foglio e tutto il suo contenuto verranno eliminati. Puoi annullare.","A folha e todo o seu conte\xfado ser\xe3o exclu\xeddos. Voc\xea pode desfazer.","Het blad en alles erop wordt verwijderd. Je kunt dit ongedaan maken.","Bladet och allt p\xe5 det tas bort. Du kan \xe5ngra detta.","List a v\u0161e na n\u011bm bude smaz\xe1no. Akci lze vr\xe1tit.","\u03a4\u03bf \u03c6\u03cd\u03bb\u03bb\u03bf \u03ba\u03b1\u03b9 \u03cc\u03bb\u03bf \u03c4\u03bf \u03c0\u03b5\u03c1\u03b9\u03b5\u03c7\u03cc\u03bc\u03b5\u03bd\u03cc \u03c4\u03bf\u03c5 \u03b8\u03b1 \u03b4\u03b9\u03b1\u03b3\u03c1\u03b1\u03c6\u03bf\u03cd\u03bd. \u039c\u03c0\u03bf\u03c1\u03b5\u03af\u03c4\u03b5 \u03bd\u03b1 \u03c4\u03bf \u03b1\u03bd\u03b1\u03b9\u03c1\u03ad\u03c3\u03b5\u03c4\u03b5.","Arkusz i ca\u0142a jego zawarto\u015b\u0107 zostan\u0105 usuni\u0119te. Mo\u017cesz to cofn\u0105\u0107.","\u0410\u0440\u043a\u0443\u0448 \u0456 \u0432\u0435\u0441\u044c \u0439\u043e\u0433\u043e \u0432\u043c\u0456\u0441\u0442 \u0431\u0443\u0434\u0435 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043e. \u0426\u0435 \u043c\u043e\u0436\u043d\u0430 \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438.","\u041b\u0438\u0441\u0442 \u0438 \u0432\u0441\u0451 \u0435\u0433\u043e \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0435 \u0431\u0443\u0434\u0443\u0442 \u0443\u0434\u0430\u043b\u0435\u043d\u044b. \u042d\u0442\u043e \u043c\u043e\u0436\u043d\u043e \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c.","Sayfa ve \xfczerindeki her \u015fey silinecek. Bunu geri alabilirsiniz.","Trang t\xednh v\xe0 m\u1ecdi n\u1ed9i dung tr\xean \u0111\xf3 s\u1ebd b\u1ecb x\xf3a. B\u1ea1n c\xf3 th\u1ec3 ho\xe0n t\xe1c.","\uc2dc\ud2b8\uc640 \uadf8 \uc548\uc758 \ubaa8\ub4e0 \ub0b4\uc6a9\uc774 \uc0ad\uc81c\ub429\ub2c8\ub2e4. \uc2e4\ud589 \ucde8\uc18c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\u30b7\u30fc\u30c8\u3068\u305d\u306e\u5185\u5bb9\u306f\u3059\u3079\u3066\u524a\u9664\u3055\u308c\u307e\u3059\u3002\u5143\u306b\u623b\u305b\u307e\u3059\u3002","\u8be5\u5de5\u4f5c\u8868\u53ca\u5176\u6240\u6709\u5185\u5bb9\u5c06\u88ab\u5220\u9664\u3002\u53ef\u4ee5\u64a4\u9500\u3002","\u0936\u0940\u091f \u0914\u0930 \u0909\u0938 \u092a\u0930 \u092e\u094c\u091c\u0942\u0926 \u0938\u092c \u0915\u0941\u091b \u0939\u091f \u091c\u093e\u090f\u0917\u093e\u0964 \u0906\u092a \u0907\u0938\u0947 \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964","\u0633\u064a\u062a\u0645 \u062d\u0630\u0641 \u0627\u0644\u0648\u0631\u0642\u0629 \u0648\u0643\u0644 \u0645\u0627 \u0639\u0644\u064a\u0647\u0627. \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0630\u0644\u0643.","\u0628\u0631\u06af\u0647 \u0648 \u0647\u0645\u0647 \u0645\u062d\u062a\u0648\u0627\u06cc \u0622\u0646 \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0627\u06cc\u0646 \u06a9\u0627\u0631 \u0631\u0627 \u0648\u0627\u06af\u0631\u062f \u06a9\u0646\u06cc\u062f."],t.w)
B.dSo=new A.b(B.aT,["A sheet needs a name.","Una hoja necesita un nombre.","Une feuille doit avoir un nom.","Ein Blatt braucht einen Namen.","Un foglio deve avere un nome.","Uma folha precisa de um nome.","Een blad heeft een naam nodig.","Ett blad beh\xf6ver ett namn.","List mus\xed m\xedt n\xe1zev.","\u0388\u03bd\u03b1 \u03c6\u03cd\u03bb\u03bb\u03bf \u03c7\u03c1\u03b5\u03b9\u03ac\u03b6\u03b5\u03c4\u03b1\u03b9 \u03cc\u03bd\u03bf\u03bc\u03b1.","Arkusz musi mie\u0107 nazw\u0119.","\u0410\u0440\u043a\u0443\u0448 \u043f\u043e\u0432\u0438\u043d\u0435\u043d \u043c\u0430\u0442\u0438 \u043d\u0430\u0437\u0432\u0443.","\u0423 \u043b\u0438\u0441\u0442\u0430 \u0434\u043e\u043b\u0436\u043d\u043e \u0431\u044b\u0442\u044c \u0438\u043c\u044f.","Sayfan\u0131n bir ad\u0131 olmal\u0131.","Trang t\xednh c\u1ea7n c\xf3 t\xean.","\uc2dc\ud2b8\uc5d0\ub294 \uc774\ub984\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","\u30b7\u30fc\u30c8\u306b\u306f\u540d\u524d\u304c\u5fc5\u8981\u3067\u3059\u3002","\u5de5\u4f5c\u8868\u9700\u8981\u540d\u79f0\u3002","\u0936\u0940\u091f \u0915\u093e \u0928\u093e\u092e \u0939\u094b\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964","\u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0644\u0644\u0648\u0631\u0642\u0629 \u0627\u0633\u0645.","\u0628\u0631\u06af\u0647 \u0628\u0627\u06cc\u062f \u0646\u0627\u0645 \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u062f."],t.w)
B.dTF=new A.b(B.aT,['There is already a sheet named "{name}".','Ya hay una hoja llamada "{name}".',"Il existe d\xe9j\xe0 une feuille nomm\xe9e \xab {name} \xbb.","Es gibt bereits ein Blatt namens \u201e{name}\u201c.",'Esiste gi\xe0 un foglio chiamato "{name}".','J\xe1 existe uma folha chamada "{name}".','Er is al een blad met de naam "{name}".','Det finns redan ett blad som heter "{name}".',"List s n\xe1zvem \u201e{name}\u201c u\u017e existuje.","\u03a5\u03c0\u03ac\u03c1\u03c7\u03b5\u03b9 \u03ae\u03b4\u03b7 \u03c6\u03cd\u03bb\u03bb\u03bf \u03bc\u03b5 \u03cc\u03bd\u03bf\u03bc\u03b1 \xab{name}\xbb.","Arkusz o nazwie \u201e{name}\u201d ju\u017c istnieje.","\u0410\u0440\u043a\u0443\u0448 \u0456\u0437 \u043d\u0430\u0437\u0432\u043e\u044e \xab{name}\xbb \u0432\u0436\u0435 \u0456\u0441\u043d\u0443\u0454.","\u041b\u0438\u0441\u0442 \u0441 \u0438\u043c\u0435\u043d\u0435\u043c \xab{name}\xbb \u0443\u0436\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442.",'"{name}" adl\u0131 bir sayfa zaten var.','\u0110\xe3 c\xf3 trang t\xednh t\xean "{name}".','"{name}" \uc2dc\ud2b8\uac00 \uc774\ubbf8 \uc788\uc2b5\ub2c8\ub2e4.',"\u300c{name}\u300d\u3068\u3044\u3046\u540d\u524d\u306e\u30b7\u30fc\u30c8\u306f\u65e2\u306b\u3042\u308a\u307e\u3059\u3002","\u5df2\u5b58\u5728\u540d\u4e3a\u201c{name}\u201d\u7684\u5de5\u4f5c\u8868\u3002",'"{name}" \u0928\u093e\u092e \u0915\u0940 \u0936\u0940\u091f \u092a\u0939\u0932\u0947 \u0938\u0947 \u0939\u0948\u0964','\u062a\u0648\u062c\u062f \u0648\u0631\u0642\u0629 \u0628\u0627\u0633\u0645 "{name}" \u0628\u0627\u0644\u0641\u0639\u0644.',"\u0628\u0631\u06af\u0647\u200c\u0627\u06cc \u0628\u0627 \u0646\u0627\u0645 \xab{name}\xbb \u0627\u0632 \u0642\u0628\u0644 \u0648\u062c\u0648\u062f \u062f\u0627\u0631\u062f."],t.w)
B.dSj=new A.b(B.aT,["Sheet names can be at most 31 characters.","Los nombres de hoja pueden tener como m\xe1ximo 31 caracteres.","Les noms de feuille comptent au plus 31 caract\xe8res.","Blattnamen d\xfcrfen h\xf6chstens 31 Zeichen lang sein.","I nomi dei fogli possono avere al massimo 31 caratteri.","Nomes de folha podem ter no m\xe1ximo 31 caracteres.","Bladnamen mogen maximaal 31 tekens lang zijn.","Bladnamn f\xe5r vara h\xf6gst 31 tecken.","N\xe1zev listu m\u016f\u017ee m\xedt nejv\xfd\u0161e 31 znak\u016f.","\u03a4\u03b1 \u03bf\u03bd\u03cc\u03bc\u03b1\u03c4\u03b1 \u03c6\u03cd\u03bb\u03bb\u03c9\u03bd \u03ad\u03c7\u03bf\u03c5\u03bd \u03ad\u03c9\u03c2 31 \u03c7\u03b1\u03c1\u03b1\u03ba\u03c4\u03ae\u03c1\u03b5\u03c2.","Nazwa arkusza mo\u017ce mie\u0107 najwy\u017cej 31 znak\xf3w.","\u041d\u0430\u0437\u0432\u0430 \u0430\u0440\u043a\u0443\u0448\u0430 \u043c\u043e\u0436\u0435 \u043c\u0430\u0442\u0438 \u0449\u043e\u043d\u0430\u0439\u0431\u0456\u043b\u044c\u0448\u0435 31 \u0441\u0438\u043c\u0432\u043e\u043b.","\u0418\u043c\u044f \u043b\u0438\u0441\u0442\u0430 \u043c\u043e\u0436\u0435\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043d\u0435 \u0431\u043e\u043b\u0435\u0435 31 \u0441\u0438\u043c\u0432\u043e\u043b\u0430.","Sayfa adlar\u0131 en fazla 31 karakter olabilir.","T\xean trang t\xednh t\u1ed1i \u0111a 31 k\xfd t\u1ef1.","\uc2dc\ud2b8 \uc774\ub984\uc740 \ucd5c\ub300 31\uc790\uc785\ub2c8\ub2e4.","\u30b7\u30fc\u30c8\u540d\u306f31\u6587\u5b57\u307e\u3067\u3067\u3059\u3002","\u5de5\u4f5c\u8868\u540d\u79f0\u6700\u591a 31 \u4e2a\u5b57\u7b26\u3002","\u0936\u0940\u091f \u0915\u0947 \u0928\u093e\u092e \u092e\u0947\u0902 \u0905\u0927\u093f\u0915\u0924\u092e 31 \u0905\u0915\u094d\u0937\u0930 \u0939\u094b \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964","\u064a\u0645\u0643\u0646 \u0623\u0646 \u064a\u062a\u0643\u0648\u0646 \u0627\u0633\u0645 \u0627\u0644\u0648\u0631\u0642\u0629 \u0645\u0646 31 \u062d\u0631\u0641\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0643\u062b\u0631.","\u0646\u0627\u0645 \u0628\u0631\u06af\u0647 \u062d\u062f\u0627\u06a9\u062b\u0631 \u06f3\u06f1 \u0646\u0648\u06cc\u0633\u0647 \u0627\u0633\u062a."],t.w)
