B.eWU=new A.b(B.h,['Leadership rotates; strong relative strength can reverse sharply. For bonds and FX, "vs SPY" only says which did better, not why.'],t.w)
B.fcv=new A.b(B.h,["The past year's return, skipping the latest month \u2014 a classic momentum measure."],t.w)
