B.eyX=new A.b(B.h,["mean ETF score + regime tilt; \u2265 +20 Favoured, \u2264 \u221220 Avoid, else Neutral. Tilts: stress \u2014 equities \u221215, credit \u221220, bonds +15, commodities \u221210, dollar +10, crypto \u221215, real estate \u221210; slowdown \u2014 equities \u221210, credit \u221210, bonds +15, commodities \u221210, real estate \u22125; late cycle \u2014 equities \u22125, bonds \u22125, commodities +10; expansion \u2014 equities +10, credit +5, commodities +5, bonds \u221210, dollar \u22125, crypto +5."],t.w)
B.f5c=new A.b(B.h,["The tilt table is a simple rule of thumb, kept small on purpose. With no live macro readings there is no tilt."],t.w)
