B.hic=new A.C("id",B.T,"This node's handle \u2014 used as the PageStorage key so the selected segment survives a structural rebuild (e.g. a window resize flipping the phone/desktop layout branch). An id-less segments still restores its index across such a rebuild via a fallback key derived from the segment labels, but an explicit id is more robust if segments are added/removed/relabelled.",B.k,null,!1)
B.fZ_=new A.C("segments",B.a_,"List of { label, child, icon?, action? } segments. An optional `action` is fired when the person switches TO that segment (never on first build).",B.k,null,!1)
B.h_I=new A.C("initial",B.aM,"Index of the segment shown before the person picks one (default 0). A remembered pick (PageStorage) still wins.",B.k,null,!1)
B.hiD=new A.C("fill",B.ab,'Fill the (bounded) parent and hand the active tab the remaining height via Expanded \u2014 needed when a tab hosts a height-filling surface (a bubl board, notepad, nested explorer, or a map/table/chart asking for height:"fill"). The active tab also republishes its own bounded height, so a height:"fill" child fills the TAB exactly (not the whole body) and pans internally. As a ROOT body it also takes the exact viewport height instead of the page-scroll fallback. Default off: segments shrink-wrap and drop into a scroll view.',B.k,null,!1)
B.hgg=new A.C("chips",B.ab,"Render the header as a compact row of small icon chips instead of full FilledButton text pills. Each segment map may carry an `icon` (a nav icon-name string, same registry as tab-bar icons); without one the chip falls back to the label's first letter in a small circle. The active chip is tinted, inactive chips are faint, and the current segment's label is shown next to the strip. Default off: the classic text-pill header (byte-identical to before this key existed).",B.k,null,!1)
B.fW0=new A.C("swipe",B.ab,"With `chips:true`, a horizontal drag ANYWHERE ON THE CHIP STRIP (never the body) advances/retreats the active segment, with an animated slide transition. Deliberately scoped to the strip \u2014 never a body-wide PageView \u2014 so a one-finger drag inside the active tab (a bubl board drag/marquee, an outline scroll, a canvas pan) is never intercepted. Default off.",B.k,null,!1)
B.hf8=new A.C("transition",B.T,'With `swipe:true`, how the active tab\'s body animates on switch: "fade" (default) \u2014 a capped 150ms cross-fade, incoming child on top so a heavy outgoing child (a gantt, a big table) never reads as "stuck" over the new one \u2014 or "none" \u2014 an instant swap with no AnimatedSwitcher at all, for content sensitive to any transition cost. Ignored without `swipe:true`.',B.k,null,!1)
B.h_X=new A.C("scrollBody",B.ab,'The active tab\'s body scrolls INSIDE the bounded pane instead of being clipped, while the header/tab-bar stays docked above it \u2014 for a tab whose content (a list/column of rows) is naturally taller than the available slot. Implies `fill` (needs the same bounded pane); combine with a fixed screen/parent height, not with a child asking `height:"fill"` (that child would lose its bounded pane \u2014 use `fill` alone for that case). Default off: byte-identical to before this key existed.',B.k,null,!1)
B.fTo=new A.C("dense",B.ab,"Compact tab strip: 2px outer inset and a 32px minimum height instead of the full M3 FilledButton size \u2014 matches a `pick` segmented control's density so the two read as one control language.",B.k,null,!1)
B.h1H=new A.C("color",B.T,"Pin the inactive tab fill (hex) instead of inheriting the theme's DERIVED secondaryContainer, which can land on an unrelated hue.",B.k,null,!1)
B.hbe=new A.C("textColor",B.T,"Pin the inactive tab label color (hex).",B.k,null,!1)
B.h4V=new A.C("borderColor",B.T,"Pin an outline color (hex) on every tab.",B.k,null,!1)
B.h8o=new A.C("selectedColor",B.T,"Pin the ACTIVE tab fill (hex).",B.k,null,!1)
B.he2=new A.C("selectedTextColor",B.T,"Pin the ACTIVE tab label color (hex).",B.k,null,!1)
B.hgP=new A.C("darkColor",B.T,"Dark-mode `color` override.",B.k,null,!1)
