B.h5e=new A.C("artboard",B.a_,"artboard-r1-1012. Optional `{width, height, label?}`: the region at the scene origin the drawing is FOR (e.g. a phone frame), drawn as an outlined sheet behind the content and used as the first-load fit target. Absent = no sheet.",B.k,null,!1)
B.h3k=new A.C("fidelity",B.bU,'How nodes RENDER (free layout): "auto" (default tinted card), "wireframe" (mono outline + white fill), or "themed" (each `kind` drawn as a real component \u2014 button/input/list/nav/image/text/section/frame).',B.a17,null,!1)
B.h1B=new A.C("confirmDelete",B.ab,'Ask to confirm before deleting a node (also honors the app-wide "confirm before deleting" setting).',B.k,null,!1)
