B.h_6=new A.C("allowAddStage",B.ab,'Graph layout: show the "add stage" (+) affordance in the milestone header row (default on when `milestoneOrder` is NOT explicitly configured \u2014 stages are then data-derived and lexically ordered, so a new milestone value can be minted to sort strictly between two existing ones). When `milestoneOrder` IS configured, only "add at end" is offered (inserting mid-list would require editing the configured array, not a data write).',B.k,null,!1)
B.fWJ=new A.C("allowInsertStep",B.ab,'Graph layout: show the "Insert step here" action on the selection toolbar when exactly one edge is selected (default true; needs `milestoneColumn`). Inserting adds a new step into the edge\'s stage (or a freshly minted midpoint stage) and rewires the edge around it; refused with a toast if it would create a cycle.',B.k,null,!1)
B.h0P=new A.C("dataTable",B.b1,"Data overlay: a second table rendered as DATA nodes into the same staged flow (graph layout only). Absent = no data overlay.",B.k,null,!1)
B.h0E=new A.C("dataStageColumn",B.K,"Data overlay: which stage (a `milestoneColumn` value) a data row attaches to. Dragging a data node between stages writes this column only \u2014 never x/y, never an edge row.",B.k,null,!1)
B.hiu=new A.C("dataIntentColumn",B.K,"Data overlay: column rendered as a small badge on the data node \u2014 WHY the data is there (e.g. source / input / derived / output).",B.k,null,!1)
B.aW_=new A.C("dataLabelColumn",B.K,'Data overlay: display-name column for a data node (default falls back to a "label" or "name" column on `dataTable`).',B.k,null,!1)
B.h7R=new A.C("dataLinkColumn",B.K,"Data overlay: id of the step row (in `nodesTable`) a data row feeds. When set, a light PAINTED-ONLY line is drawn from the data node to that step \u2014 no row is written to `edgesTable`, so a deleted step just makes the line vanish, never an orphaned edge.",B.k,null,!1)
B.hdD=new A.C("filter",B.a_,"Opt-in row scope for `nodesTable` (and, unless `dataFilter` overrides it, `dataTable` too) \u2014 same shape as `bubl`'s filter: {column, value} or {column, in:[...]}; `value`/each `in` entry may be a token ($selected:<table>, $rowId, $playerId). Absent = all rows (unchanged behavior); resolved value/set EMPTY = no rows, never all. A node/data row freshly created while a resolved scalar {column, value} filter is scoping the view is stamped with that column:value so it stays in scope.",B.k,null,!1)
B.aVE=new A.C("dataFilter",B.a_,"Opt-in override of `filter` for `dataTable` only, when the data table scopes on a different column than `nodesTable`. Same shape as `filter`. Absent = `dataTable` falls back to `filter`.",B.k,null,!1)
B.aW7=new A.C("scopeColumn",B.K,"Opt-in ENGINE scope filter for `nodesTable` \u2014 the same convention the `explorer` node's `scopeColumn` reads via `activeScope`, so a canvas bound to a scoped table (e.g. a File > Board > nodes chain) shows only the open file/board's nodes even when no ancestor explorer for that hop happened to mount. Distinct from `filter` (a token-resolved value/set filter); the two may combine. Absent = unchanged behavior.",B.k,null,!1)
