B.fw1=new A.dv("annotate","Screenshot markup pad: paste, ink, label, copy regions.",B.cXj,!1)
B.h3d=new A.C("columns",B.mD,'Columns to show (default = all). An entry may be a bare column name OR an object { column, format: currency|percent|compact|number|relative|duration|epochSeconds|epochMillis, decimals?, prefix?, inputUnit?: seconds|millis, style?: date|time|dateTime|relative, valueLabels?: {rawValue: words} (shows words for a raw value, key "" = empty), lines?: 1-6 (wrap long text to N lines), flex?: relative column width } \u2014 a formatted column renders read-only (sorting still uses the stored number). `relative` humanizes an ISO-8601 timestamp column as "3m ago"/"2h ago"/"3d ago"; `duration` shows seconds (or `inputUnit:"millis"`) as a compact localized "3d 4h 12m" / "4h 12m" / "12m 5s" (negative \u2192 "\u2014"); `epochSeconds`/`epochMillis` show a Unix timestamp as localized device-time-zone text, `style` = date | time | dateTime (default) | relative. Non-numeric values pass through untouched.',B.k,null,!1)
B.aWh=new A.C("height",B.T,'Optional height (scrolls internally). Accepts a number (logical px), "fill" (the full available body height, scrolling/panning internally), or "<frac>fill" (e.g. "0.55fill").',B.k,null,!1)
B.hf0=new A.C("hideWhenEmpty",B.ab,"Opt-in: render nothing (no empty-state panel) when the table has no rows to show. Unset = the usual empty surface.",B.k,null,!1)
B.h7b=new A.C("pageSize",B.aM,"Opt-in paging (tablepage-1110): show N rows per page with a Previous/Next pager when there are more. The table takes its natural height (ignores `height`) and has NO inner vertical scroller, so the page always scrolls over it. Unset = historic fixed-height body.",B.k,null,!1)
B.fWe=new A.C("rowDetail",B.T,'Opt-in (tablepage-1110): "readOnly" makes tapping a row open a read-only popup with every shown column in full (no editing, no row action needed). Unset = the row action (or nothing).',B.k,null,!1)
B.dfS=s(["scroll","cards"],t.s)
B.aVy=new A.C("overflow",B.bU,'Phone behavior for a grid wider than the pane. "scroll" (default) keeps the grid and scrolls horizontally; "cards" swaps to a stacked card-per-row layout on a phone-width pane (still a grid when wide). Unset = "scroll" (byte-identical to the historic grid).',B.dfS,"Wide-grid overflow",!1)
B.h7O=new A.C("action",B.a_,"Row-handle action spec { fn, args }.",B.k,null,!1)
B.h8s=new A.C("filters",B.a_,"Column filtering is ALWAYS available on the table (long-press a header to open the shared, type-aware Add-filter editor \u2014 operator picker for text/number, relative/range for dates, is-any-of checklist for enum/reference). The leading header cell clears all filters (tap) and flips AND\u21c4OR combine mode (long-press). Filters are view-only, never persisted. This key is reserved for a future declarative seed.",B.k,null,!1)
B.hi0=new A.C("where",B.a_,'Opt-in (dufb-1017), view-only standing scope: {"column": "status", "in": ["done", "superseded"]} (or "equals", or "notIn" to exclude) keeps only matching rows; a LIST of such conditions ANDs them. Header filters still apply on top.',B.k,null,!1)
B.hgj=new A.C("sortBy",B.a_,'Opt-in (dufb-1017): default row order {"column": "finishedAt", "descending": true}; rows missing the value sort last.',B.k,null,!1)
B.h7A=new A.C("staleWhen",B.b1,"Name of a SOURCE table this table is derived from (e.g. a `results` table feeding a `metrics` rollup). When the source's newest `updatedAt` is more recent than this table's own newest `updatedAt`, a quiet \"stale \u2014 recalc?\" banner shows above the grid. Unset = no check, byte-identical render.",B.k,null,!1)
B.h1m=new A.C("showProvenance",B.ab,'Show a small read-only "source \xb7 fetched <relative time>" caption above the grid, drawn from the engine-internal provenance envelope auto-stamped by `importData`/`http` when they last landed rows in this table. Unset = no caption, byte-identical render.',B.k,null,!1)
B.h6M=new A.C("openActions",B.a_,'Extra compact trailing icon-buttons on each row, each { label, icon?, action } fired with the row injected (e.g. "Show on map" \u2192 focusRow chained with goto). Additive beside the leading row-handle action \u2014 row-tap is unchanged.',B.k,null,!1)
B.haw=new A.C("scopeColumn",B.K,"Opt-in ENGINE scope filter (see `BoardState.rowsForScoped`) \u2014 the same convention the `explorer` node's `scopeColumn` reads via `activeScope`, so a table bound to a scoped table (e.g. a File > Board > rows chain) shows only the open file/board's rows even when no ancestor explorer for that hop happened to mount. Absent = unchanged behavior.",B.k,null,!1)
