B.fTm=new A.C("tablePicker",B.ab,'Opt-in: false hides the "Table: <name>" picker row above the view (one-table spreadsheets). Absent/true = shown, unchanged.',B.k,null,!1)
B.h5L=new A.C("alignByType",B.ab,"Sheet mode, opt-in: cells without an explicit alignment right-align numbers and left-align text, like Excel. Absent = only number-formatted cells right-align.",B.k,null,!1)
