B.a5K=new A.C("configSource",B.bU,"Subscribe to the BOARD shared data config: \"board\" applies the dataset's shared filters/sort (and group-by where it applies) before this node's own refinements. Set by databoard applets so one control panel drives every view.",B.a18,null,!1)
B.haz=new A.C("cluster",B.ab,"Opt-in zoom-aware grid clustering of pins (default off = every row renders its own marker, unchanged). Groups nearby pins into count-badge clusters that split apart as the map zooms in \u2014 keeps a large table (e.g. thousands of geocoded rows) smooth at a zoomed-out view instead of rendering one widget per row.",B.k,null,!1)
B.fTX=new A.C("spiderfyThreshold",B.aM,"A cluster badge with at most this many members SPIDERFIES on tap (fans its pins out on short legs, each individually tappable) instead of glide-zooming in \u2014 default 4. Only used with cluster:true. Larger clusters still glide-zoom in as before.",B.k,null,!1)
B.hhE=new A.C("markerPulse",B.ab,"Opt-in gentle breathing highlight (repeating opacity pulse, ~1s period) on every visible non-clustered pin \u2014 default off = today's plain pin rendering, unchanged. Purely visual: tap targets, spiderfy and detailPopup are unaffected. Pairs with `databars`' `play` for a \"time wave\" read (the strip sweeps, only that slot's pins show, and they breathe).",B.k,null,!1)
B.h5a=new A.C("userLocation",B.ab,"Show a locate-me button and the user's current position on the map. Opt-in.",B.k,null,!1)
B.hiz=new A.C("zoom",B.aM,"Opening zoom (default 12 with pins, 7 without). A polygon overlay fits its own bounds instead. A focused row overrides to a campus-level zoom.",B.k,null,!1)
B.h_Y=new A.C("maxMarkers",B.aM,"Cap on pins rendered at once (default 500).",B.k,null,!1)
B.h66=new A.C("nameProperty",B.T,'GeoJSON feature property read as each polygon\'s name (default "name").',B.k,null,!1)
B.fUq=new A.C("choropleth",B.a_,'{ table?, valueColumn, nameColumn?, nameProperty?, color?, lowColor?, highColor?, filter? } \u2014 shade each GeoJSON feature from live rows (min-max normalized). Opt-in `filter`: { "column": <col>, "value": <val-or-token> } (or the set form { "column": <col>, "in": [..] }) scopes the choropleth table\'s rows before shading \u2014 same shape/token resolution as bubl\'s `filter` prop ($selected:<table> \u2192 the selectRow pick, $rowId, $playerId). Absent \u2192 all rows (unchanged); present but resolved to empty (e.g. nothing selected yet) \u2192 no rows shaded. `lowColor`+`highColor` (both required together, any color the theme resolver accepts) swap the default single-hue alpha ramp for a two-hue lerp (e.g. a green\u2192red style ramp); `color` alone keeps the legacy single-hue behavior unchanged.',B.k,null,!1)
B.hiL=new A.C("choroplethPick",B.ab,"Opt-in column picker for the choropleth: shows a chip row of paintable (numeric) columns above the map and re-aims choropleth.valueColumn at the tapped one. Requires `choropleth`.",B.k,null,!1)
B.fVi=new A.C("pickColumns",B.a_,"Restricts/orders the columns offered by the choropleth column-picker (needs choroplethPick: true); absent offers every numeric schema column (minus the join/name column).",B.k,null,!1)
B.h21=new A.C("featureFilterColumn",B.K,"Column (on featureFilterTable, default = table) whose live rows restrict which GeoJSON features draw.",B.k,null,!1)
B.h1F=new A.C("featureFilterTable",B.b1,"Table read for featureFilterColumn (defaults to `table`).",B.k,null,!1)
B.heD=new A.C("overlayToggle",B.a_,"Show a pins/polygon-overlay toggle chip; a String sets its label.",B.k,null,!1)
B.h9P=new A.C("linesAsset",B.T,"Bundled asset path of a GeoJSON FeatureCollection of LineString/MultiLineString features, drawn as polylines on top of the polygon/pin layers (e.g. a route network or a hub's shortest-path tree). Independent of geojsonAsset \u2014 a map can shade districts and draw routes at the same time.",B.k,null,!1)
B.h8V=new A.C("linesFilterProperty",B.T,"GeoJSON feature property (on linesAsset) matched against the CURRENT featureFilterColumn/featureFilterTable selection: only features whose property equals the selected value draw (nothing draws while unselected). Unset draws every line in the asset always, regardless of any selection \u2014 use this for an always-on network layer and set it for a per-selection route tree.",B.k,null,!1)
B.fVV=new A.C("lineColor",B.T,"Default polyline color \u2014 a ramp name (teal/coral/...) or #RRGGBB. A feature's own properties.stroke/properties.color overrides it.",B.k,null,!1)
B.fTh=new A.C("lineWidth",B.aM,"Polyline stroke width (default 2).",B.k,null,!1)
B.h6P=new A.C("linesToggle",B.a_,'Show a routes/polyline-overlay toggle chip controlling linesAsset2 (layer 1, linesAsset, has no manual toggle \u2014 its own linesFilterProperty/selection already gates visibility). Independent of overlayToggle (polygon layer only); a String sets its label (default "Routes").',B.k,null,!1)
B.h0n=new A.C("linesAsset2",B.T,"A SECOND, independent GeoJSON asset of LineString/MultiLineString features, drawn alongside linesAsset \u2014 lets one map combine a filtered layer (e.g. linesAsset + linesFilterProperty for a per-selection hub route tree) with an always-on one (e.g. linesAsset2 with no linesFilterProperty2, for a full network of links) at the same time, since one filter can't apply to only some features in one asset.",B.k,null,!1)
B.h2A=new A.C("linesFilterProperty2",B.T,"Same mechanism as linesFilterProperty, applied to linesAsset2 instead.",B.k,null,!1)
B.h4h=new A.C("lineColor2",B.T,"Default polyline color for linesAsset2 (default: the theme tertiary color, distinct from lineColor's default).",B.k,null,!1)
B.h2y=new A.C("lineWidth2",B.aM,"Polyline stroke width for linesAsset2 (default 2).",B.k,null,!1)
B.h4o=new A.C("basemap",B.ab,"Draw the street/tile basemap under the overlays (default true). false = a pure-overlay map (e.g. a world choropleth): no tile requests and no tile attribution.",B.k,null,!1)
B.he0=new A.C("background",B.T,"Map ground color (#RRGGBB) behind tiles/overlays \u2014 shows where no basemap is drawn (default light grey).",B.k,null,!1)
B.h2g=new A.C("pointList",B.ab,"Show a list of the plotted points below/beside the map (default on; set false to hide).",B.k,null,!1)
B.h1s=new A.C("listSubtitleColumn",B.K,'Column shown as the point-list row subtitle instead of the default raw "lat, lon". Opt-in \u2014 unset keeps the coordinate subtitle.',B.k,null,!1)
B.h36=new A.C("listTagColumn",B.K,"Column rendered as a small colored pill (trailing) on each point-list row, e.g. a genre/category tag. Opt-in \u2014 unset renders no pill.",B.k,null,!1)
B.fWy=new A.C("detailPopup",B.ab,'Opt-in select-then-act model: tapping a marker or a point-list row animates the camera to that point and shows a small in-map detail card (label + detailFields + an "Open website" button) instead of firing the row action immediately. Default off preserves today\'s exact behavior (row action fires straight from the tap).',B.k,null,!1)
B.fW7=new A.C("detailFields",B.a_,'Column names shown as extra lines in the detailPopup card (e.g. ["start","genreTag"]). Only used when detailPopup is true.',B.k,null,!1)
B.fZo=new A.C("linkColumn",B.K,'Column the detailPopup\'s "Open website" button reads its URL from (default "url"). Only used when detailPopup is true; a blank/absent value on the row hides the button. The button still fires the node\'s own action (default fn "openLink") so link-safety behavior is unchanged \u2014 this only tells it which column to read.',B.k,null,!1)
B.hd4=new A.C("layers",B.a_,"Opt-in ORDERED layer toolkit: a List of {id, label, kind, on?, ...kind-specific config reusing the legacy prop shapes (markers: colorColumn/colors/cluster/maxMarkers; network: linesAsset2/lineColor2/lineWidth2/linesFilterProperty2; choropleth: choropleth + optional pickColumns; geojson: geojsonAsset/geojson; labels: no extra config \u2014 toggles marker caption pills)}. 2+ entries render a compact collapsible layer panel (top-right) with a toggle per layer (choropleth rows also surface their metric-pick chips); toggle state is ephemeral/session-only, never written back to board JSON. Absent/under-2 \u2192 today's exact rendering (legacy flat props + overlayToggle/linesToggle chips), fully unchanged.",B.k,null,!1)
