B.h6j=new A.C("routingEdgesAsset",B.T,"Bundled GeoJSON asset of LineString/MultiLineString edges, each feature carrying routingFromProperty/routingToProperty node-id properties. Builds a headless Dijkstra graph (geo_routing.dart) used to snap pins to nodes and route between consecutive pins.",B.k,null,!1)
