B.fVN=new A.C("routingSpeedKmh",B.aM,"Network speed (km/h) used to derive an edge's travel time from its geometry length when the edge has no explicit weight (default 33.0 \u2014 match a bake's own model speed for consistent estimates).",B.k,null,!1)
