B.h_A=new A.C("snapMaxKm",B.aM,'Max straight-line distance (km) a pin may snap to the nearest routing node (default 1.5). Beyond this, that leg reports an honest "no nearby station" state instead of a fabricated route.',B.k,null,!1)
B.hgM=new A.C("routeColor",B.T,"Highlighted route-overlay polyline color (default: theme error color) \u2014 visually distinct from any static line sourceLayers.",B.k,null,!1)
B.h9D=new A.C("routeWidth",B.aM,"Route-overlay polyline stroke width (default 4).",B.k,null,!1)
B.h8n=new A.C("allowRotate",B.ab,"Let the user rotate the map camera (two-finger twist). Default off (north-locked) \u2014 an applet opts a specific map into rotation.",B.k,null,!1)
