B.fUz=new A.C("subtitleColumn",B.K,"Optional column rendered as an italic standfirst under the title.",B.k,null,!1)
B.fV5=new A.C("onLinkTap",B.a_,'Action spec { fn, args } fired when a Markdown `[label](target)` link is tapped; `"$value"` in args is replaced by the raw link target, unmodified \u2014 the same contract `notepad`\'s `onLinkTap` uses. Unset \u2192 links render styled but inert.',B.k,null,!1)
B.h_h=new A.C("jumpToSectionSetting",B.T,'Board-settings key whose value `"<nonce>::<heading text>"` scrolls to the first matching `#`/`##`/`###` heading (trimmed, case-insensitive). The leading nonce lets a repeated tap on the same section re-trigger. The landing position is an ESTIMATE \u2014 "near this section", not frame-perfect.',B.k,null,!1)
B.fVO=new A.C("findEnabledSetting",B.T,'Opt-in "Find in article" \u2014 restores the same feature `notepad`\'s `findEnabledSetting` offers, dropped when this applet migrated from `notepad` to `bookreader`. Names a board-settings key an external affordance (e.g. a summoned action-footer\'s find icon) toggles true/false to open/close an inline search bar docked above the page. The typed query, per-occurrence match highlighting, match-count feedback ("N of M"), next/prev stepping and scroll-to-match are all self-contained in this widget \u2014 no other prop or host wiring is needed. Unset (default) \u2192 zero footprint, byte-identical to before this prop existed.',B.k,null,!1)
B.h4k=new A.C("dropCaps",B.ab,"Drop capital on the first prose paragraph (default true). A paragraph that does not open with a LETTER renders normally instead.",B.k,null,!1)
B.he6=new A.C("sectionRules",B.ab,"Thin centred ink rule above each `##` section (default true).",B.k,null,!1)
B.hi2=new A.C("justify",B.ab,"Justify body paragraphs (default false \u2014 ragged right, which reads better at narrow measures).",B.k,null,!1)
B.hb8=new A.C("accent",B.T,"Link + drop-cap colour as `#rgb`/`#rrggbb`/`#aarrggbb`. Default is the palette oxblood (lifted for legibility in the night treatment). An unparseable value is ignored.",B.k,null,!1)
B.hgB=new A.C("paper",B.T,"Page ground colour override (hex).",B.k,null,!1)
B.fZT=new A.C("ink",B.T,"Body text colour override (hex).",B.k,null,!1)
B.h99=new A.C("displayFont",B.T,'Family for titles and headings (default "IM Fell English"; falls back to Lora/Georgia/serif when the app does not bundle it).',B.k,null,!1)
B.h0G=new A.C("bodyFont",B.T,'Family for body text (default "Lora", falling back to Georgia/serif).',B.k,null,!1)
B.hci=new A.C("maxWidth",B.aM,"Page measure in logical pixels (default 680) \u2014 the text column is centred and never wider than this.",B.k,null,!1)
B.h_S=new A.C("footer",B.T,"Provenance / footer line under a closing rule (e.g. a source attribution). Empty \u2192 no footer.",B.k,null,!0)
B.fTw=new A.C("footerColumn",B.K,"Column on the bound row supplying the footer line; a non-empty value here wins over `footer`.",B.k,null,!1)
B.h_F=new A.C("imagesTable",B.b1,"Opt-in local image bytes: table holding base64 payloads a whole-line `![alt](local:<id>)` resolves against. Unset (default) \u2192 every image renders as its ALT TEXT. This node NEVER fetches an image: an http(s) src always renders alt text.",B.k,null,!1)
B.h3l=new A.C("imageSrcColumn",B.K,'Column on `imagesTable` holding the base64 payload (default "b64").',B.k,null,!1)
B.h9H=new A.C("scopedSubscription",B.ab,"Opt-in perf: only rebuild (re-parse the Markdown) when `table` or `imagesTable` actually changes, instead of on every board-wide notify (e.g. unrelated crawl/bookkeeping writes elsewhere on the board). Same mechanism `notepad`/`cards`/`table`/`dataview`/`explorer` use. Off by default: zero behavior change.",B.k,null,!1)
B.fUF=new A.C("tapChrome",B.ab,'A tap on the page body (never a link tap, never a scroll/drag) toggles `chromeSetting` true/false \u2014 mirrors mobile-browser chrome, hidden by default. Bind a sibling action footer\'s `showIf` to the same key (`{ setting: chromeSetting, equals: "true" }`) to show it only while chrome is toggled on. Off by default (false).',B.k,null,!1)
B.hbf=new A.C("chromeSetting",B.T,'Board-settings key `tapChrome` flips between "true"/"false". Unset \u2192 derived from `table` (`"bookreaderChrome:<table>"`) so two bookreaders bound to different tables never collide.',B.k,null,!1)
B.hfV=new A.C("fastScroll",B.ab,"Wikipedia-app-style right-edge fast-scroll: a draggable scrollbar thumb hugging the reading column's right edge, shown while the article scrolls and faded after ~1.5s idle. Dragging scrubs the whole document proportionally and floats a themed bubble naming the current section heading beside the thumb. Off by default (false): zero footprint for every existing bookreader use.",B.k,null,!1)
B.cgO=s([B.h9q,B.h3M,B.h4a,B.hfD,B.fUz,B.fV5,B.h_h,B.fVO,B.h4k,B.he6,B.hi2,B.hb8,B.hgB,B.fZT,B.h99,B.h0G,B.hci,B.h_S,B.fTw,B.h_F,B.h3l,B.h9H,B.fUF,B.hbf,B.hfV],t.G)
B.fwc=new A.dv("bookreader","A bespoke BOOK-PAGE reader for one row's Markdown text: parchment ground, a drop capital on the opening paragraph, thin ink rules between sections, oxblood links and serif typography (display + body). Read only \u2014 it never writes the row. A DROP-IN UPGRADE for a `readOnly` `notepad`: the binding (`table`/`rowId`/`column`), the `onLinkTap` contract and `jumpToSectionSetting` all behave identically, and the SAME block grammar parses the text, so swapping the type keeps the applet's data flow. Dark mode is a deliberate night-reading treatment (deep warm ground, soft ink), not an inverted page. The node bounds its own size, so an unbounded host axis renders a real page rather than a blank one.",B.cgO,!1)
B.haO=new A.C("model",B.a_,'The anatomy model: { parts: [{ id, name, group, kind: "muscle"|"bone", layer: "superficial"|"deep", color (hsl(...) or #hex), info, from, to, points: [[x,y,z],..], radii: [start, belly, end], peak, segments, ring }], groups: [..], title, subtitle, center: [x,y,z], tilt, yawStep, disclaimer }. A part with several strands may use `tubes: [{points, radii, ..}, ..]` instead of the inline points/radii. A malformed model renders an honest empty state \u2014 it never crashes the applet.',B.k,null,!1)
B.h1D=new A.C("disclaimer",B.T,'Honesty line shown under the info card. Defaults to "Schematic model \u2014 simplified for learning, not a medical reference."; an empty value falls back to that default rather than hiding the line. (The model\'s own `disclaimer` key takes precedence.)',B.k,null,!0)
B.fZy=new A.C("initialYaw",B.aM,"Opening spin in degrees, snapped to the model's step (default 30).",B.k,null,!1)
B.h77=new A.C("rotationStep",B.aM,'Degrees per yaw/pitch step the viewer OPENS on: 5, 15 (default, or the model\'s own `yawStep`) or 45. The viewer offers all three in its "\u22ef" cluster; a value it does not offer falls back to the model.',B.k,null,!1)
B.h2a=new A.C("sensitivity",B.a_,"AUTHOR LEVER for gesture sensitivity \u2014 the standard `sensitivity` attribute shared by every bespoke surface. Either a per-channel object, { rotate, pan, zoom, scroll, tapSlop, longPress }, or a single number as shorthand for the four continuous channels. Each value is a MULTIPLIER on the node's own calibration, clamped to 0.25-3.0; higher means the surface reacts to less input. A USER's pick in the viewer's Sensitivity sheet always outranks this, per channel, and declaring nothing leaves behavior exactly as calibrated. The tapSlop and longPress channels are additionally floored for accessibility (12px, 300ms) whatever is declared.",B.k,null,!1)
B.h7V=new A.C("minZoom",B.aM,"Minimum zoom factor (default 0.4).",B.k,null,!1)
B.h9g=new A.C("maxZoom",B.aM,"Maximum zoom factor (default 4).",B.k,null,!1)
B.h2L=new A.C("showList",B.ab,"Show the grouped part-list drawer and its toolbar button (default true).",B.k,null,!1)
B.hgy=new A.C("features",B.a_,"DECLARATIVE CHROME GATES. { probe, dissect, deepLayer, movements, pivot, snapView, sensitivity } \u2014 each defaults to true, and only the literal `false` turns one off, so an undeclared (or malformed) value leaves the node byte-identical to the full study toolbelt bodytomy ships. A gate removes ENTRY POINTS (the chips and the tap tool), never the model or the painter: `dissect: false` also drops the Hide tap tool, the card's Hide chip and the Undo/Redo/X-ray trio, and a stored `hide` tap mode falls back to rotate rather than stranding the user in a mode whose exit was removed. For an applet that mounts the body only to PICK on it (see `moveset`), all seven off leaves turn/tilt/zoom, tap-to-select and the parts list.",B.k,null,!1)
B.h7B=new A.C("selectionTable",B.b1,'Opt-in TWO-WAY selection mirror. Declared, the node writes one row per highlighted structure into this table IN PICK ORDER (a full replace, never a merge) and adopts that table back as its highlight set \u2014 so the rest of the applet can act on what the user picked with stock list/filter nodes, and an action that writes the table (e.g. "show this exercise\'s targets") lights the figure up. Undeclared, the node stays board-free: it renders a model, it never touches a row. Column names default to partId / name / group / pickOrder and are overridable via `selectionIdColumn`, `selectionNameColumn`, `selectionGroupColumn`, `selectionOrderColumn`.',B.k,null,!1)
B.hhc=new A.C("selectionIdColumn",B.K,'Part-id column of `selectionTable` (default "partId").',B.k,null,!1)
B.fZd=new A.C("selectionNameColumn",B.K,'Resolved part-name column (default "name").',B.k,null,!1)
B.hbw=new A.C("selectionGroupColumn",B.K,'Resolved group column (default "group").',B.k,null,!1)
B.hcF=new A.C("selectionOrderColumn",B.K,'Zero-based pick-order column (default "pickOrder"); the read-back sorts on it, so the figure and the list always agree on order.',B.k,null,!1)
B.dgR=s([B.haO,B.h1D,B.fZy,B.h77,B.h2a,B.h7V,B.h9g,B.h2L,B.hgy,B.h7B,B.hhc,B.fZd,B.hbw,B.hcF],t.G)
B.fvB=new A.dv("anatomy","A schematic, rotatable 3D anatomy viewer. Parts are tube meshes built from a few control points and a belly-radius profile; the view is orthographic with the spin locked to fixed steps, so each distinct view is projected and depth-sorted once and cached in a small LRU (pan, zoom and roll are pure 2D and never reproject). THREE AXES: drag sideways to spin (yaw), up/down to tilt (pitch), twist with two fingers to roll; two-finger drag pans and pinch or scroll zooms. Tap a part for a plain-language card, which can always be collapsed to a chip. The deep-layer toggle peels the superficial parts. Geometry is DATA: the whole model lives in `model`, so a new body region ships as JSON.",B.dgR,!1)
B.hg4=new A.C("table",B.b1,"Bubbles table (one row per idea).",B.k,null,!1)
B.fUW=new A.C("filter",B.a_,'Opt-in row scope: { "column": <col>, "value": <val-or-token> } keeps bubbles whose column equals the value; the set form { "column": <col>, "in": [..] } keeps rows whose value is in the set. Tokens resolve live: $selected:<table> \u2192 the selectRow pick, $rowId \u2192 the injected host row, $playerId \u2192 the current player. Absent \u2192 all rows; present but the resolved value is empty (e.g. nothing selected) \u2192 no bubbles, never all. Links auto-scope to the visible bubbles.',B.k,null,!1)
B.h3W=new A.C("scopeColumn",B.K,"Opt-in ENGINE scope filter (see `BoardState.rowsForScoped`) \u2014 the same convention the `explorer` node's `scopeColumn` reads via `activeScope`, so a bubl bound to a scoped table (e.g. a File > Board > bubbles chain) shows only the open file/board's bubbles even when no ancestor explorer for that hop happened to mount. Distinct from `filter` (a token-resolved value/set filter); the two may combine. Absent = unchanged behavior.",B.k,null,!1)
B.fTk=new A.C("labelColumn",B.K,'Text label column (default "label").',B.k,null,!1)
B.hia=new A.C("labelFallbackColumn",B.K,"When the label is empty, show this column's first line instead (e.g. a titleless comment's text).",B.k,null,!1)
B.hh7=new A.C("sublabelColumn",B.K,'Optional second, smaller line under the label \u2014 a quantity or status ("2 L", "low", "out").',B.k,null,!1)
B.h8M=new A.C("computeColumn",B.K,"Auto-compute: a numeric attribute (e.g. calories) that an output bubble SUMS across its inputs (following the links); a stated value that differs from the sum is flagged as an unaccounted gap.",B.k,null,!1)
B.hh3=new A.C("attrsColumn",B.K,'Column storing USER-DEFINED attributes as a JSON map {name: value} \u2014 the "Add attribute\u2026" side-channel on the selected bubble\'s style bar. Any name/value pair the user types, no hard-coded categories (default "attrs").',B.k,null,!1)
B.fXn=new A.C("computePick",B.ab,"With selectStyle: show a small selector letting the user choose WHICH numeric attribute (from attrsColumn) the \u03a3 rollup totals, instead of a fixed computeColumn (default off).",B.k,null,!1)
B.heM=new A.C("subPick",B.ab,"With selectStyle: show a small selector letting the user choose WHICH attribute (from attrsColumn) shows as each bubble's sublabel line, instead of a fixed sublabelColumn (default off).",B.k,null,!1)
B.fXA=new A.C("posColumn",B.K,'Column storing "x,y" position (default "pos").',B.k,null,!1)
B.fU6=new A.C("colorColumn",B.K,"Optional numeric colour-index column.",B.k,null,!1)
B.h10=new A.C("colorMap",B.a_,'Optional map of colorColumn values to palette index (0-5), so a string column like kind ("raw"/"made"/"final") drives colour.',B.k,null,!1)
B.hg5=new A.C("parentColumn",B.K,'Column storing the nesting parent bubble id (default "parent").',B.k,null,!1)
B.fXT=new A.C("linksTable",B.b1,"Optional table of links (from/to bubble ids).",B.k,null,!1)
B.hbQ=new A.C("linkFromColumn",B.K,'Link source id column (default "from").',B.k,null,!1)
B.h8G=new A.C("linkToColumn",B.K,'Link target id column (default "to").',B.k,null,!1)
B.h7Q=new A.C("extraLinks",B.a_,'ideasgraft-1026: READ-ONLY extra line sources drawn beside linksTable: [{table, fromColumn?, toColumn?, typeColumn?, typeValue?, dashed?}] (from/to default "from"/"to"; typeValue keeps only matching rows; dashed defaults true so a second relation reads differently). Never selectable, toggled or deleted from the board.',B.k,null,!1)
B.h5g=new A.C("linkTypeColumn",B.K,'Column stamped with linkTypeValue on links this node CREATES, so drawn/sprouted links carry a type (e.g. "flow") a typed outline can recognise. Absent \u2192 links stay {from,to} only.',B.k,null,!1)
B.fZE=new A.C("linkTypeValue",B.T,'Value written into linkTypeColumn for new links (e.g. "flow").',B.k,null,!1)
B.h93=new A.C("nestLinkType",B.T,'Opt-in: derive nesting from linksTable \u2014 a link row whose linkTypeColumn value equals this makes the "to" bubble a child of the "from" bubble (from CONTAINS to) instead of drawing an arrow for that edge. Requires linksTable + linkTypeColumn. A non-empty literal parentColumn value on a row always wins over the derived parent, so drag-nesting/repositioning keeps working; absent \u2192 unchanged behavior (parentColumn only).',B.k,null,!1)
B.hgw=new A.C("onLinkTap",B.a_,"Link-arrow tap action spec { fn, args }, fired with the LINK row (from linksTable) \u2014 tap an arrow to open what flows along it. Bubbles win over arrows; absent \u2192 arrows stay passive.",B.k,null,!1)
B.hhF=new A.C("linkSelect",B.ab,"Tap a drawn link arrow to SELECT it: the arrow highlights and a small floating bar blooms at its midpoint with reverse / delete / close. Bubbles and the water still win the tap first; a link tap under linkSelect does not ripple or add a bubble (default off).",B.k,null,!1)
B.h8W=new A.C("contain",B.ab,"Keep free bubbles inside the visible board (clamp their on-screen centre) so a bubble anchored outside it stays reachable and draggable. Default off (free float).",B.k,null,!1)
B.h_C=new A.C("maxBubbleRadius",B.aM,"Upper bound (px) on a data-driven sizeColumn radius. Default 220.",B.k,null,!1)
B.h9o=new A.C("float",B.aM,"Gentle bob amplitude in px, 0 = still (default 5).",B.k,null,!1)
B.h11=new A.C("nestGrip",B.aM,"How centred a drop must be to nest vs link, 0.2..0.95 (default 0.5).",B.k,null,!1)
B.h4N=new A.C("dragNestDisabled",B.ab,"A drag END never auto-nests (writes parentColumn) or auto-links (writes linksTable) \u2014 free positional drag still works and still persists posColumn, it just never mutates parent/link data as a side effect of where a bubble lands. For a VIEW-ONLY board whose parent/color/links are owned and rewritten by an external process (default off).",B.k,null,!1)
B.hg6=new A.C("bubbleSize",B.aM,"Base bubble radius in logical px (default 52).",B.k,null,!1)
B.fW4=new A.C("look",B.T,'Visual style: "soft" = pale water, pale-white bubbles with a strong colored outline, radius sized to fit the text. Unset = legacy watercolor look.',B.k,null,!1)
B.hgE=new A.C("holdMenu",B.ab,"Long-press a bubble opens an in-canvas action ring on the water (rename in place / pull a link / zoom in); hold + drag pulls a live link thread onto another bubble. Supersedes longPressEdits for bubbles (default off).",B.k,null,!1)
B.hdp=new A.C("zoomable",B.ab,"With holdMenu: a zoom chip focuses INTO a bubble \u2014 the board shows its children, water taps spawn inside it, and a breadcrumb chip zooms back out (default off).",B.k,null,!1)
B.hfs=new A.C("duplicable",B.ab,"With holdMenu: a duplicate chip copies the held bubble AND everything nested inside it (its whole sub-tree) plus every link that stays within the copy; the new copy is offset from the original (default off).",B.k,null,!1)
B.h4u=new A.C("selectStyle",B.ab,"Tap a bubble to SELECT it: a floating in-canvas style bar (fill, shape, outline colour + thickness, rename, subtext, resize, erase) \u2014 each control writes a per-bubble style column, so appearance is user-chosen, not enum-driven (default off).",B.k,null,!1)
B.h84=new A.C("pinchZoom",B.ab,"Pinch-zoom + pan the whole board: two fingers pinch to zoom (0.5\xd7\u20133\xd7) and drag to pan; a trackpad two-finger scroll pans and \u2303/\u2318 + wheel zooms (the draw-tool model). One-finger gestures keep their meanings (default off).",B.k,null,!1)
B.hgV=new A.C("showNested",B.ab,"Show bubbles nested inside others at the ROOT level (default on). Off: nested bubbles tuck behind their parent \u2014 which wears a +N badge \u2014 and zooming INTO a bubble still reveals its contents.",B.k,null,!1)
B.h9C=new A.C("collapsedColumn",B.K,'Opt-in per-row FOLDER state: any bubble with hierarchy children (parentColumn or nestLinkType) shows a small expand/collapse chip; collapsing folds its whole descendant subtree \u2014 and every link touching a hidden bubble \u2014 behind a "+N" badge (same visual as showNested\'s badge). Set \u2192 toggling WRITES this bool column (like posColumn persists position), so the fold survives a reload. Unset \u2192 the chip still works, but the fold is SESSION-ONLY (in-memory), no schema change needed. PRECEDENCE with showNested: the two compose by OR \u2014 a bubble is hidden if either applies. showNested off already tucks every nested bubble away by default; a per-bubble collapse folds a SPECIFIC subtree on top of that (or entirely on its own with showNested on, for fine per-bubble control instead of an all-or-nothing default). Absent (default) \u2192 the chip still appears on any bubble with children, but nothing is ever pre-folded, so an untouched board renders unchanged.',B.k,null,!1)
B.fYw=new A.C("arrowCollapsedColumn",B.K,'Opt-in per-row FOLDER state for the DOWNSTREAM ARROW CASCADE \u2014 a SECOND, independent collapse axis from [collapsedColumn] (which folds NESTED children). A bubble flagged true in this bool column folds its whole downstream chain: every bubble reachable by following OUTGOING links (linksTable, linkFrom\u2192linkTo, drawn-arrow edges only, never nesting edges), behind a "+N" badge (same visual as collapsedColumn\'s). Cycle-safe (arrow graphs can loop). V1 hides the WHOLE downstream cascade \u2014 a bubble reachable from a collapsed root hides even if a still-visible bubble also points to it; shared-node-aware hiding is a deliberate follow-up, not an oversight. Composes with collapsedColumn and showNested by OR (any applicable rule hides a bubble). No built-in chip this round \u2014 toggle via the existing toggleField function against this column. Absent (default) \u2192 zero behavior change.',B.k,null,!1)
B.fZN=new A.C("multiSelect",B.ab,"With selectStyle: select MANY bubbles at once \u2014 drag on open water for a marquee, shift-click to add, ctrl/cmd-click to toggle (add or remove). While more than one is selected, style changes apply to all and a drag moves the whole group (default off).",B.k,null,!1)
B.h0Q=new A.C("holdMultiSelect",B.ab,"With multiSelect: long-hold a bubble then tap others to extend the selection one at a time (add-mode), instead of marquee/shift/ctrl-click only. Also extends holdMenu's long-press to add a link's endpoints to the selection (default off).",B.k,null,!1)
B.hfL=new A.C("fillColorColumn",B.K,'Column holding a per-bubble fill "#RRGGBB" (soft look). Empty = the palette default.',B.k,null,!1)
B.hhu=new A.C("fillColorMap",B.a_,'Opt-in DERIVED fill colour for read-only consumers with no colour column: { "column": <col>, "colors": { <value>: <ramp-name-or-#hex>, .. }, "default": <ramp-name-or-#hex>? }. Resolved AFTER fillColorColumn \u2014 a literal per-row hex from that column always wins when both are set. Absent/unmapped with no default = unchanged.',B.k,null,!1)
B.fYg=new A.C("outlineColorColumn",B.K,'Column holding a per-bubble outline "#RRGGBB".',B.k,null,!1)
B.h4m=new A.C("outlineWidthColumn",B.K,"Column holding a per-bubble outline width in px.",B.k,null,!1)
B.hfR=new A.C("shapeColumn",B.K,"Column holding a per-bubble shape: circle / rounded / diamond / triangle / pentagon / hexagon / semihex / star.",B.k,null,!1)
B.hdV=new A.C("roundedColumn",B.K,"Column (truthy) \u2192 soften the corners of the bubble's shape.",B.k,null,!1)
B.fTK=new A.C("aspectColumn",B.K,"Column (number width\xf7height, 1=equal) \u2192 stretch the shape wider/taller.",B.k,null,!1)
B.h57=new A.C("rotationColumn",B.K,"Column (degrees) \u2192 rotate the shape (label stays upright).",B.k,null,!1)
B.hdF=new A.C("customShapeColumn",B.K,'Column holding a drawn polygon "x,y;x,y;\u2026" of normalised points (-1..1) that overrides the preset shape.',B.k,null,!1)
B.hco=new A.C("sizeColumn",B.K,"Column holding a per-bubble radius (used by the resize handle).",B.k,null,!1)
B.fXS=new A.C("wave",B.ab,"A dragged bubble gently leans its neighbours away as it passes (they spring back, never relocated). Default on; set false to hold the water still.",B.k,null,!1)
B.hcf=new A.C("linksOnTop",B.ab,"Draw link arrows ABOVE the bubbles (default below), so a flow stays visible where bubbles overlap or nest.",B.k,null,!1)
B.hft=new A.C("doubleTapWaterAdds",B.ab,"Double-tap the open water to add a bubble; a single tap only ripples (so you never add one by accident).",B.k,null,!1)
B.hbI=new A.C("doubleTapEdits",B.ab,"With selectStyle, double-tap a bubble to open its inline label editor; a single tap still just selects it (default off).",B.k,null,!1)
B.h6O=new A.C("holdWaterGrows",B.ab,"Hold the open water to grow a bubble (bigger the longer you hold), released at that size; needs sizeColumn to persist it.",B.k,null,!1)
B.h4d=new A.C("onTap",B.a_,"Bubble-tap action spec { fn, args }.",B.k,null,!1)
B.hck=new A.C("onLongPress",B.a_,"Bubble long-press action spec { fn, args } \u2014 used with tapBubbleSprouts so editing still has a home once tap adds.",B.k,null,!1)
B.h2K=new A.C("tapWaterAdds",B.ab,"Tap the open water to add a new bubble there (default off).",B.k,null,!1)
B.h64=new A.C("tapBubbleSprouts",B.ab,"Tap a bubble to sprout a new one linked from it; suppresses the tap action (default off).",B.k,null,!1)
B.hgQ=new A.C("longPressEdits",B.ab,"Long-press a bubble to fire onLongPress, e.g. edit it (default off).",B.k,null,!1)
B.h2z=new A.C("showAddButton",B.ab,'Show a floating "+ New idea" button that adds a bubble and opens it to name (default off).',B.k,null,!1)
B.hfi=new A.C("pickColumn",B.K,"Tap a bubble to bloom a ring of pickValues around it; the chosen value writes to this column (e.g. set a stage in place). Suppresses the tap action \u2014 pair with longPressEdits so editing has a home.",B.k,null,!1)
B.fTN=new A.C("pickValues",B.a_,'Values offered by the tap picker, e.g. ["raw","made","final"]; each option is coloured via colorMap.',B.k,null,!1)
B.ham=new A.C("addPickColumn",B.K,"Long-press the water to bloom a ring of addPickValues and choose the KIND of the NEW bubble (written to this column). A plain tap on the water still adds a default one.",B.k,null,!1)
B.h_R=new A.C("addPickValues",B.a_,'Bubble kinds offered by the long-press-water add picker, e.g. ["idea","raw","made","final"]; each option is coloured via colorMap.',B.k,null,!1)
B.fYx=new A.C("linkColorColumn",B.K,'Column holding a per-link arrow "#RRGGBB" override (opt-in) \u2014 wins over the selection/soft-look default color. The link bar shows a color picker only when this column is configured.',B.k,null,!1)
B.hb5=new A.C("linkWidthColumn",B.K,"Column holding a per-link arrow stroke width, thin/med/thick (opt-in) \u2014 wins over the selected/plain stroke width. The link bar shows a thickness toggle only when this column is configured.",B.k,null,!1)
B.h9_=new A.C("linkStyleColumn",B.K,'Column holding a per-link arrow style, "solid" (default) or "dashed" (opt-in). The link bar shows a solid/dashed toggle only when this column is configured.',B.k,null,!1)
B.fWb=new A.C("linkShapeColumn",B.K,'Per-link shape column (opt-in, same convention as linkColorColumn): "straight" (default) or "arc" \u2014 arc bows the arrow into a soft quadratic curve. The link bar shows a straight/curved toggle only when this column is configured.',B.k,null,!1)
B.hi4=new A.C("linkHeadsColumn",B.K,'Per-link arrowhead column (opt-in): \'\' or "one" (default, arrow at the TO end only), "both" (both ends), or "none" (plain line). The link bar shows a one/both/none toggle only when this column is configured.',B.k,null,!1)
B.dfe=s(["radial"],t.s)
B.h3B=new A.C("autoArrange",B.T,'Opt-in root-level auto-layout for a bubble with no stored posColumn value yet: "radial" arranges ROOT bubbles in overlap-avoiding concentric rings sized from bubbleSize, instead of the plain per-index ring fallback \u2014 so the map opens tidy. Nested bubbles keep auto-orbiting their parent either way. Re-runnable on demand via the `bublArrange` action (wire a "Tidy" button/menu item to it). Absent \u2192 unchanged per-index ring fallback.',B.dfe,null,!1)
B.fTM=new A.C("tapMenu",B.a_,"Opt-in: a plain bubble TAP opens a menu sheet listing these items instead of firing onTap directly \u2014 [{label, icon?, action}, ...] (same shape as swipeActions' object entries). Selecting an item fires its `action` spec with the tapped bubble's id+table merged in, same as onTap. Absent/empty \u2192 today's direct-tap behavior, unchanged.",B.k,null,!1)
B.fWH=new A.C("chainThemes",B.a_,'List of "#RRGGBB" hexes. Every bubble with no explicit fill (fillColorColumn/fillColorMap still win) is tinted by the theme of its chain root, picked by that root\'s id. Absent/empty = unchanged palette fallback.',B.k,null,!1)
B.fVz=new A.C("feelSliders",B.ab,'Add a small "Feel" section to the style bar (requires selectStyle) with two live sliders for waveStrength and waveRange, persisted per board. Off by default.',B.k,null,!1)
B.h9U=new A.C("rememberFolds",B.ab,"Persist the collapsed/folded bubble-id set per board instead of the session-only in-memory set. Only applies when collapsedColumn is unset (a bound column already persists and wins).",B.k,null,!1)
B.ddU=s(["pathContains"],t.s)
B.h9l=new A.C("scopeMatch",B.bU,'Opt-in scope MATCH MODE, only meaningful alongside scopeColumn. "pathContains" treats scopeColumn\'s value as a materialized-path string and matches when it contains the active scope value wrapped in slashes (shows bubbles at any depth, not just an exact id match). Absent = plain equality.',B.ddU,null,!1)
B.fXs=new A.C("waveRange",B.aM,"Opt-in override of the wave-push range in px \u2014 how close a neighbour must be to feel a push at all. Absent = the existing per-pair formula. A live feelSliders drag overrides this once set.",B.k,null,!1)
B.h6Y=new A.C("waveStrength",B.aM,"Opt-in multiplier on the wave-push intrusion depth \u2014 how far a neighbour shoulders aside as a dragged bubble passes (default 1.0). A live feelSliders drag overrides this once set.",B.k,null,!1)
B.cZN=s([B.hg4,B.fUW,B.h3W,B.fTk,B.hia,B.hh7,B.h8M,B.hh3,B.fXn,B.heM,B.fXA,B.fU6,B.h10,B.hg5,B.fXT,B.hbQ,B.h8G,B.h7Q,B.h5g,B.fZE,B.h93,B.hgw,B.hhF,B.h8W,B.h_C,B.h9o,B.h11,B.h4N,B.hg6,B.fW4,B.hgE,B.hdp,B.hfs,B.h4u,B.h84,B.hgV,B.h9C,B.fYw,B.fZN,B.h0Q,B.hfL,B.hhu,B.fYg,B.h4m,B.hfR,B.hdV,B.fTK,B.h57,B.hdF,B.hco,B.fXS,B.hcf,B.hft,B.hbI,B.h6O,B.h4d,B.hck,B.h2K,B.h64,B.hgQ,B.h2z,B.hfi,B.fTN,B.ham,B.h_R,B.fYx,B.hb5,B.h9_,B.fWb,B.hi4,B.h3B,B.fTM,B.fWH,B.fVz,B.h9U,B.h9l,B.fXs,B.h6Y,B.qQ],t.G)
B.fw_=new A.dv("bubl","A calm floating idea board: each row is a rounded bubble that floats gently in place. Drag to place, drop one centre-on-centre to nest it, overlap two edges to link them (a directional idea-flow arrow). A tap fires onTap. Powers the bublee applet.",B.cZN,!1)
B.hdd=new A.C("modelTablesTable",B.b1,'Scenario data-model TABLES (default "modelTables": board, name, label, order) \u2014 authored in the Data panel. Absent = no Data panel.',B.k,null,!1)
B.hg9=new A.C("modelColumnsTable",B.b1,'Scenario data-model COLUMNS (default "modelColumns": board, table, name, label, type, options, order).',B.k,null,!1)
B.fTl=new A.C("modelRowsTable",B.b1,'Scenario data-model SAMPLE ROWS (default "modelRows": board, table, data JSON). Optional \u2014 absent = no sample rows.',B.k,null,!1)
B.h0r=new A.C("cobuildSessionsTable",B.b1,'Build-with-Claude RECIPE sessions (default "cobuildSessions": board, startedAt, prompt, model) \u2014 one row per exchange. Absent (with cobuildStepsTable) = the step feed is session-only.',B.k,null,!1)
B.fXz=new A.C("cobuildStepsTable",B.b1,'Build-with-Claude RECIPE steps (default "cobuildSteps": session, order, op, args JSON, label, manualPath, ok, refusal, optional targets JSON) \u2014 one row per applied op; the walk-through source.',B.k,null,!1)
B.h1E=new A.C("scope",B.T,"The board (file) id to scope screens to \u2014 typically injected by the hosting library-explorer node. Absent shows every screen row.",B.k,null,!1)
B.hbb=new A.C("screenBoardColumn",B.K,'Screens: board FK column (default "board").',B.k,null,!1)
B.hgt=new A.C("screenNameColumn",B.K,'Screens: name column (default "name").',B.k,null,!1)
B.hhA=new A.C("screenDeviceColumn",B.K,'Screens: device column, "phone"/"tablet"/"web" (default "device").',B.k,null,!1)
B.fYe=new A.C("screenXColumn",B.K,'Screens: board X position column (default "x").',B.k,null,!1)
B.fVj=new A.C("screenYColumn",B.K,'Screens: board Y position column (default "y").',B.k,null,!1)
B.hgU=new A.C("screenWidthColumn",B.K,'Screens: content-width column for a fragment-device screen (spec \xa77.3; default "width").',B.k,null,!1)
B.fZO=new A.C("screenVariantOfColumn",B.K,'Screens: nullable FK to the source screen a variant was generated from (default "variantOf").',B.k,null,!1)
B.h9r=new A.C("screenFolderColumn",B.K,'Screens: nullable shared-string folder label column (default "folder"). Screens sharing a trimmed non-empty value render as one labeled group on the board with a collapsible outline; absent/empty is unfiled, byte-identical to a board that predates this feature.',B.k,null,!1)
B.h5h=new A.C("screenModeColumn",B.K,'Screens: nullable per-frame RENDER MODE column (default "mode") \u2014 "wireframe" (blocks solved and painted as ghosts, the only behavior before this existed) or "real" (the frame mounts the ACTUAL applet screen named by screenRealAppletColumn/screenRealScreenColumn, through the same host resolver `embed` uses). Absent/empty/unknown falls back to the board default (`frameMode`), so a board that carries none of these columns renders byte-identically to today.',B.k,null,!1)
B.fWh=new A.C("screenRealAppletColumn",B.K,'Screens: applet id a "real"-mode frame renders (default "realApplet").',B.k,null,!1)
B.fWE=new A.C("screenRealScreenColumn",B.K,'Screens: which screen of that applet a "real"-mode frame renders (default "realScreen"); absent/empty = the applet\'s own first/root screen. A bound screen id that does not exist renders the marked placeholder with a reason, never a blank frame.',B.k,null,!1)
B.has=new A.C("screenNodeJsonColumn",B.K,"Screens: the frame's CARRIED ui.json node subtree, as a raw JSON string (default \"nodeJson\"). A frame that carries nodes renders THOSE nodes through the engine's real node builders \u2014 the same path the running applet goes through \u2014 so identical JSON produces an identical view by construction, and the tree stays editable board data instead of a sealed live mount. Absent/empty/unparseable/non-object falls back to reading the body live from the applet named by screenRealAppletColumn, byte-identically to a board that predates this feature.",B.k,null,!1)
B.hhw=new A.C("widgetNodeJsonColumn",B.K,'Widgets: the BLOCK\'s own carried ui.json node subtree, as a raw JSON string (default "nodeJson"). A block that carries a node is rendered by the engine\'s real node builder against the applet its screen is bound to (screenRealAppletColumn), so a mirrored applet screen is a TREE of real, selectable, movable widgets rather than one sealed picture of the app. The block\'s "kind" stays editing metadata only (tree icon, inspector, and the sketch fallback when the applet cannot be resolved) \u2014 never the visual path, so no hand-mapped translation can drift. Absent/empty/unparseable/non-object renders exactly as before this feature.',B.k,null,!1)
B.h3g=new A.C("widgetNodeTypeColumn",B.K,'Widgets: the REAL ui.json node type behind a carried node (default "nodeType") \u2014 provenance for the inspector; never read by the renderer.',B.k,null,!1)
B.hdB=new A.C("screenPlaceholderColumn",B.K,'Screens: truthy on a frame standing for a HOST-ONLY surface \u2014 an OS share sheet, a system camera, a sign-in web view \u2014 that no applet screen can ever render (default "placeholder"). Such a frame never attempts a real render: it keeps its editable wireframe blocks and wears a dashed outline plus a corner badge over them.',B.k,null,!1)
B.hhC=new A.C("screenPlaceholderLabelColumn",B.K,'Screens: nullable badge text for a placeholder frame (default "placeholderLabel"; absent shows "Host surface").',B.k,null,!1)
B.h5w=new A.C("widgetScreenColumn",B.K,'Widgets: owning screen FK column (default "screen").',B.k,null,!1)
B.fVe=new A.C("widgetKindColumn",B.K,'Widgets: kind enum column \u2014 titlebar/searchbar/tabs/scrollview/list/settings/text/card/image/buttonrow/bottomnav/fab/row/dropdown/popup (default "kind"). `dropdown` (body) is a closed selector that opens its `items` as a list below itself; `popup` (overlay, like `fab`) is a small closed pill that opens its `items` as a centered scrim card \u2014 both are Moku menus (mkmenus-0820): open/closed state is session-only (never written), and one level of an item\'s `children` opens as an indented sub-menu on tap.',B.k,null,!1)
B.h_5=new A.C("widgetLabelColumn",B.K,'Widgets: label column (default "label").',B.k,null,!1)
B.hfa=new A.C("widgetRegionColumn",B.K,'Widgets: region column, top/body/bottom/overlay (default "region").',B.k,null,!1)
B.fYB=new A.C("widgetOrderColumn",B.K,'Widgets: order-within-region column (default "order").',B.k,null,!1)
B.h7n=new A.C("widgetIntentColumn",B.K,"Widgets: nullable size-intent override, fixed/fill/wrap/natural (default \"intent\"); absent falls back to the kind's default intent. natural (planted by a mirror) follows the carried real node's measured height, falling back to the stored height.",B.k,null,!1)
B.fZq=new A.C("widgetHeightColumn",B.K,"Widgets: nullable per-block height override in logical px, set by the inspector's Height field (default \"height\"); absent falls back to the kind's previewHeight (row: its computed intrinsic height).",B.k,null,!1)
B.heK=new A.C("widgetBehaviorColumn",B.K,'Widgets: nullable per-block behavior applied by dropping a behavior chip\'s circle avatar onto an existing block (e.g. "scrollview"/"list"/"settings"; default column "behavior"). A non-empty value forces that block\'s effective intent to fill (expands into remaining space) and paints an affordance overlay; absent/empty/unknown solves and renders byte-identically to today.',B.k,null,!1)
B.han=new A.C("widgetParentColumn",B.K,"Widgets: nullable FK to an owning `row` widget's id (default \"parent\"). Absent/empty = top-level widget, today's behavior.",B.k,null,!1)
B.h68=new A.C("widgetCellColumn",B.K,'Widgets: column index within the owning row\'s cells, only meaningful alongside widgetParentColumn (default "cell"); absent defaults to 0.',B.k,null,!1)
B.fWA=new A.C("widgetColsColumn",B.K,'Widgets: number of columns for a `row`-kind widget (default "cols"); absent defaults to 2.',B.k,null,!1)
B.hgc=new A.C("widgetWeightsColumn",B.K,'Widgets: nullable relative column-width weights for a `row`-kind widget, e.g. "[1,2]" (default "weights"); absent/null = equal columns.',B.k,null,!1)
B.fXu=new A.C("widgetItemsColumn",B.K,'Widgets: nullable JSON-encoded list of real content items (default "items"). Each entry is a plain string, or an object {text, toggle?, icon?, children?}. When set and non-empty on a content-capable kind (list/settings/tabs/buttonrow/card/scrollview/text/dropdown/popup), the block paints real text rows instead of its usual skeleton, in Visuals, Labels, Blueprint and Present alike. `children` is parsed and indented one level in list-shaped kinds; absent/empty/garbage JSON solves and renders byte-identically to today. The inspector\'s Items editor (add/edit/toggle/reorder/remove) and its "Paste dataset" multiline box (one item per line) both write this column.',B.k,null,!1)
B.h0b=new A.C("widgetTableColumn",B.K,'Widgets: the DATA TABLE a block is bound to (default "table") \u2014 read only by the faithful applet export: with a data model, a list/card/searchbar/stat/calendar block binds to the table named here (an unbound data block uses the model\'s first table).',B.k,null,!1)
B.h9z=new A.C("widgetFieldColumn",B.K,"Widgets: the bound COLUMN of the block's data table (default \"field\") \u2014 a list/card title, a search bar's search column, a calendar's date column. Read by the faithful applet export.",B.k,null,!1)
B.hbz=new A.C("widgetDataActionColumn",B.K,'Widgets: the block\'s authored tap action (default "dataAction") \u2014 JSON {fn, args} validated by the shared action gate, or "none". Written only by the setBlockAction build op.',B.k,null,!1)
B.h7E=new A.C("flowBoardColumn",B.K,'Flows: board FK column (default "board").',B.k,null,!1)
B.hf9=new A.C("flowFromWidgetColumn",B.K,'Flows: source widget FK column (default "fromWidget").',B.k,null,!1)
B.haX=new A.C("flowToScreenColumn",B.K,'Flows: target screen FK column (default "toScreen").',B.k,null,!1)
B.hec=new A.C("flowTransitionColumn",B.K,'Flows: transition column, push/fade/sheet (default "transition").',B.k,null,!1)
B.fYO=new A.C("flowFromItemColumn",B.K,"Flows: which ITEM inside the source block this link belongs to, as a 0-based index into that block's `items` (default \"fromItem\"). Empty/absent = the link belongs to the whole block, the only thing a flows row could mean before this column existed \u2014 so every legacy row keeps its exact meaning. This is what lets one nav bar's tabs, or one list's rows, each carry their own destination.",B.k,null,!1)
B.hcD=new A.C("flowActionColumn",B.K,'Flows: what the link DOES \u2014 "screen" (navigate to `toScreen`, the implicit behaviour of every legacy row and the fallback for an absent/unrecognised value), "back" (pop one level of Play\'s visited-frame stack), or "overlay" (open the block named by `toOverlay` over the CURRENT screen without navigating). Default column name "action".',B.k,null,!1)
B.hbs=new A.C("flowToOverlayColumn",B.K,'Flows: the overlay BLOCK\'s widget id for `action: "overlay"` links (default "toOverlay"). An overlay is a dropdown/popup block on the same screen \u2014 an overlay STATE of that screen, deliberately not a screen of its own. Ignored for every other action.',B.k,null,!1)
B.hdX=new A.C("showFlows",B.ab,"Draw light curved arrows widget->screen when NOT in play mode (default on).",B.k,null,!1)
B.djc=s(["wireframe","clean","material","ios","web"],t.s)
B.fWP=new A.C("style",B.bU,'Board-wide design language for the ghost painter \u2014 a deterministic token swap over the SAME solved rects, never a re-layout (default "wireframe", pixel-identical to today; an unknown value also falls back to wireframe). This is the JSON-authored default; boardStyleColumn (when boardsTable is set) lets the toolbar persist a per-document override instead.',B.djc,null,!1)
B.dj4=s(["wireframe","real"],t.s)
B.fZD=new A.C("frameMode",B.bU,'Board-wide DEFAULT render mode for frames that do not state their own (default "wireframe", byte-identical to a composer that predates real rendering). "real" makes every unmarked frame mount its bound applet screen \u2014 how an EXISTING app board opts its whole canvas in at once. Real frames mount only while VISIBLE (a bounded number of live nested boards; off-screen frames show the still captured when they left view), and are NON-INTERACTIVE this round: taps inside the app do nothing, while flow hotspots still navigate in Play. Needs a host that wired an embed resolver; without one every real frame shows a marked placeholder instead.',B.dj4,null,!1)
B.hcb=new A.C("sketch",B.a_,'Opt-in SKETCH artboards: a map of `canvas`-node props (nodesTable, edgesTable, sketchTable/sketchColumn for freehand ink, label/x/y/w/h columns, colors, fidelity, ...) plus `screenColumn` (default "screen") naming the column on box and ink rows that keys them to their frame. A frame whose content column is "sketch" then hosts a real canvas drawing (edited full screen; previewed read-only on the board and in Play, where a box with a goto link is a tap target) instead of widget blocks (shown to users as a DIAGRAM; the stored content value stays "sketch"). Absent = every frame is Live, unchanged.',B.k,null,!1)
B.h3F=new A.C("freehand",B.a_,'Opt-in freehand SKETCH artboards: a map of `draw`-node props plus `table` (default "freehandDrawings"), `strokesColumn` (default "strokes"), `titleColumn` (default "title") and `screenColumn` (default "screen") keying each drawing row to its frame. A frame whose content column is "freehand" then hosts a real draw-node drawing (edited full screen; previewed read-only on the board and in Play) instead of widget blocks. Absent = no Sketch type offered.',B.k,null,!1)
B.hcU=new A.C("screenContentColumn",B.K,'Screens: per-frame content mode column (default "content"): "sketch" = a canvas drawing (needs `sketch`), anything else = Live widget blocks.',B.k,null,!1)
B.hb7=new A.C("screenHeightColumn",B.K,'Screens: explicit artboard height column (default "height"); with the width column it pins a framed artboard to an exact size (New artboard presets / custom sizes). Absent = the device size.',B.k,null,!1)
B.h46=new A.C("boardArtboardSizesColumn",B.K,'Boards: JSON list of the app\'s saved custom artboard sizes (default "artboardSizes"), kept on the main board row and re-offered by New artboard in every scenario of that app.',B.k,null,!1)
B.fUA=new A.C("screenOrderColumn",B.K,"Screens: artboard order column (default \"order\"), written by the artboard strip's drag-to-reorder; orders the strip, Play's first frame and exports. Absent = store order.",B.k,null,!1)
B.h4J=new A.C("boardSnapColumn",B.K,'Boards: per-board snap-to-grid switch (default "snapGrid"; absent/null = on). Dragging a frame lands it on the canvas dot grid while on. Absent column = session-only toggle.',B.k,null,!1)
B.h3m=new A.C("boardPlayCleanColumn",B.K,'Boards: Play\'s per-board CLEAN VIEW switch (default "playClean"; absent/null = on). On, Play hides every authoring annotation ("Sketch \u2014 not live" chips, host-surface badges, hotspot outlines, "not linked" hints) and shows only what the shipped app would. Absent column = session-only.',B.k,null,!1)
B.fVP=new A.C("boardPlayDeviceColumn",B.K,'Boards: the device Play last ran at (default "playDevice"; JSON `{name, w, h}`). Play renders every framed frame at that size, LOCKED for the run (window resizes only rescale it); the device pill switches it explicitly. Absent = the starting frame\'s size.',B.k,null,!1)
B.haE=new A.C("boardInspectColumn",B.K,'Boards: hover inspector on/off (default "inspect"; absent = off). On, hovering a live frame outlines the DEEPEST widget under the pointer and shows a readout that selects it on tap. Pointer only.',B.k,null,!1)
B.fXl=new A.C("boardInspectModeColumn",B.K,'Boards: the inspector\'s mode column (default "inspectMode"): "leaf" (just the deepest widget) or "path" (the whole chain to it).',B.k,null,!1)
B.h5k=new A.C("boardFrameModeColumn",B.K,'Boards: per-document default render-mode column (default "frameMode"), read from the scoped board row when boardsTable is set. Overrides the JSON `frameMode`; a screen\'s own mode column overrides both.',B.k,null,!1)
B.h1w=new A.C("sampleData",B.ab,"mokusample-0923. Whether a frame bound to an applet may fill that applet's EMPTY tables with deterministic, schema-derived placeholder rows, so a mirror board shows the app as it looks IN USE rather than \"0 articles\" over a blank body. Default TRUE \u2014 the JSON author's baseline, overridden by the board row's `sampleDataColumn` and then by a frame's own `screenSampleDataColumn`. Placeholders NEVER touch a table that already has rows, and never leave the render sandbox: the host must also vouch that the embedded board is ephemeral and store-free (`EmbeddedApplet.sampleDataAllowed`), so nothing can reach a store, a seed file or a sync path.",B.k,null,!1)
B.hiF=new A.C("screenSampleDataColumn",B.K,'Screens: per-frame sample-data column (default "sampleData"). Absent/null on a row means INHERIT (the board default), so a board that never writes it behaves exactly as before; an explicit false turns one frame back to the true empty state.',B.k,null,!1)
B.h3_=new A.C("screenInputModeColumn",B.K,'Screens: per-frame column for how much of the pointer stream this frame\'s embedded real screen may receive IN PLAY (default "inputMode"): "sealed" (absent/unknown/default \u2014 the embed is a live but completely inert picture, byte-identical to every board before this existed), "tappable" (taps reach the embedded screen where it actually painted, while a pointer landing on space it drew nothing in stays with the canvas for pan and select), or "live". NEVER has any effect on the editing canvas \u2014 a tappable embed there would swallow the pans and block-selects the editor is made of \u2014 and it changes nothing about the sandbox: the embedded board is still ui-only, store-free and sync-free in every mode.',B.k,null,!1)
B.h4T=new A.C("boardSampleDataColumn",B.K,'Boards: per-document sample-data column (default "sampleData"), read from the scoped board row when boardsTable is set. Overrides the JSON `sampleData`; a screen\'s own column overrides both.',B.k,null,!1)
B.fUr=new A.C("realAppletOptions",B.a_,"The catalog the frame menu's \"Choose applet screen\u2026\" picker offers (mokureal-menu-0905): a list of `{id, label, screens: [{id, label}]}` objects. The embed resolver has no enumeration API \u2014 it only ever loads an applet by an id it is already given \u2014 so this host-supplied list is the picker's sole source of options. Absent/empty makes the menu item show a disabled hint instead of opening the picker; never a crash.",B.k,null,!1)
B.fZP=new A.C("boardsTable",B.b1,"Optional boards table to persist the style/accent toolbar controls on the scoped board row (keyed by `scope`). Absent = the toolbar control is session-only and `style` wins on every rebuild.",B.k,null,!1)
B.fV9=new A.C("boardStyleColumn",B.K,'Boards: style column (default "style"); only read/written when boardsTable is set.',B.k,null,!1)
B.heI=new A.C("boardAccentColumn",B.K,'Boards: nullable accent-colour hex column, e.g. "#2563EB" (default "accent"); only read/written when boardsTable is set.',B.k,null,!1)
B.hhP=new A.C("review",B.ab,'Turn on the DESIGN-REVIEW layer (default off, byte-identical to a board without it). The same workboard gains: an 8px status dot per frame (proposed/approved/changes) with a status-coloured ring on the two that still want a decision, image-backed frames, canvas sticky notes, numbered pins, a live "Approved n \xb7 Proposed n \xb7 Changes n" legend computed from the rows, and TAP-A-FRAME to open a full-screen frame review (swipe between frames, tap a pin for its note, Approve / Request changes / add a note). Which mode a document OPENS in is persisted per board on boardModeColumn, so existing boards keep opening in the editor.',B.k,null,!1)
B.fX6=new A.C("boardModeColumn",B.K,'Boards: which mode this document opens in \u2014 "design" or "edit" (default column "mode"). Only read/written when `review` is on and boardsTable is set; an absent/unknown value reads as "edit".',B.k,null,!1)
B.h2s=new A.C("boardRevColumn",B.K,'Boards: optional revision number shown in the design-canvas subtitle ("Design canvas \xb7 10 frames \xb7 rev 6"; default "rev"). Absent simply omits the "rev n" clause \u2014 never a fabricated 1.',B.k,null,!1)
B.fZb=new A.C("screenStatusColumn",B.K,'Screens: review status enum \u2014 proposed/approved/changes (default "status"). Absent/empty/unknown reads as "proposed".',B.k,null,!1)
B.fUM=new A.C("frameImagesTable",B.b1,"Optional table of frame SCREENSHOTS, one image per row (the wikipick `articleImages` pattern: mime/b64/w/h/bytes, base64 payload, never a URL \u2014 keep each row well under the Android CursorWindow 2MB limit). A screen with a row here is IMAGE-BACKED and paints those bytes; a screen without one is NATIVE and renders live from the layout solver at whatever scale it is shown.",B.k,null,!1)
B.h0q=new A.C("frameImageScreenColumn",B.K,'Frame images: owning screen FK column (default "screen").',B.k,null,!1)
B.h2x=new A.C("frameImageSrcColumn",B.K,'Frame images: base64 payload column (default "b64"); a bare base64 string or a data: uri. Decoded through the shared local-image cache (never fetched \u2014 no egress from this path).',B.k,null,!1)
B.h0U=new A.C("stickiesTable",B.b1,"Optional sticky-notes table \u2014 free notes floating on the canvas between frames. Absent = no stickies.",B.k,null,!1)
B.hce=new A.C("stickyBoardColumn",B.K,'Stickies: board FK column (default "board").',B.k,null,!1)
B.h30=new A.C("stickyXColumn",B.K,'Stickies: canvas X column (default "x").',B.k,null,!1)
B.hdh=new A.C("stickyYColumn",B.K,'Stickies: canvas Y column (default "y").',B.k,null,!1)
