B.hbE=new A.C("stickyTextColumn",B.K,'Stickies: note text column (default "text").',B.k,null,!1)
B.hfg=new A.C("boardParentColumn",B.K,'mokufb7-1004-B: board-row column naming a SCENARIO\'s main board (default "parentBoard"). A scenario is a sandbox: Play always runs example data and offers no "Your real data" choice.',B.k,null,!1)
B.hf4=new A.C("screenRevisionOfColumn",B.K,'Screens: the live frame id this row is a PENDING REVISION of (default "revisionOf"; mokucmp-0926 Proposal compare). A row with it set is never listed as a frame; its board cell is empty. The whole revision feature is on only when this column AND widgetRevisionOfColumn exist in the schema.',B.k,null,!1)
B.h0x=new A.C("screenRevisionBaseColumn",B.K,'Screens: JSON snapshot of the live frame when the revision was made (default "revisionBase") \u2014 the base of Approve\'s three-way apply.',B.k,null,!1)
B.h56=new A.C("screenRevisionNoteColumn",B.K,'Screens: short summary of a revision (default "revisionNote").',B.k,null,!1)
B.h7l=new A.C("widgetRevisionOfColumn",B.K,'Widgets: the live widget a revision widget stands for (default "revisionOf"; empty = a widget the revision adds).',B.k,null,!1)
B.hhn=new A.C("frameHistoryTable",B.b1,"Optional frame-history table (columns screen/kind/title/changes/snapshot/revision/by/at). Approving a revision keeps the frame's prior state here. Absent = approve keeps no history.",B.k,null,!1)
B.h5G=new A.C("pinsTable",B.b1,"Optional pin-notes table \u2014 numbered notes attached to a POINT on a frame, read and created in the frame review. Absent = the review screen still approves/requests changes, it just has nothing to pin.",B.k,null,!1)
B.fWq=new A.C("pinScreenColumn",B.K,'Pins: owning screen FK column (default "screen").',B.k,null,!1)
B.fYz=new A.C("pinXColumn",B.K,'Pins: FRACTIONAL x within the frame, 0..1 (default "x") \u2014 fractional so a pin stays where it was placed at every zoom and on every device size.',B.k,null,!1)
B.hdl=new A.C("pinYColumn",B.K,'Pins: fractional y within the frame, 0..1 (default "y").',B.k,null,!1)
B.hhi=new A.C("pinOrderColumn",B.K,'Pins: sort key (default "order"). The NUMBER painted on a pin is its position in this order, so numbering stays 1..n with no gaps after a delete.',B.k,null,!1)
B.fWs=new A.C("pinTitleColumn",B.K,'Pins: short note title (default "title").',B.k,null,!1)
B.hd8=new A.C("pinTextColumn",B.K,'Pins: note body (default "text").',B.k,null,!1)
B.haT=new A.C("pinAuthorColumn",B.K,'Pins: author label (default "author") \u2014 the literal "you" or "claude" tint/label the review layer\'s note card and marker read; anything else renders neutral with that literal string as the name.',B.k,null,!1)
B.fX_=new A.C("pinParentColumn",B.K,"Pins: nullable FK to a root pin's id (default \"parent\"). A non-empty value makes the row a REPLY, rendered inside its parent's note card as a thread rather than getting its own numbered marker on the frame \u2014 see composePinsFor (roots only) and composeRepliesFor (children of one root, oldest first).",B.k,null,!1)
B.hb0=new A.C("pinRefColumn",B.K,"Pins: one typed reference string (default \"ref\") \u2014 `https://\u2026` / `gh:<org>/<repo>@<sha>:<path>` / `dispatch:<rowId>` / `frame:<screenId>` / `board:<boardId>` / `session:<tag>`. Rendered as a 44px reference chip; tapping it fires the host `openRef` callback (`onOpenRef`) with `{ref}` \u2014 the SAME chokepoint `onExport` uses, wired by `_buildNode_compose` from `renderer.callbacks['openRef']`. Absent/empty renders no chip.",B.k,null,!1)
B.fZr=new A.C("pinToColumn",B.K,'Pins: addressee \u2014 "" or "claude" or "you" (default "to"). Set by the note card\'s "Send to Claude" toggle and automatically by "Request changes" (a change request IS a message to Claude).',B.k,null,!1)
B.hej=new A.C("pinAwaitingColumn",B.K,"Pins: open-turn flag (default \"awaiting\"), set alongside pinToColumn \u2014 this engine only ever sets it true; it never clears it (that is the desktop channel's patch-fields envelope, outside this node's scope).",B.k,null,!1)
B.hbi=new A.C("pinCreatedAtColumn",B.K,'Pins: ISO-8601 stamp column (default "createdAt"), written by every in-app pin/reply write. Backs the derived "Claude replied" halo/count \u2014 see composeUnreadClaudeCount \u2014 which compares each thread\'s latest "you" vs latest "claude" createdAt; there is no separate "seen" column.',B.k,null,!1)
B.hig=new A.C("pinModelColumn",B.K,'Pins: attribution for a claude-authored row, e.g. "claude-fable-5-1 (opus)" (default "model").',B.k,null,!1)
B.hh9=new A.C("stickyAuthorColumn",B.K,'Stickies: author label, same "you"/"claude" vocabulary as pinAuthorColumn (default "author"); tints the sticky note.',B.k,null,!1)
B.h4D=new A.C("stickyRefColumn",B.K,'Stickies: one typed reference string, same grammar as pinRefColumn (default "ref").',B.k,null,!1)
B.hba=new A.C("stickyCreatedAtColumn",B.K,'Stickies: ISO-8601 stamp column (default "createdAt").',B.k,null,!1)
B.fYq=new A.C("stickyModelColumn",B.K,'Stickies: attribution column, same as pinModelColumn (default "model").',B.k,null,!1)
B.hfY=new A.C("screenStatusByColumn",B.K,'Screens: who set the current `status` \u2014 "you" or "claude" (default "statusBy"). This engine only ever writes "you" here (Claude never sets status from inside the app); a "claude" value can only have arrived from the desktop channel writer.',B.k,null,!1)
B.h18=new A.C("screenStatusAtColumn",B.K,'Screens: ISO-8601 stamp for the current `status` (default "statusAt"), shown as "Approved by you \xb7 2h ago" in the frame review header. Absent omits the byline \u2014 never a fabricated time.',B.k,null,!1)
