B.fvE=new A.dv("compose","An auto-layout screen composer: a pannable workboard of device frames. Drop a widget chip and the screen RE-SOLVES as a real layout (top/bottom regions stack fixed-height chrome, the body splits remaining space among fill widgets) instead of drawing a static mock. Self-contained chip palette; flows draw light arrows widget->screen; a Play toggle tweens the camera to a tapped widget's linked screen. Powers the `composer` applet.",B.cVZ,!1)
B.h0C=new A.C("level",B.a_,"Level definition (length, groundY, platforms, enemies, goalX).",B.k,null,!1)
B.fTn=new A.C("scoresTable",B.b1,"Optional table to persist high scores into.",B.k,null,!1)
