B.dik=s(["value","label"],t.s)
B.h5R=new A.C("sortBy",B.bU,'Bar order: "value" (default, unchanged \u2014 largest first) or "label" (ascending string sort of the group/label value \u2014 use for a chronological chart whose group is an ISO-8601 date/day string, since those sort lexicographically the same as chronologically). Ignored when `groupOrder` pins an explicit order.',B.dik,null,!1)
B.h0R=new A.C("dateLabels",B.ab,'Display each bar\'s label as M/D (e.g. "8/20") when it is a plain ISO-8601 date string ("YYYY-MM-DD") \u2014 cosmetic only, does not affect grouping/sorting/aggregation. Pair with `sortBy:"label"` for a compact, readable 14-day-style chart. Default false = the raw group value shown unchanged.',B.k,null,!1)
B.Gd=new A.C("scopeRowId",B.T,"Restrict this tile to the CONTAINS-subtree rooted at this row: a literal row id or a `$`-token (`$rowId`, `$selected:<table>`). The ROOT ROW ITSELF IS INCLUDED (same contract as `cards.scopeRowId`). Unset (absent) = unchanged, whole-table behavior. Configured but UNRESOLVED (e.g. `$selected:` with nothing selected) fails CLOSED to the empty set \u2014 never silently falls back to the whole board.",B.k,null,!1)
B.Gg=new A.C("scopeEdgeFrom",B.K,'With `scopeRowId`: the edge\'s parent-id column (default "from"; set explicitly when the edges table differs, e.g. "fromId").',B.k,null,!1)
B.Gh=new A.C("scopeDepth",B.aM,"With `scopeRowId` (dispfb-1018): `1` narrows the scope to the root's DIRECT children only, root excluded. Absent = whole subtree, root-inclusive (unchanged).",B.k,null,!1)
B.G6=new A.C("excludeTypes",B.a_,'Drop rows whose `typeColumn` value is in this list, BEFORE aggregation. The second predicate `filter` (single-column) can not express: because `scopeRowId` includes the root row and every sub-container under it, a status-filtered scoped count otherwise counts the containers themselves. Same two keys as `priolanes` (e.g. `typeColumn: "type"`, `excludeTypes: ["group","note"]`). Absent/empty = unchanged.',B.k,null,!1)
B.Gm=new A.C("typeColumn",B.K,'Column holding the row\'s type, read by `excludeTypes` (default "type").',B.k,null,!1)
B.Gk=new A.C("excludeArchived",B.ab,'dufb17a-0924: drop rows hidden by the ARCHIVE lifecycle (rows whose incoming edges are all type "archived", plus their contains-subtrees) before rendering/aggregation. Scoped views already never reach them; this covers whole-table use. Absent/false = unchanged.',B.k,null,!1)
