B.he5=new A.C("titleColumn",B.K,"Bar label column (default title).",B.k,null,!1)
B.hd3=new A.C("laneColumn",B.K,"Optional \u2014 group rows sharing this column's value onto ONE lane (one visual row) instead of one row per row, e.g. several bars for the same session. Lanes order by first appearance (earliest start among their rows); overlapping bars within a lane stack onto an extra sub-row rather than overdraw. Each bar keeps its own start/end/status coloring and tap-to-detail. Unset draws one row per row, byte-identical to before this prop existed.",B.k,null,!1)
B.h82=new A.C("laneLabelColumn",B.K,"With laneColumn set, the column whose value (read off the lane's earliest-starting row) labels the lane; default falls back to that row's titleColumn value, then the raw lane value. Ignored without laneColumn.",B.k,null,!1)
B.hbF=new A.C("statusColors",B.a_,'Optional {statusValue: colorName} map (colorName one of green/blue/amber/red/grey/purple) overriding the default done/doing/todo bar coloring \u2014 e.g. {"landed":"green","inFlight":"blue","waiting":"amber"}. Absent keeps the original scheme.',B.k,null,!1)
B.h3Q=new A.C("dashedStatuses",B.a_,'List of status values (from statusColumn) whose bar draws a dashed outline instead of a solid fill \u2014 pairs with statusColors to mark e.g. "in flight" work distinctly from "landed".',B.k,null,!1)
B.h7k=new A.C("expandFields",B.a_,"Fields shown in a bar's tap detail (same shape as cards' expandFields: a list of {column, label}). Tapping a bar opens a read-only detail surface \u2014 a centered popup Dialog by default, a full-screen push when detailMode is \"push\" \u2014 never a bottom sheet.",B.k,null,!1)
B.hgX=new A.C("todayLabel",B.T,'Optional bright text (e.g. "HERE") drawn beside the today line. Unset draws just the line, byte-identical to before this prop existed.',B.k,null,!1)
B.h7h=new A.C("todayColor",B.T,"Optional colour for the today marker line \u2014 one of the same named ramp values as statusColors (green/blue/amber/red/grey/purple), or a #RGB/#RRGGBB/#AARRGGBB hex string. Use this to move the marker off red when red is already reserved as the one blocked-status accent. Unset/unrecognized keeps the original hard-coded red, byte-identical to before this prop existed.",B.k,null,!1)
B.fX5=new A.C("height",B.T,'Optional height. Unset with an UNBOUNDED slot (desktop / page scroll) keeps the historic intrinsic content height. Given a BOUNDED slot (phone) \u2014 or an explicit value \u2014 the timeline fills that height and pans INTERNALLY on both axes (a long plan gets a legible per-day width and scrolls sideways instead of squeezing). Accepts a number (logical px), "fill" (the full available body height, scrolling/panning internally), or "<frac>fill" (e.g. "0.55fill").',B.k,null,!1)
B.h4B=new A.C("filter",B.a_,"Static pre-filter { column, value|in } \u2014 OR a LIST of such maps, ANDed (same shape as `cards`' filter) \u2014 narrows the source rows before building the tree, e.g. keeping a shared table's member/comment rows off the timeline, or combining a kind gate with a board scope.",B.k,null,!1)
