B.fVT=new A.C("twoFingerHoldMs",B.aM,"How long (ms) a stroke must be going before a 2nd finger is ignored (keeps your mark) instead of starting a zoom (erases the tiny start). Default 250; 0\u20135000.",B.k,"Two-finger hold (ms)",!1)
B.h1_=new A.C("iconMode",B.ab,'Icon-authoring aids on the (already-square) canvas: a rule-of-thirds + centre-cross guide overlay, a live ~32px corner preview, and an "Export icon set" menu entry bundling PNGs at 16\u20131024px plus one full-size PNG into a .zip.',B.k,"Icon mode",!1)
