B.hhN=new A.C("trashColumn",B.K,"Bool column for soft-delete; set it to enable a recoverable Trash. Omit for hard delete.",B.k,null,!1)
B.fV4=new A.C("maxDepth",B.aM,"Optional cap on folder nesting depth.",B.k,null,!1)
B.h8j=new A.C("detail",B.tS,'Node rendered for the selected file; its "rowId" (and "table") are injected so it binds to that row.',B.k,null,!1)
B.h6G=new A.C("title",B.T,'Rail header label (default "Files"); may be a {lang: text} map.',B.k,null,!0)
B.he1=new A.C("railTitle2",B.T,'Two-level rail: fixed title for column 2 (e.g. "Tasks"); unset = the selected project\'s name. May be a {lang: text} map.',B.k,null,!0)
B.h42=new A.C("treeRail",B.ab,"Two-level: column 1 becomes a DIRECTORY TREE \u2014 folders nest (sub-projects), non-folders are leaves, and the tree never descends into a non-folder (a task's children are its log). Column 2 then lists the selected folder's non-folder children only.",B.k,null,!1)
B.hcy=new A.C("rail2Folders",B.ab,"Two-level + treeRail: ALSO list the selected project's SUB-PROJECTS (child folders) at the top of column 2, above its tasks \u2014 tapping one drills into it (becomes column 2's root). Off = column 2 is tasks only.",B.k,null,!1)
B.h_8=new A.C("searchSource",B.T,'Set "app" so the GLOBAL app-header search (board.searchQuery) filters the directory: while a query is active it shows a flat list of name-matching rows instead of the nested tree.',B.k,null,!1)
B.fYE=new A.C("viewToggle",B.ab,"Two-level: show a Tree/Cards toggle in column 1. Tree = the nesting directory outline; Cards = a Finder-column card browser of the current level (tap a card selects it \u2014 its tasks open in the column to the side \u2014 and a dropdown/dropup chevron peeks its children inline). Off = tree only (unchanged).",B.k,null,!1)
B.hgq=new A.C("defaultView",B.T,'Initial view when viewToggle is on: "tree" or "cards". Unset \u2192 tree on a wide layout, cards on a narrow (phone) one. "today" (disphybrid-1111, needs todayStrip) opens on the grouped Today list.',B.k,null,!1)
B.fXM=new A.C("viewActions",B.a_,'mokugaps-1019: per-option action for the view toggle (Tree/Cards/Starred) \u2014 `{"tree"|"cards"|"starred": {fn, args}}`, fired when the person picks that option (like a segment\'s `action`). A `goto` navigates away and keeps this view. Absent = the plain local switch.',B.k,null,!1)
B.dhh=s(["tree","cards"],t.s)
B.fZL=new A.C("narrowDefaultView",B.bU,"mokugaps-1019: the phone (narrow two-level) layout's Tree/Cards switch opens on this. Unset \u2192 cards (unchanged).",B.dhh,null,!1)
B.h5J=new A.C("narrowViewActions",B.a_,'mokugaps-1019: per-option action for the phone Tree/Cards switch \u2014 `{"tree"|"cards": {fn, args}}`; same contract as viewActions.',B.k,null,!1)
B.h6z=new A.C("starredTab",B.ab,'Adds a third "Starred" segment to the Tree/Cards toggle: a flat, fast list of every starred row (folder or leaf) at ANY depth in this table, for one-tap access. Requires starColumn; a no-op without one.',B.k,null,!1)
B.hh_=new A.C("archiveEnabled",B.ab,'dufb17a-0924: opt-in ARCHIVE lifecycle (edges-mode only). A layer orthogonal to status: the row menu gains Archive/Unarchive, which flips the row\'s incoming contains edge(s) to type "archived" and back (retire-never-delete; the row itself is never rewritten or deleted, no other edge is touched; a top-level row gets a single empty-parent archived marker edge). Archived rows leave the tree/cards/Starred/search views and every rollup; archiving a folder hides its whole subtree and unarchiving restores it as it was. An "Archived (N)" disclosure at the foot of the rail lists them dimmed with Unarchive. Off (default) = unchanged.',B.k,null,!1)
B.hfo=new A.C("showChildCounts",B.ab,'Two-level task cards show a "N <noun>" count of their children.',B.k,null,!1)
B.hiv=new A.C("childCountLabel",B.T,'Singular|plural noun for the child count (default "item|items"); may be a {lang: text} map (resolved before the "|" split).',B.k,null,!0)
B.h9A=new A.C("expandUntilSelected",B.ab,"Two-level: while nothing is selected, column 2 expands to fill the remaining width (the empty detail pane is hidden); selecting a row restores the fixed rail + detail layout.",B.k,null,!1)
B.fXB=new A.C("dense",B.ab,"Tighter vertical margins/paddings on rail tiles (flat and tree rows) so more rows fit per screen.",B.k,null,!1)
B.fUX=new A.C("showProgress",B.ab,'Each folder row shows a thin bar + "NN%" \u2014 DONE/TOTAL among its TASK descendants (kindColumn == fileValue) rolled up over the whole contains-subtree; notes/attachments/sub-groups are excluded. Requires statusColumn; a folder with no task descendants shows nothing.',B.k,null,!1)
B.fUR=new A.C("breadcrumb",B.ab,"Show the selected node's ancestor path above the detail (edges-mode).",B.k,null,!1)
B.fTf=new A.C("alongside",B.ab,"Opt-in: allow opening a second file beside the first (dismissible; tabs on phone).",B.k,null,!1)
B.fZR=new A.C("menuActions",B.a_,'Host-defined row-menu extras: [{label, folderOnly?, fileOnly?, rootOnly?, action:{fn,args}}] \u2014 each fires with the row\'s id (e.g. "Export project\u2026"); rootOnly shows it on top-level rows only.',B.k,null,!1)
B.ha4=new A.C("uiCreateActions",B.a_,'Engine-built CREATE entries by name (explorer_ui_actions.dart), each with its own engine-localized label + visibility, appended to the landing / New menu items and (with focusRoot + childAdd) to the "+ New <child>" chooser: "composeStartFromPrompt" (Moku "Start from a prompt\u2026": popup \u2192 blank scenario \u2192 co-build panel pre-filled). Unknown names are ignored.',B.k,null,!1)
B.fZk=new A.C("uiMenuActions",B.a_,'Engine-built row-menu entries by name (explorer_ui_actions.dart), each with its own engine-localized label and per-row visibility: "composeProposeToApp" (Moku scenario of a mirror-bound board \u2192 Propose to app) and "composeProposals" (mirror-bound main board \u2192 its Proposals list). Unknown names are ignored.',B.k,null,!1)
B.h5Q=new A.C("fileIcon",B.T,"File icon hint: image | draw | doc | sheet | note (default file).",B.k,null,!1)
B.h7N=new A.C("newFileLabel",B.T,"Tooltip for the new-file button; may be a {lang: text} map.",B.k,null,!0)
B.fZF=new A.C("newFolderLabel",B.T,"Tooltip for the new-folder button; may be a {lang: text} map.",B.k,null,!0)
B.fXt=new A.C("allowAdd",B.ab,"false hides every new-file/new-folder affordance \u2014 a registry-style explorer that is browsed here, authored elsewhere.",B.k,null,!1)
B.h2d=new A.C("leafChildKinds",B.a_,'Sub-leaf tree: child kindColumn values of a LEAF shown nested under it in the tasks column (e.g. ["task"] = sub-tasks). Other children (the leaf\'s log) stay out of the rails. Leaf \u22ee menus gain a create-sub-leaf item.',B.k,null,!1)
B.fTq=new A.C("leafAttachmentKinds",B.a_,'Child kindColumn values of a LEAF shown as TERMINAL attachment leaves under it (e.g. ["wireframe","docs","image"]): no expand chevron, and a tap opens the item full-screen. Unlike leafChildKinds these never descend \u2014 lets a task\'s attachments appear in the directory tree.',B.k,null,!1)
B.fZH=new A.C("newSubLeafLabel",B.T,'Label for the leaf \u22ee create-sub-leaf item (default "New sub-item here"); may be a {lang: text} map.',B.k,null,!0)
B.heZ=new A.C("railWidth",B.aM,"Left rail width on wide screens (default 260).",B.k,null,!1)
B.fUU=new A.C("railResizable",B.ab,"Opt-out (default true): a click-drag handle on the single rail's edge (wide layouts only) lets the user resize it live, between ~240dp and min(560dp, 50% of the available width); double-tap/ double-click resets to railWidth. The chosen width persists via the same explorerLayout LocalPrefs entry the two-level rail already uses.",B.k,null,!1)
B.hbO=new A.C("orderColumn",B.K,"Numeric column ordering the rail (e.g. a user-set position from drag-reorder); unset \u2192 name order.",B.k,null,!1)
B.h6E=new A.C("allowFolders",B.ab,"false hides folder creation and treats the tree as files-only.",B.k,null,!1)
B.h3b=new A.C("folderTapExpands",B.ab,"Recursive-mode opt-in: tapping a FOLDER row ALSO toggles its expansion (the familiar file-tree feel) in addition to selecting it. Off by default (row-tap = select only).",B.k,null,!1)
B.h9v=new A.C("tapOpens",B.ab,'Tap opens (house rule 7). DEFAULT true: a detail whose root column has a direct-child `goto` button (the old "Open this file" step) is opened by tapping/Enter on the row itself, and that button is not drawn. `false` keeps the two-step flow (select, then press the button) \u2014 only for a screen that genuinely needs it.',B.k,null,!1)
B.h_z=new A.C("railWidth1",B.aM,"Two-level rail: column 1 width on wide screens (default 200).",B.k,null,!1)
B.h7c=new A.C("railWidth2",B.aM,"Two-level rail: column 2 width on wide screens (default = railWidth).",B.k,null,!1)
B.fXa=new A.C("autoSelectFirst",B.ab,"Select the first row automatically once rows load (pairs with startBlank for an open-something-immediately explorer).",B.k,null,!1)
B.h2v=new A.C("scopeTargets",B.a_,"Restrict the explorer to these subtree root ids (scope the directory to a branch instead of the whole table).",B.k,null,!1)
B.h8L=new A.C("nestedScopeTargets",B.a_,'A SECOND level of `scopeTargets`-shaped nesting for a `scopeTargets` entry whose own child rows are never a second `explorer` screen \u2014 a JSON object keyed by one of `scopeTargets`\' own tables, each value the SAME `[{table, column}]` list shape as `scopeTargets` itself, e.g. `{"screens": [{"table":"widgets","column":"screen"}, {"table":"pins","column":"screen"}]}`. The normal case (docs/notes/ bublie) needs nothing here: a `scopeTargets` child that IS its own `explorer` screen already gets this discovered for free by walking that screen\'s own `scopeTargets`/`scopeColumn`. This key exists for a scope-target whose children live inside one custom canvas node instead (composer: a board\'s `screens` row owns `widgets`/`pins`/ `frameImages` rows entirely inside the `compose` node, never a second Explorer) \u2014 the host\'s library-shape discovery (e.g. isan\'s `discoverLibraryShape`) reads this key explicitly so file export/ import can still capture those rows. Purely additive/opt-in \u2014 absent for every explorer that predates this key.',B.k,null,!1)
B.hcP=new A.C("scopeColumn",B.K,"Second-level nesting: further filter this explorer's own rail to rows whose value in this column matches the board's ACTIVE [setScope] value for (table, scopeColumn) \u2014 the scope an ANCESTOR explorer wrote via its own scopeTargets (e.g. Files > Boards).",B.k,null,!1)
B.d3w=s(["drawer","collapsible","none","tabs"],t.s)
B.fUh=new A.C("railMode",B.bU,'How the file tree shows. "drawer" hides it behind a hamburger that slides it in as an overlay; "collapsible" shows the rail with a chevron that hides it (explorer.dart); "none" renders only the detail; "tabs" shows the leaves as a horizontal TAB STRIP above (default) or below the detail \u2014 worksheet tabs \u2014 placed by tabsSetting / tabsPosition (sheettabs-1107); default is a fixed side rail.',B.d3w,null,!1)
B.hcT=new A.C("tabsSetting",B.T,'railMode "tabs" only: board-setting KEY whose live value places the strip \u2014 "top" | "bottom" | "side" (side = the classic side rail; falls back to top at phone width). Unset/unknown values use tabsPosition. Durable only when the app allow-lists the key (durableSettings).',B.k,null,!1)
B.dhe=s(["top","bottom","side"],t.s)
B.fW6=new A.C("tabsPosition",B.bU,'railMode "tabs" only: where the strip sits when tabsSetting is unset (default "top").',B.dhe,null,!1)
B.hi8=new A.C("tabsHiddenColumn",B.K,'railMode "tabs" only: a boolean column; rows where it is true (hidden worksheets) are left out of the strip.',B.k,null,!1)
B.hak=new A.C("startBlank",B.ab,'With nothing selected, render the detail child unbound + blank (e.g. a fresh draw canvas) instead of a "select a file" placeholder.',B.k,null,!1)
B.fYP=new A.C("emptyHome",B.ab,'With nothing selected, render a landing Home (new-file actions + recent files) instead of the "select a file" placeholder. Opening and creating are both optional \u2014 nothing auto-opens or auto-creates. startBlank takes precedence when both are set.',B.k,"Show a Home when nothing is open",!1)
B.h0_=new A.C("homeTitle",B.T,"Home heading; defaults to the rail title. May be a {lang: text} map.",B.k,null,!0)
B.h12=new A.C("homeSubtitle",B.T,"Muted line under the Home heading; omitted when unset. May be a {lang: text} map.",B.k,null,!0)
B.fYk=new A.C("recencyColumn",B.K,"Sort column for the Home's Recent list (newest first); defaults to orderColumn.",B.k,null,!1)
B.hhB=new A.C("completedByColumn",B.K,"Opt-in: ref column stamped with the actor when a row's status is set to doneStatus (cleared when it moves off done).",B.k,null,!1)
B.fVG=new A.C("finishedAtColumn",B.K,"Opt-in: date column stamped with today when status becomes doneStatus (cleared when it moves off done \u2014 an empty finish date is a fact).",B.k,null,!1)
B.hbq=new A.C("doneStatus",B.T,'The statusColumn value that counts as "done" for completion stamping (default "done").',B.k,null,!1)
B.h8F=new A.C("defaultActor",B.T,"Row id used as the completer when the signed-in user is not a row of the completedBy ref's table (else the first row).",B.k,null,!1)
B.h2f=new A.C("fileIconByKind",B.ab,"Resolve each leaf's icon from its own kindColumn value (a distinct glyph per row) instead of one shared fileIcon.",B.k,null,!1)
B.fV3=new A.C("addItems",B.a_,'Extra typed "New <x>" actions beyond New file: [{label, icon, values}] \u2014 each stamps values on the new leaf (e.g. {kind:"doc"}); shown as one "New" menu. An entry may instead give {label, icon, action:{fn,args}} (e.g. Mokup\'s "New from template", firing instantiateTemplate) \u2014 the action fires directly and no leaf is created here, for an action that mints its own root row. `action` wins over `values` if an entry has both.',B.k,null,!1)
B.fWF=new A.C("edgesTable",B.b1,"Opt-in GRAPH/edges-mode: relations table (rows {from,to,type}) that resolves parent\u2192child instead of the single parentColumn \u2014 a node can have MANY parents (many-to-many) and shows under each. Null (default) = classic single-parent tree.",B.k,null,!1)
B.hcn=new A.C("edgeFrom",B.K,'Edges-mode: source-id column on edgesTable (default "from").',B.k,null,!1)
B.hg1=new A.C("edgeTo",B.K,'Edges-mode: target-id column on edgesTable (default "to").',B.k,null,!1)
B.fWp=new A.C("edgeType",B.K,'Edges-mode: edge-kind column on edgesTable (default "type").',B.k,null,!1)
B.h7Z=new A.C("containsType",B.T,'Edges-mode: edgeType value meaning "contains" (default "contains").',B.k,null,!1)
B.h54=new A.C("sharedBadge",B.ab,'Edges-mode: show a small "also in N" chip on a node with more than one incoming contains-edge (lives under several parents).',B.k,null,!1)
B.fVQ=new A.C("inboxColumn",B.K,'ideasgraft-1026 (classic parentColumn mode): opt-in capture INBOX \u2014 a boolean column. A new TOP-LEVEL leaf is stamped true and lists in an "Inbox \xb7 N" section above the tree (and on the phone landing) instead of in it; the row menu and the open row\'s filing strip gain "File into\u2026" \u2014 a full-view picker of ONE home (or the top level) that sets parentColumn and clears the flag. Cycle-guarded.',B.k,null,!1)
B.fXr=new A.C("schedule",B.a_,'ideastime-1027: opt-in SCHEDULE strip under the open row: {dateColumn, timeColumn?, kindColumn?, doneColumn?, noneValue?, kinds: [{value, label, color?, done?}]}. Shows "Schedule\u2026" when the row has no date/kind, else kind \xb7 date \xb7 time; tapping opens a full popup to set or remove the schedule (one undo step).',B.k,null,!1)
B.fUP=new A.C("place",B.a_,'ideasgeo-1027: opt-in PLACE strip under the schedule strip: {whereColumn, nameColumn?}. Shows "Set place\u2026" when the row has no pin/name, else the place name (or coordinates); tapping opens a full popup with a name field and the map-pin picker (Save/Remove write both columns in one undo step). whereColumn holds "lat, lng".',B.k,null,!1)
B.h2U=new A.C("pageTools",B.a_,'pagetools-m1-1031: declare engine PAGE TOOLS for this table instead of hand-wiring them: {tools: ["schedule", "place"], <tool>: {overrides}}. Each tool resolves to its registry defaults (page_tools.dart: schedule = when/whenTime/scheduleKind/done + to-do/appointment/event kinds; place = where/place) with per-tool overrides merged over them. An explicit schedule/place key wins. Lint: a declared tool\'s columns must exist on the table.',B.k,null,!1)
B.h_s=new A.C("graftsTable",B.b1,'ideasgraft-1026 (classic mode): opt-in GRAFTS \u2014 a table of typed containment edges {graftFromColumn: branch, graftToColumn: row, graftTypeColumn: graftType} attaching a row as a leaf under extra branches. The row menu and filing strip gain "Also file under\u2026" (tick/untick places). parentColumn stays the single primary home; grafting under the row itself or anything under it is refused.',B.k,null,!1)
B.fTd=new A.C("graftFromColumn",B.K,'graftsTable column holding the BRANCH id (default "fromId").',B.k,null,!1)
B.heJ=new A.C("graftToColumn",B.K,'graftsTable column holding the grafted row id (default "toId").',B.k,null,!1)
B.h7e=new A.C("graftTypeColumn",B.K,'graftsTable column holding the edge type (default "type").',B.k,null,!1)
B.h6f=new A.C("graftType",B.T,'Edge type value meaning "grafted under" (default "graft").',B.k,null,!1)
B.heS=new A.C("badgeColumn",B.K,"Generic badge: any row whose <badgeColumn> boolean field is true shows a small badge icon, independent of edges-mode/sharing \u2014 works on any explorer (e.g. flag rows with an inherited property).",B.k,null,!1)
B.h6V=new A.C("starColumn",B.K,"Generic star: every row gets a tap-to-toggle star icon bound to this boolean column, and starred rows sort ahead of unstarred siblings at the same level (folders still sort before files).",B.k,null,!1)
B.hfO=new A.C("shareAware",B.ab,"Opt-out (default true): when the host has wired a ShareInfoProvider/AccessResolver (project sharing), this explorer shows the share people-chip + accent stripe and honors capability gating on add/rename/delete/drag. Set false to exempt this explorer even when the host's hooks are wired globally. Inert when the host wires no hooks.",B.k,null,!1)
B.h8f=new A.C("nameFromColumn",B.K,'Opt-in: a leaf whose name column is empty shows the first line of THIS column (the note body) as its name, else a localized "New note". Display only; nothing is written.',B.k,null,!1)
B.h7a=new A.C("quickCreate",B.ab,"Opt-in quick capture: New file creates an empty-named leaf in the current folder (or top level), selects it, and skips the rename prompt \u2014 no folder choice up front. Pair with nameFromColumn.",B.k,null,!1)
B.fW5=new A.C("moveToFolder",B.ab,'Opt-in, parentColumn mode: file items into folders after the fact \u2014 row \u22ee "Move to folder\u2026" (centered popup, works on phone) plus drag a row onto a folder (mouse drag / touch long-press) and a top-level drop zone while dragging. One undoable parent write + Undo toast.',B.k,null,!1)
B.hfG=new A.C("dragReparent",B.ab,"Edges-mode: drag a row onto another to re-parent it \u2014 moves the grabbed contains-edge to the drop target, cycle-guarded with undo.",B.k,null,!1)
B.hha=new A.C("fileValue",B.T,'kindColumn value stamped on a new leaf (non-folder); default "file" \u2014 set when kindColumn is an enum without a literal "file" value.',B.k,null,!1)
B.h5U=new A.C("initiallyExpanded",B.ab,"Open every folder on first build (a grouped-list feel) instead of a collapsed tree the user must expand.",B.k,null,!1)
B.hdK=new A.C("listOnly",B.ab,'Render just the rail \u2014 a clean full-width list with no always-shown detail pane; a row\'s \u22ee "View detail" opens the detail node in a dialog on demand.',B.k,null,!1)
B.haS=new A.C("convertible",B.ab,'Row menu offers "Make a folder" (on a file) / "Make a file" (on a folder, \u22641 child) \u2014 spins owned child rows + carry-column content to/from a fresh child so nothing is lost.',B.k,null,!1)
B.h3K=new A.C("ownedTables",B.a_,"Convertible: child tables this node OWNS via a column == the node id (e.g. {table: updates, column: nodeId}); their rows re-parent on convert.",B.k,null,!1)
B.fTc=new A.C("carryColumns",B.a_,"Convertible: column names whose value travels to the new child on file\u2192folder, and back on folder\u2192file.",B.k,null,!1)
B.h1O=new A.C("convertToFolderLabel",B.T,'Convertible: row-menu label for the file\u2192folder action (default "Make a folder"); may be a {lang: text} map.',B.k,null,!0)
B.fTC=new A.C("convertToFileLabel",B.T,'Convertible: row-menu label for the folder\u2192file action (default "Make a file"); may be a {lang: text} map.',B.k,null,!0)
B.fZw=new A.C("previewLines",B.aM,"Descriptive leaf rows: show the name across up to N lines (default 1) \u2014 folders always stay 1-line.",B.k,null,!1)
B.h1X=new A.C("titleMaxLines",B.aM,"Ceiling on how many lines a leaf row TITLE itself may wrap to (default 2, minimum 1) \u2014 independent of previewLines, which still governs the comment preview below it. A narrow tree column can set this to 1 so a row stays a compact title + single preview line instead of stacking a 2-line title on top of a multi-line preview.",B.k,null,!1)
B.hds=new A.C("itemViewOnCreate",B.ab,'Adding a new leaf opens the read-only item view (title autofocused, comment placeholder) instead of the classic auto-"Rename" popup; abandoning it with both fields still blank deletes the row outright instead of leaving it "Untitled". Folders are unaffected \u2014 they keep the Rename prompt.',B.k,null,!1)
B.h8c=new A.C("titleFromFirstLine",B.ab,"Opt-in (needs itemViewOnCreate + commentColumn): a new leaf saved from the item view with an empty title takes its title from the first line of the comment/body (same rule as the notepad prop of the same name; a typed title is never overwritten).",B.k,null,!1)
B.h8m=new A.C("titleAutoColumn",B.K,'Memo column for explorer titleFromFirstLine (default "titleAuto"); keep it equal to the detail notepad\'s titleAutoColumn.',B.k,null,!1)
B.heA=new A.C("commentColumn",B.K,"Optional free-text column shown as a second preview line under a leaf row's title (real content, or a grey-italic \"Comment\" placeholder when empty) and, with itemViewOnCreate, as the item view's comment box.",B.k,null,!1)
B.fZj=new A.C("commentEmptyText",B.T,'What the tree-row preview line says for a row whose commentColumn is empty. Unset keeps the grey-italic "Comment" placeholder; an empty string shows no second line; text may be a {lang: text} map.',B.k,null,!0)
B.hac=new A.C("tags",B.a_,'Leaf rows: colored chips beneath the name, pairing with previewLines for a "cards" look in a flat list.',B.k,null,!1)
B.h27=new A.C("statusColumn",B.K,'Status quick-set: when set, a row\'s \u22ee menu offers "Status: <value>" per statusOptions entry, writing it to this column (one undo step).',B.k,null,!1)
B.fTZ=new A.C("statusOptions",B.a_,"List of status values offered by the statusColumn quick-set menu.",B.k,null,!1)
B.h_o=new A.C("prioColumn",B.K,'Priority quick-set (priolanes2-0726): same idiom as statusColumn \u2014 a row\'s \u22ee menu offers "Priority: <value>" per prioOptions entry (plus a Clear item once set), writing it to this column (one undo step). Engine-generic; Dispatch wires it to `prioLane`.',B.k,null,!1)
B.hdn=new A.C("prioOptions",B.a_,"List of priority values offered by the prioColumn quick-set menu.",B.k,null,!1)
B.fVx=new A.C("prioLabels",B.a_,"Optional {value: label} display overrides for prioOptions entries; unset values show their raw string.",B.k,null,!1)
B.h59=new A.C("recursive",B.ab,'An item can have BOTH its own detail AND children (no folder/file split) \u2014 every selected item shows its detail, any item with children is expandable, and "New <item>"/addItems add a child of the selected item.',B.k,null,!1)
B.hgr=new A.C("ownerColumn",B.K,"When set AND a rowId is injected (this explorer is itself a master-detail DETAIL child), the list filters to rows whose value in this column equals that injected id, and new rows are stamped with it.",B.k,null,!1)
B.hfZ=new A.C("detailedView",B.ab,"Two-level rail: column 2 (contents) offers a Directory \u27f7 Detailed toggle in its header \u2014 compact rows vs. a per-row progress DASHBOARD (status chip, progress bar, subtask/log-entry counts, the existing `tags` chips for priority/importance/due/assignee, and a one-line latest-activity preview), plus a compact done/active/queued rollup summary + bar at the top of the column for the open folder. Reads the existing showProgress rollup cache; never a second board walk.",B.k,null,!1)
B.de3=s(["plain","rich"],t.s)
B.h5M=new A.C("folderCardStyle",B.bU,'detailedView: folder-row card style. "plain" (default, unchanged) | "rich" \u2014 primary-tinted folder surface, badge icon, a "N tasks \xb7 M sub-projects \xb7 K files" counts line (files = whole-subtree attachment count), a one-row chip strip of the folder\'s direct attachments (leafAttachmentKinds; omitted when dense) and a "No tasks yet" line for task-less folders.',B.de3,null,!1)
B.h0l=new A.C("folderCardImageColumn",B.T,'folderCardStyle "rich": column on an image attachment row holding its picture (data-uri/url or [{mime,data}] list) for the chip thumbnail. Default "attachment".',B.k,null,!1)
B.d3p=s(["directory","detailed"],t.s)
B.fTT=new A.C("defaultContentsView",B.bU,'detailedView: initial column-2 toggle state. Unset \u2192 "directory" (unchanged compact rows on first open).',B.d3p,null,!1)
B.h4r=new A.C("projectOverview",B.ab,"Opt-in PER-PROJECT overview dashboard \u2014 a third Tasks \u21c4 Overview segment in column 2's (contents) header, alongside the existing detailedView Directory/Detailed toggle. Off by default so no existing applet's UI changes. When on, selecting a project can switch its contents column to a computed bar/pie breakdown of every item in that project's contains-subtree. See overviewTagsColumn/overviewTypeColumn for the two breakdown columns.",B.k,null,!1)
B.h9O=new A.C("valueLabels",B.a_,"Opt-in raw-value \u2192 display map for rendered DATA VALUES (tree row status/tag chips, the projectOverview by-status/by-tag/by-type chart bucket labels): {raw: text-or-{lang:text}} or column-keyed {column: {raw: ...}}, resolved against the ambient locale; unmapped values render exactly as before (passthrough, never blank). Display-only \u2014 stored values, filter payloads and tag `colors` keys stay RAW.",B.k,null,!1)
B.h6F=new A.C("overviewTagsColumn",B.K,"projectOverview: the multi-value (List<String>) column the overview's \"by tag\" bar chart buckets on \u2014 each item can carry more than one tag, so every tag it holds counts once in that tag's bucket (a scalar column works too; each row then counts once under its own value). Unset hides the tag breakdown.",B.k,null,!1)
B.hcY=new A.C("overviewTypeColumn",B.K,'projectOverview: the scalar column the overview\'s "by type" bar chart buckets on (e.g. group/task/note/goal/milestone/...). Unset hides that breakdown.',B.k,null,!1)
B.h9V=new A.C("overviewMarkerColumns",B.mD,"projectOverview: boolean columns (e.g. bottleneck/blocked) whose true value marks an item as needing attention in the overview's \"Needs attention\" section \u2014 one group per configured column, titled by that column's own schema label. Empty (default) adds no marker groups; the no-responsible-person and stale groups are always generic and still show.",B.k,null,!1)
B.h5t=new A.C("overviewDueColumn",B.K,"projectOverview: the date column read for the overview's Overdue needs-attention group. Unset skips the Overdue group entirely.",B.k,null,!1)
B.fY3=new A.C("overviewLogColumn",B.K,"projdash-0810 fix-forward: boolean column marking a descendant as LOG CHATTER (an entrythread comment/reply) rather than a first-class project item \u2014 the SAME column an entrythread node's own opt-in `logEntryColumn` stamps true on every composed entry. When set, projectOverview's item population (`_overviewDescendants`) excludes flagged rows from the headline count, the status/tag/type breakdowns and the item list \u2014 a task with 300 log comments no longer inflates \"items total\" or the active-status pie. Unset (default) is a no-op: nothing is excluded, matching pre-fix behavior. Attachment-kind children (`leafAttachmentKinds`) are excluded unconditionally, no config needed.",B.k,null,!1)
B.fXe=new A.C("activeStatus",B.T,'detailedView: statusColumn value counted as "active" in the active/queued split (default "active").',B.k,null,!1)
B.fXH=new A.C("queuedStatus",B.T,'detailedView: statusColumn value counted as "queued" (default "queued").',B.k,null,!1)
B.fU7=new A.C("activityColumn",B.K,'detailedView: column holding the text shown as a row\'s one-line latest-activity/comment preview (default "comment").',B.k,null,!1)
B.hc6=new A.C("activityTimeColumn",B.K,'detailedView: column used to find the most recent child/descendant for the latest-activity preview (default "postedAt"); must resolve to a parseable date/dateTime column.',B.k,null,!1)
B.hc0=new A.C("alwaysShowDetail",B.ab,'Two-level, wide layout: when a project (folder) is selected/opened and no child ends up auto-selected, show the project\'s OWN detail (requires `recursive`) instead of the "pick a task" placeholder.',B.k,null,!1)
B.hip=new A.C("detailKindLabel",B.ab,'Show a small "Project"/"Task" header label above the detail pane\'s content \u2014 nouns derived from newFolderLabel/newFileLabel (strip a leading "New "), override via folderNoun/fileNoun.',B.k,null,!1)
B.h8z=new A.C("folderNoun",B.T,'detailKindLabel override: the noun shown for a folder ("Project"). May be a {lang: text} map.',B.k,null,!0)
B.h9J=new A.C("fileNoun",B.T,'detailKindLabel override: the noun shown for a leaf ("Task"). May be a {lang: text} map.',B.k,null,!0)
B.hbC=new A.C("settingsAction",B.a_,"Opt-in: {fn, args?, label?} \u2014 a gear affordance shown next to a selected FOLDER's detail header, fired with that row's id (like menuActions, but a single, separate surface for FEATURE settings \u2014 e.g. sharing/members \u2014 kept distinct from the row \u22ee menu's quick actions and from the attributes/edit-details form's data fields).",B.k,null,!1)
B.fVb=new A.C("rootDashboard",B.ab,'Two-level rail: the synthetic root ("Projects", nothing selected) gets a COMPUTED cross-project progress dashboard as its detail \u2014 overall done/active/queued rollup plus one row per top-level project \u2014 built from the existing showProgress rollup cache. The root stays synthetic: no new record, no reparenting.',B.k,null,!1)
B.fVI=new A.C("filterable",B.ab,"Opt-in per-column filtering of the TASKS/children column (the two-level rail's column 2, and the narrow children-directory list) via the unified Add-filter engine \u2014 mirrors agenda/tree/cards/report's own \"filterable\" opt-in (AddFilterBar<Record> + applyColFilters). Off (default) renders exactly as before. Session-scoped state only; the pinned strip and the projects (column-1/root) list are never filtered.",B.k,null,!1)
B.hbN=new A.C("filterGroups",B.a_,'Config-defined sections for the Filter config view\'s field list: [{"label": "Workflow" or {"en": ..., "ko": ...}, "columns": ["type", "status"]}]. Listed groups render first in config order (columns in listed order); columns no group lists fall back to the automatic sections (Status & lanes / People / Dates / Text / More). Absent = automatic sections only.',B.k,null,!1)
B.fVD=new A.C("filterPresets",B.a_,'Built-in filter presets shipped by the applet: [{"name": "Done" or {"en": ..., "ko": ...}, "orMode": false, "filters": {"status": {"selected": ["done"]}}}] (the saved-preset JSON shape). Listed ahead of the user\'s own presets, lock-marked and read-only (no rename/overwrite/delete; never stored with user presets).',B.k,null,!1)
B.hcr=new A.C("statusLegend",B.a_,'Opt-in (dufb-1017): [{"value": "superseded", "label": {lang: text}, "meaning": {lang: text}}] \u2014 an info button beside the contents column\'s filter/sort pops a floating list of every status with its one-line meaning.',B.k,null,!1)
B.fXP=new A.C("detailGutter",B.aM,"dispfb-1018: horizontal gutter (px, house token scale 4/8/12/16/24) applied at the DETAIL PANE container so every section inherits it instead of sitting flush against the panel divider. Absent/0 = unchanged.",B.k,null,!1)
B.fY6=new A.C("selectShowsProject",B.ab,"Opt-in (dufb-1017, needs recursive): selecting a project always opens the project's own view in the wide detail pane \u2014 never a bare row selection or a lingering task of it.",B.k,null,!1)
B.hfk=new A.C("wrapRows",B.ab,"Opt-in (dufb-1017, widened dispinline-1026): every LEAF row (tiles, directory rows, favorites, tree) shows the title and the row's own commentColumn fully wrapped (no clamp); ONE tap on that text edits it in place (Enter/blur/outside-tap commits, Esc cancels). Wide: the same tap also selects the row so the detail pane opens beside the editor. Phone: a tap OPENS the item (tap-opens standard); a trailing open button is an extra explicit door.",B.k,null,!1)
B.h9t=new A.C("findInFolder",B.ab,'Opt-in (dispsearch-1019): a "Find in folder" row-menu entry on folders that scopes a find box to that folder\'s subtree, with a tappable ancestor-path line on every result. Off = unchanged.',B.k,null,!1)
B.haA=new A.C("searchResultPath",B.ab,"Opt-in (dispsearch-1019): show a tappable ancestor-path line (tap a segment to reveal that folder in the tree) on rows of the app-header search results list. Implied by findInFolder.",B.k,null,!1)
B.h6v=new A.C("compactRowMenu",B.ab,'Opt-in (dufb-1017): fold the row menu \u2014 create entries under one "New \u25b8" door, copy entries under "Copy \u25b8", organize/host extras (move to top, convert, pin, menuActions) under "More \u25b8". A group with one entry stays inline. Off = the flat menu.',B.k,null,!1)
B.aAm=s(["newday"],t.s)
B.h8B=new A.C("rowStyle",B.bU,'Opt-in (disphybrid-1111) "newday": LEAF rows in the detailed contents list take New Day\'s look \u2014 a coloured lane edge from prioColumn (rowLaneColors / rowLaneFallback; off-list values are neutral), a \u25b8/\u25be inline peek at what is inside, "N inside" / "N comments" (rowCommentKinds + overviewLogColumn), the tag chips and the overviewDueColumn date. Folder cards are unchanged. Unset = the existing detailed tile.',B.aAm,null,!1)
B.h98=new A.C("rowMenu",B.bU,'Opt-in (disphybrid-1111) "newday": right-click (and a long-press; on touch, lifting a row and releasing it in place) opens the hybrid row menu \u2014 title + counts, Copy as text (outline with items inside and comments), Lane (prioOptions), Status \u203a, Move into project\u2026 (edges + dragReparent: re-points only the edge from the parent being viewed), Star, Open \u2014 and "More actions \u203a" with the full existing row menu. Unset = the existing menu.',B.aAm,null,!1)
B.fZ4=new A.C("rowLaneColors",B.a_,'disphybrid-1111: {lane: "#RRGGBB"} overrides for the hybrid row\'s lane edge (defaults: immediate, now, next, queued, later).',B.k,null,!1)
B.h2n=new A.C("rowLaneFallback",B.a_,"disphybrid-1111: {status: lane} \u2014 the lane an EMPTY prioColumn reads as for the edge colour (display only, never written).",B.k,null,!1)
B.h0I=new A.C("rowCommentKinds",B.a_,'disphybrid-1111: kindColumn values counted as comments on a hybrid row (with overviewLogColumn-marked rows); every other child counts as "inside".',B.k,null,!1)
B.fZz=new A.C("todayStrip",B.a_,'disphybrid-1111: [{id, label, groupLabel?, color "#hex", filter}] \u2014 counted chips above the tree (wide) / under the top bar (phone, not on the item page), and the groups of the defaultView "today" list. filter: {column, value | in | exists | empty} or a list (ANDed); values are literal (no today/now tokens); "$playerId" binds to the signed-in player, else defaultActor, else the bucket is empty.',B.k,null,!1)
B.hgY=new A.C("todayAction",B.a_,"disphybrid-1111: action fired when a Today chip is tapped outside the Today view (e.g. goto the Today screen); that screen opens focused on the tapped bucket.",B.k,null,!1)
B.him=new A.C("defaultFilterPreset",B.a_,'Opt-in (dufb-1017): the filterPresets entry (int index or English name) applied to the tasks column on open. The Presets menu then offers "Set current filter as my default" (stored per user/applet) and "Reset default" (back to this preset).',B.k,null,!1)
B.hal=new A.C("followSelection",B.ab,"Two-way sync with `board.settings['sel:<table>']`: an external write (e.g. a notepad's resolved [[Wiki Link]] tap) selects + reveals that row here; picking a row here publishes back to the same setting. Off by default (no behavior change).",B.k,null,!1)
B.hir=new A.C("id",B.T,"This node's handle \u2014 required for the explorerSetPanelVisible runtime action (and panelChannel) to target it (an id-less explorer still renders, just not runtime-controllable).",B.k,null,!1)
B.hgH=new A.C("panelChannel",B.ab,"Opt-in (roundb-0720-eng): the three rail panels (tree/contents/detail) collapse state is read/written through BoardState.effectiveExplorerPanelVisible/setExplorerPanelVisible (runtime-overridable via the explorerSetPanelVisible action) instead of pure session-local widget state. Requires this node's `id`. Off (default): byte-identical to today, pure private State.",B.k,null,!1)
B.h8H=new A.C("twoLevel",B.ab,"Two-column rail: column 1 lists top-level folders/projects, column 2 the selected one's children, before the detail view.",B.k,null,!1)
B.fVd=new A.C("autoSelectFirstChild",B.ab,"On selecting a folder, immediately select its first child so the detail pane is never empty.",B.k,null,!1)
B.h7z=new A.C("colorColumn",B.K,"Optional per-row colour column (ramp name or #hex) tinting the rail entry.",B.k,null,!1)
B.hgS=new A.C("emojiColumn",B.K,"Optional column holding a leading emoji shown on each rail entry.",B.k,null,!1)
B.h3z=new A.C("cardRows",B.ab,"Render each rail row as a rounded card surface (margin + border) instead of a flat list row, so an items panel reads as pretty cards.",B.k,null,!1)
B.fZ0=new A.C("clearSelectionOnBackgroundTap",B.ab,'With followSelection on, tapping empty rail background clears the current sel:<table> selection (same as the "Scoped to: X \u2715" chip). On by default when followSelection is set; set false to opt a followSelection explorer out.',B.k,null,!1)
B.h8X=new A.C("newValues",B.a_,'Values stamped on every new leaf (New <file> and addItems), token-resolved like a composer write (e.g. {"createdBy": "$playerId"}); addItems\' own "values" override these per-item.',B.k,null,!1)
B.h_q=new A.C("focusRoot",B.ab,'mokufb7-1004-B: while a row is open the rail shows only its top-level ancestor with that row\'s children nested (always open); the rail title becomes a back-link to the full list (the open row stays open); narrow layouts show the family as tabs. Leaves with children expand; "New <file>" always makes a top-level row; deleting a row with children asks delete-all vs keep. Classic parentColumn mode only. Off = unchanged.',B.k,null,!1)
B.fWr=new A.C("childAdd",B.a_,'With focusRoot: {label, icon?, options?:[{label, icon?, action}], action?} \u2014 the "+ New <child>" row under the focused family and in a top-level row\'s menu. Actions fire with the top-level row id + the surface `locale`; no action = a plain child row. Hidden when the table lacks parentColumn. Labels may be {lang: text} maps.',B.k,null,!1)
B.h_W=new A.C("childIcon",B.T,'With focusRoot: icon for child rows (e.g. "branch").',B.k,null,!1)
B.h50=new A.C("childNoun",B.T,'With focusRoot: children\'s noun "singular|plural" for the delete-with-children choice; may be a {lang: text} map.',B.k,null,!0)
B.df6=s([B.hgp,B.h7S,B.h95,B.h0S,B.fZc,B.hhN,B.fV4,B.h8j,B.h6G,B.he1,B.h42,B.hcy,B.h_8,B.fYE,B.hgq,B.fXM,B.fZL,B.h5J,B.h6z,B.hh_,B.hfo,B.hiv,B.h9A,B.fXB,B.fUX,B.fUR,B.fTf,B.fZR,B.ha4,B.fZk,B.h5Q,B.h7N,B.fZF,B.fXt,B.h2d,B.fTq,B.fZH,B.heZ,B.fUU,B.hbO,B.h6E,B.h3b,B.h9v,B.h_z,B.h7c,B.fXa,B.h2v,B.h8L,B.hcP,B.fUh,B.hcT,B.fW6,B.hi8,B.hak,B.fYP,B.h0_,B.h12,B.fYk,B.hhB,B.fVG,B.hbq,B.h8F,B.h2f,B.fV3,B.fWF,B.hcn,B.hg1,B.fWp,B.h7Z,B.h54,B.fVQ,B.fXr,B.fUP,B.h2U,B.h_s,B.fTd,B.heJ,B.h7e,B.h6f,B.heS,B.h6V,B.hfO,B.h8f,B.h7a,B.fW5,B.hfG,B.hha,B.h5U,B.hdK,B.haS,B.h3K,B.fTc,B.h1O,B.fTC,B.fZw,B.h1X,B.hds,B.h8c,B.h8m,B.heA,B.fZj,B.hac,B.h27,B.fTZ,B.h_o,B.hdn,B.fVx,B.h59,B.hgr,B.hfZ,B.h5M,B.h0l,B.fTT,B.h4r,B.h9O,B.h6F,B.hcY,B.h9V,B.h5t,B.fY3,B.fXe,B.fXH,B.fU7,B.hc6,B.hc0,B.hip,B.h8z,B.h9J,B.hbC,B.fVb,B.fVI,B.hbN,B.fVD,B.hcr,B.fXP,B.fY6,B.hfk,B.h9t,B.haA,B.h6v,B.h8B,B.h98,B.fZ4,B.h2n,B.h0I,B.fZz,B.hgY,B.him,B.hal,B.hir,B.hgH,B.h8H,B.fVd,B.h7z,B.hgS,B.h3z,B.fZ0,B.h8X,B.h_q,B.fWr,B.h_W,B.h50,B.Ry],t.G)
B.fvf=new A.dv("explorer","Master-detail file browser: a collapsible left folder-tree (nested via a self-referential parent column) drives a configurable detail view of the selected file. New/rename/delete (recoverable Trash) on the rail.",B.df6,!1)
B.h7u=new A.C("table",B.b1,'Files table (default "files").',B.k,null,!1)
B.h9h=new A.C("fileId",B.T,'The open file\'s id; usually injected as "rowId" by an explorer detail.',B.k,null,!1)
B.h6H=new A.C("parentColumn",B.K,'Self-referential parent id linking pages to their file (default "parentId").',B.k,null,!1)
B.hhR=new A.C("nameColumn",B.K,'Page-name column (default "name").',B.k,null,!1)
B.fZm=new A.C("orderColumn",B.K,'Order column for pages (default "order").',B.k,null,!1)
B.fYb=new A.C("kindColumn",B.K,'Column marking a row as a page (default "kind").',B.k,null,!1)
B.hev=new A.C("pageValue",B.T,'kindColumn value that means "page" (default "page").',B.k,null,!1)
B.h1o=new A.C("pageLabel",B.T,'Noun for a page: Page / Canvas / Sheet (default "Page").',B.k,null,!1)
B.h55=new A.C("fileIsFirstPage",B.ab,"Treat the file row itself as page 1 (default true).",B.k,null,!1)
B.hfF=new A.C("detail",B.tS,'Editor rendered for the active page; "rowId"/"table" are injected.',B.k,null,!1)
B.d_C=s([B.h7u,B.h9h,B.h6H,B.hhR,B.fZm,B.fYb,B.hev,B.h1o,B.h55,B.hfF],t.G)
B.fww=new A.dv("pages","A page strip for an open file (companion to explorer): switch / add / rename / delete the pages inside one file, with a configurable detail editor for the active page. Same strip drives a document's pages, a drawing's canvases, or a spreadsheet's sheet-tabs.",B.d_C,!1)
B.aVL=new A.C("table",B.b1,"The table holding the document/page row.",B.k,null,!1)
B.aW4=new A.C("rowId",B.T,"Row to edit; usually injected by a pages/explorer detail.",B.k,null,!1)
B.h7D=new A.C("column",B.K,'Column storing the document Delta JSON (default "body").',B.k,null,!1)
B.h_a=new A.C("page",B.ab,'Page-look surface \u2014 a centered max-width "paper". On by default; set false for a plain full-bleed editor.',B.k,null,!1)
B.hhU=new A.C("fonts",B.a_,'Override the font-family picker: {"Label": "Family", \u2026}. Omit to use the bundled document fonts (Lora, Inter, Space Grotesk, IM Fell English, Special Elite, Rye).',B.k,null,!1)
B.hhp=new A.C("title",B.T,'Document title used when printing (default "Document"); may be a {lang: text} map.',B.k,null,!0)
B.d0k=s([B.aVL,B.aW4,B.h7D,B.h_a,B.hhU,B.hhp],t.G)
B.fw7=new A.dv("richdoc","A true WYSIWYG rich-text editor (flutter_quill) for one row's column \u2014 toolbar formatting (bold/italic/underline/strike/highlight/colour/font/headings/lists/links) stored as Quill Delta JSON. Migrates an existing Markdown value in on first open. The Docs page editor; Notes stay on `notepad`/Markdown.",B.d0k,!1)
B.h3s=new A.C("column",B.K,'Text column to edit (default "body").',B.k,null,!1)
B.h_T=new A.C("titleColumn",B.K,"Optional column shown as the editor heading (inline when chromeless).",B.k,null,!1)
B.h7P=new A.C("firstLineTitle",B.ab,"Opt-in Apple-Notes look (needs titleColumn; implies titleFromFirstLine): the first body line is the note title, set large + bold in the editor, no separate header title; an empty note is focused ready to type. A note with an explicit (manual/legacy) title keeps the classic header title and a plain body. No data is migrated.",B.k,null,!1)
B.h5H=new A.C("titleFromFirstLine",B.ab,"Opt-in (needs titleColumn): on each body save the title follows the first non-empty body line (~60 chars, markdown markers stripped) until the title is changed any other way (a rename) \u2014 then the manual title wins permanently. Pages with a different pre-existing title are never touched; wiki-links re-resolve on a derived change.",B.k,null,!1)
B.hgu=new A.C("titleAutoColumn",B.K,'Column remembering the last title derived by titleFromFirstLine (default "titleAuto"). A stored title that differs from it is treated as manual.',B.k,null,!1)
B.fXF=new A.C("placeholder",B.T,"Empty-editor hint text; may be a {lang: text} map.",B.k,null,!0)
B.fUB=new A.C("editedByColumn",B.K,"Opt-in: on a real inline edit, stamp this ref column with `editedBy` (the pre-resolved actor id).",B.k,null,!1)
B.hhj=new A.C("editedAtColumn",B.K,"Opt-in: date column stamped today alongside editedByColumn on an edit.",B.k,null,!1)
B.hdQ=new A.C("editedBy",B.T,"Pre-resolved actor id the host passes for edit stamping (a users row).",B.k,null,!1)
B.h5E=new A.C("saveMode",B.T,'Initial save mode: "live" (continuous, default) or "manual" (Save).',B.k,null,!1)
B.h9c=new A.C("chromeless",B.ab,"Hide the notepad's own header (Write/Preview, Auto/Manual, Save) so a host (e.g. an expandable card) owns the edit chrome; the title then renders inline.",B.k,null,!1)
B.h72=new A.C("editing",B.ab,"Host-driven edit gate: false = read-only Markdown view, true = editable. Omit to self-manage (the default).",B.k,null,!1)
B.hcX=new A.C("readOnly",B.ab,"Force the read (Markdown) view.",B.k,null,!1)
B.fUe=new A.C("autoHeight",B.ab,"Size to content (no Expanded) for inline use \u2014 a short note stays short; the editor grows with its text.",B.k,null,!1)
B.fXE=new A.C("toolbar",B.ab,"Docs-grade authoring: show a Markdown formatting toolbar (bold, italic, headings, lists, quote, code, link) in Write mode. Off by default \u2014 Notes stays minimal; Docs opts in.",B.k,null,!1)
B.h5D=new A.C("document",B.ab,"Hold the editor + reading view to a centered page width for a real document feel. Off by default (full-bleed notes).",B.k,null,!1)
B.hbY=new A.C("colorColumn",B.K,'Sticky-note colour: show a quick colour strip in the editor that writes this column (a ramp name like "amber"). Colours come from the column\'s options. Off by default.',B.k,null,!1)
B.hdt=new A.C("liveFormat",B.ab,"Live formatting: render Markdown styling (bold / italic / headings / code / strikethrough) in the editor as you type, so the editor IS the preview. Off by default; Docs opts in.",B.k,null,!1)
B.hhW=new A.C("dense",B.ab,"Compact inline field: no outer padding, starts one line tall, body-medium text \u2014 a quiet field for compose cards, not a big box.",B.k,null,!1)
B.hao=new A.C("heading",B.ab,"Style the edit text as a heading (title-small) \u2014 pair with a title column so a card title reads as a heading, not body copy.",B.k,null,!1)
B.hcW=new A.C("autofocus",B.ab,"Focus the editor on mount with the cursor at the END \u2014 tap-to-edit flows get a ready cursor, no second tap.",B.k,null,!1)
B.h8N=new A.C("minLines",B.aM,"Starting height in LINES for the autoHeight editor (overrides the dense/default choice) \u2014 e.g. 3 gives a comment room to write while the read view stays compact.",B.k,null,!1)
B.h1G=new A.C("linksTable",B.b1,"Enables Obsidian-style `[[Title]]` wiki-links: an auto-maintained link-row index in this table (add/remove/update on every save), tappable resolved-link spans in Preview (writes `sel:<table>` \u2014 pair with an explorer's `followSelection` to jump there), and a `[[` title autocomplete while typing. Unset (default) \u2192 zero behavior change. If a merge (or any external write) ever leaves two linksTable rows with the same resolved title for the same FROM note, the sync keeps the FIRST row in table order and reaps the rest \u2014 deterministic, not arbitrary.",B.k,null,!1)
B.fVZ=new A.C("linkFromColumn",B.K,'linksTable column holding the FROM note\'s id (default "fromId").',B.k,null,!1)
B.h7f=new A.C("linkToColumn",B.K,'linksTable column holding the resolved TO note\'s id, empty when unresolved (default "toId").',B.k,null,!1)
B.fZ5=new A.C("linkTitleColumn",B.K,'linksTable column holding the link\'s literal target title text, kept even when unresolved (default "toTitle").',B.k,null,!1)
B.h2J=new A.C("linkFromTitleColumn",B.K,'linksTable column that also receives the FROM note\'s own title (default "fromTitle") \u2014 kept in sync on every wiki-link sync pass and on rename of the source note. Lets a backlinks view label each row with the source without a join.',B.k,null,!1)
B.fUO=new A.C("onLinkTap",B.a_,"Opt-in action spec { fn, args } fired when a plain Markdown `[label](target)` link (NOT a `[[Title]]` wiki-link, which uses linksTable instead) is tapped in Preview. `target` (the link's raw url/title text) substitutes any literal \"$value\" in args, same as textinput's action. Unset (default) \u2192 the link renders styled but inert, unchanged from before this prop existed.",B.k,null,!1)
B.haR=new A.C("lazyBlocks",B.ab,"Opt-in LAZY read view: builds only on-screen Markdown blocks (ListView.builder) instead of the default eager build-everything-up-front view. For a genuinely long document (e.g. a full encyclopedia article) this is the fix for visible scroll lag. No effect when `readOnly`'s shrinkWrap (inline preview) applies. Off by default \u2014 zero behavior change for existing callers.",B.k,null,!1)
B.hdN=new A.C("jumpToSectionSetting",B.T,'Opt-in "jump to section" (only acts when lazyBlocks is also true): names a board-settings key. When that setting\'s value changes to "<anything>::<heading text>" (the leading part just needs to change to force a re-jump on a repeated tap of the same section \u2014 e.g. a timestamp), the read view animate-scrolls to the first #/##/### heading block matching the text (trimmed, case-insensitive) at an ESTIMATED position \u2014 not pixel-exact.',B.k,null,!1)
B.hhV=new A.C("findEnabledSetting",B.T,'Opt-in "Find in article" (only acts when lazyBlocks is also true): names a board-settings key an external affordance (e.g. a \u22ee "Find in article" action) toggles true/false to open/close an inline search bar rendered above the article. The typed query, per-occurrence match highlighting, match-count feedback ("N of M"), next/prev stepping and scroll-to-match are all self-contained in this widget \u2014 no other prop or host wiring is needed. Plain case-insensitive substring matching only, no regex, no cross-block spans. Unset (default) \u2192 zero behavior change.',B.k,null,!1)
B.h9p=new A.C("serifH1",B.ab,"Opt-in encyclopedia-style DISPLAY TITLE: renders a top-level `# ` Markdown heading in a serif font stack (Georgia / Times New Roman / Noto Serif / generic serif fallback \u2014 no new font asset bundled, so this always renders with whatever serif face the platform already has) instead of the body sans-serif, at a larger display size. Applies to every `# ` heading in the document (in practice just the one at the very top \u2014 see `document`) in BOTH the eager and `lazyBlocks` read-view paths. Off by default: zero behavior change for every existing caller.",B.k,null,!1)
B.ha3=new A.C("imagesTable",B.b1,"Enables `local:<id>` resolution for a standalone `![alt](src)` image block (and gives inline `![alt](src)` mid-paragraph a real target to resolve, though inline never promotes to a block): the id looks up a row in this table, whose imageSrcColumn holds a base64 payload rendered via the engine's existing local-bytes image path (same as `record`'s image preview) \u2014 never fetched. An http(s) src, or a `local:<id>` that doesn't resolve, always renders as alt text; this node has no image-fetch code at all. Unset (default) \u2192 zero behavior change.",B.k,null,!1)
B.fYK=new A.C("imageSrcColumn",B.K,'Column on imagesTable holding the base64 image payload (default "b64").',B.k,null,!1)
B.dgW=s([B.aVL,B.aW4,B.h3s,B.h_T,B.h7P,B.h5H,B.hgu,B.fXF,B.fUB,B.hhj,B.hdQ,B.h5E,B.h9c,B.h72,B.hcX,B.fUe,B.fXE,B.h5D,B.hbY,B.hdt,B.hhW,B.hao,B.hcW,B.h8N,B.h1G,B.fVZ,B.h7f,B.fZ5,B.h2J,B.fUO,B.haR,B.hdN,B.hhV,B.h9p,B.ha3,B.fYK],t.G)
B.fw2=new A.dv("notepad",'An inline, auto-saving text editor for one row\'s text column, with a Write/Preview toggle (lightweight Markdown). The natural page editor for a page-able document \u2014 reads an injected "rowId".',B.dgW,!1)
B.h0c=new A.C("table",B.b1,"Table that receives each sent row.",B.k,null,!1)
B.h7_=new A.C("column",B.K,'Column the typed text fills (default "text").',B.k,null,!1)
B.fWM=new A.C("placeholder",B.T,"Empty-input hint text; may be a {lang: text} map.",B.k,null,!0)
B.h8g=new A.C("values",B.a_,"Columns preset on every sent row; values resolve $playerId/now/uuid.",B.k,null,!1)
B.hdW=new A.C("sendIcon",B.T,"Send-button icon (send/arrow).",B.k,null,!1)
B.hay=new A.C("action",B.a_,"Optional action fired on the new row (e.g. translate it).",B.k,null,!1)
B.fWK=new A.C("helperAction",B.a_,'Optional "compose helper" action fired on the DRAFT still in the text field (no row created) \u2014 draftText is merged into its own args. Renders a small icon button next to send ONLY when set.',B.k,null,!1)
B.h6X=new A.C("helperIcon",B.T,"Compose-helper button icon (translate/auto_awesome/lightbulb).",B.k,null,!1)
B.h_v=new A.C("helperTooltip",B.T,"Compose-helper button tooltip; may be a {lang: text} map.",B.k,null,!0)
B.fXZ=new A.C("attachments",B.ab,"Opt-in pending attachments: a leading + attach button inside the text field (file/image picker, all platforms), clipboard-IMAGE paste on web and desktop only, thumbnail chips with a remove x above the input. Send commits text + all pending files as ONE row (text-less send works when files are pending). Default off.",B.k,null,!1)
B.hi3=new A.C("attachmentsColumn",B.K,'Column that receives the pending attachment list (engine inline base64 {name,mime,size,data} maps, same as entry attachments). Default "attachments".',B.k,null,!1)
B.h16=new A.C("maxAttachBytes",B.aM,"Per-file cap in bytes for composer attachments (default: engine cap).",B.k,null,!1)
B.h0Z=new A.C("pasteTable",B.ab,"Opt-in (chatx-1031), web + desktop only: Cmd/Ctrl+V of spreadsheet cells (tab-separated text and/or an HTML <table>; HTML is parsed for cell text only, never rendered) inserts a GitHub-style Markdown table at the caret (first row = header; | and newlines escaped; capped at 200 rows x 30 columns with a note row). Text without tabs and images paste as before. Default off.",B.k,null,!1)
B.h5v=new A.C("dropFiles",B.ab,"Opt-in (chatx-1031), web + desktop only, requires `attachments`: files dropped on the composer become pending attachment chips with the same caps as the + picker; a highlight shows while dragging over. Default off.",B.k,null,!1)
B.h89=new A.C("enterBehavior",B.T,'Opt-in: "newline" (chatx-1031) makes plain Enter and Shift+Enter insert a newline; send = the send button or Cmd/Ctrl+Enter. "send" (entersend-1101, the standard chat convention) makes plain Enter and Cmd/Ctrl+Enter send and Shift+Enter insert a newline; on touch platforms the soft keyboard return key inserts a newline and the send button sends. Never sends/inserts while an IME composition is active. The send button gets a shortcut-hint tooltip and the field grows up to `maxLines`. Unset = Enter sends (unchanged). Values: "newline" | "send".',B.k,null,!1)
B.h1A=new A.C("enterBehaviorSetting",B.T,'Opt-in (chatcomposer-1102): a settings key (e.g. "chat:enterKey"). When that setting holds "send" or "newline" it overrides `enterBehavior` live; any other value falls back to `enterBehavior`.',B.k,null,!1)
B.h6U=new A.C("fillSetting",B.T,'Opt-in (chatcomposer-1102): a settings key holding text the host wants prefilled (e.g. "chat:composerFill"). When the seq setting (`fillSeqSetting`, default "<fillSetting>Seq") changes after mount the composer replaces its text with it, caret at the end, and takes focus. The mount-time seq is the baseline (no stale fire).',B.k,null,!1)
B.h5z=new A.C("fillSeqSetting",B.T,'Optional seq settings key for `fillSetting` (default "<fillSetting>Seq").',B.k,null,!1)
B.hh5=new A.C("contentMaxWidth",B.aM,"Opt-in (chatlayout-1102): centres the composer in a column of this max width with a 16 px side gutter, matching a thread list whose `bubbles.contentMaxWidth` is the same value.",B.k,null,!1)
B.fWl=new A.C("draftOptions",B.a_,'Opt-in chips above the box while a draft is typed, whose values go into the new row: a list of { kind: date|time|multi|single|duration|startNow, column, label?, table?, labelColumn?, allowNew? }. table is required for multi and single. colorColumn? colors a single option. duration (timers-1108): presets? (seconds, default [300,600,1500,3600]), allowCustom? (default true) \u2014 None / lengths / Custom, writes seconds. startNow: Start tracking now / Not now \u2014 when on, send writes the current UTC ISO time to column. newday-r5-1108 (opt-in): single/multi choices? [{value, label}] or choicesRange? [from, to] instead of table; scroll? (one sideways line with a right-edge fade); default? (shown selected, written on send; "" = nothing); sub? [{when: [parent values], ...option}] follow-up rows in one tinted box, never written while hidden; recentColumn? (most recently used first, stamped on send/new); showCount? + countLabel? ("{n} tags") + maxShown?; duration style? "stepper" + step? (seconds, default 60). newday-p1-1109 (opt-in): countLabelOne? ("{n} tag", for exactly one); stepper hours? (h : mm : ss); wrapNarrow? (with scroll: wraps under a 600 px window); single picker? \u2014 a "Choose\u2026" chip (replacing + New) opening a filterable list of every choice with its colour, Enter picks the top match, "+ Create group \u2026" opens the group editor prefilled (pickerTitle?, createLabel? "{name}", orderColumn?, settingKey? for the remembered custom colour).',B.k,null,!1)
B.h2F=new A.C("dayChip",B.a_,"Opt-in (newday-r5b-1108): a chip inside the box, on the left, showing the day the entry goes to (\"Sun 8 \u25be\"); tap to pick. true (the first date draftOption's column), a column name, or {column, settingKey}. Day = the draft's pick, else the column's preset in values (e.g. $day:<key>), else settingKey's day, else today; send writes it.",B.k,null,!1)
B.h8l=new A.C("draftPeekUntil",B.T,'Opt-in (newday-r5-1108), with draftStyle "drawer": the column of the last draftOptions row shown while the keyboard is up; the rest sit below a fade and a "More below" cue until the bar is dragged up (which opens every row and grows the text box to 6 lines).',B.k,null,!1)
B.h4l=new A.C("float",B.ab,"Opt-in (newday-r5-1108), on a root footer composer: on a wide layout (content >= floatMinWidth, default 840) the box floats centred over the content, at most floatMaxWidth (default 640) wide, 16 px above the bottom, with a soft shadow; content gets its height + 16 as bottom padding.",B.k,null,!1)
B.fVg=new A.C("above",B.a_,"Opt-in (newday-p1-1109), on a root footer: a node (e.g. groupadd) shown directly above the bottom box, left-aligned with it \u2014 on the docked band on a phone, over the content just above a floating box (counted in the content's bottom padding).",B.k,null,!1)
B.d2w=s(["chips","drawer"],t.s)
B.heL=new A.C("draftStyle",B.bU,'How draftOptions show: "chips" (default) or "drawer" (a drawer rising with the draft, one line per option; peeks over a phone keyboard, opens when pulled up).',B.d2w,null,!1)
B.h09=new A.C("trailingActions",B.a_,"Opt-in (chatlayout-1102): list of {icon, tooltip, action}; the first entry renders as a 44x44 icon button between the field and Send. Fires without a draft.",B.k,null,!1)
B.h8v=new A.C("maxLines",B.aM,'With `enterBehavior` "newline" or "send": lines the field grows to before it scrolls internally (default 8). Ignored otherwise.',B.k,null,!1)
B.he7=new A.C("busy",B.a_,'Opt-in (chatcap-ui-1031), with `stopAction`: { statusColumn, statuses[], scopeColumn, scopeValue }. While the LATEST non-user row of `table` in scope (scopeColumn == resolved scopeValue, e.g. "$selected:subchats") has a status in `statuses`, the send button becomes a Stop button and sending is disabled.',B.k,null,!1)
B.hiN=new A.C("stopAction",B.a_,"Opt-in (chatcap-ui-1031): the action the Stop button fires (see `busy`).",B.k,null,!1)
B.heH=new A.C("stopLabel",B.T,"Stop button tooltip; may be a {lang: text} map.",B.k,null,!0)
B.cOt=s([B.h0c,B.h7_,B.fWM,B.h8g,B.hdW,B.hay,B.fWK,B.h6X,B.h_v,B.fXZ,B.hi3,B.h16,B.h0Z,B.h5v,B.h89,B.h1A,B.h6U,B.h5z,B.hh5,B.fWl,B.h2F,B.h8l,B.h4l,B.fVg,B.heL,B.h09,B.h8v,B.he7,B.hiN,B.heH],t.G)
B.fwn=new A.dv("composer",'A chat-style "type a message and send" input. Unlike notepad (which edits one row in place), it APPENDS a new row each send \u2014 carrying the typed text plus preset values ($playerId/now/uuid resolved) \u2014 then clears itself. The primitive for chats, comments and logs.',B.cOt,!1)
B.h4O=new A.C("table",B.b1,"Table of the row to edit (defaults to the host/injected table).",B.k,null,!1)
B.fV8=new A.C("rowId",B.T,"Id of the row to edit (usually injected by a master-detail host). A `$selected:<table>` token binds to the board-level `selectRow` pick instead of a literal id.",B.k,null,!1)
B.h9T=new A.C("emptyText",B.T,"Placeholder shown when nothing is selected; may be a {lang: text} map.",B.k,null,!0)
B.h4z=new A.C("readOnly",B.ab,"Show a posted row as an un-editable read view; a row just created in the host explorer (isNew) still opens editable so its author can fill it in once.",B.k,null,!1)
B.hcv=new A.C("hideTitle",B.ab,'Editable record only: hide the "Edit <table>" heading (action icons stay) when the record already sits under its own title, e.g. in a popup headed by the row\'s name.',B.k,null,!1)
B.h58=new A.C("backOnClose",B.ab,"Editable record only (form-input-1101): when the editor closes (Save \u2713, Discard, Delete) step back to the screen that opened this one \u2014 pop the nearest route, else hand `back` to the host. Makes a form screen's Save return to its list. Default off (stays in place).",B.k,null,!1)
B.h9F=new A.C("compact",B.ab,'Intrinsic-height, non-scrolling read view (sits as a header in a column) with an "Edit details" affordance that opens the editor.',B.k,null,!1)
B.hf1=new A.C("layout",B.T,'Read-view layout. "chips" renders the first field as a heading, long-text fields as a truncate-on-tap line, and the rest as compact inline "Label \xb7 value" chips in a Wrap. Any other value or absent keeps the default stacked label-above-value rows.',B.k,null,!1)
B.hbJ=new A.C("fields",B.a_,'Explicit list of column names to show (read view + editor). Keeps a detail to its real fields (e.g. ["title","status","description"]) regardless of the stored schema\'s hidden flags; other columns are left untouched on save.',B.k,null,!1)
B.fZZ=new A.C("statusColumn",B.K,"Completion reconcile: the status column the editor watches (default status). See completedByColumn.",B.k,null,!1)
B.hbc=new A.C("completedByColumn",B.K,"Opt-in: ref column stamped with the actor when status is saved AT doneStatus, and CLEARED when saved off it \u2014 so reopening an item through the editor never leaves a stale completer.",B.k,null,!1)
B.fVR=new A.C("finishedAtColumn",B.K,"Opt-in: date column stamped today on completion and cleared on reopen (pairs with completedByColumn).",B.k,null,!1)
B.h5m=new A.C("doneStatus",B.T,"Status value that counts as done for completion stamping (default done).",B.k,null,!1)
B.h8r=new A.C("defaultActor",B.T,"Fallback completer id when the signed-in user is not a row of the completedBy ref table.",B.k,null,!1)
B.fWj=new A.C("editedByColumn",B.K,'Opt-in: ref column stamped with the actor when a save actually changes a field (not on create, not on a no-op save) \u2014 an honest "last edited by".',B.k,null,!1)
B.hgL=new A.C("editedAtColumn",B.K,"Opt-in: date column stamped today alongside editedByColumn on a real edit.",B.k,null,!1)
B.fXK=new A.C("valueLabels",B.a_,'Opt-in (overviewsweep-0822), display-only: raw stored value \u2192 display text map (flat `{value: entry}` or column-keyed `{column: {value: entry}}`), each entry a plain string or a {lang: text} map. Used by the "chips" layout\'s inline "Label \xb7 value" chips so an enum/status column shows a translated word instead of the raw stored value under a non-English locale; the stored value itself is never touched. Same shape/precedence as the "cards" node\'s valueLabels.',B.k,null,!1)
B.fY2=new A.C("chipsInset",B.aM,'dispfb-1018, "chips" layout: horizontal inset (px) around the heading/chips block. Default 20 (unchanged). Set 0 when a parent (e.g. an explorer `detailGutter`) already supplies the gutter.',B.k,null,!1)
B.hiw=new A.C("placeholders",B.a_,'Opt-in (dufb-1017), "chips" layout: `{column: text}` \u2014 a listed field that is EMPTY shows a muted placeholder (e.g. "Untitled", "No comment yet") instead of disappearing, so an untitled row never borrows its next field as the heading. Each text is a {lang: text} map or a plain engine string key (recordPlaceholderUntitled, recordPlaceholderNoComment).',B.k,null,!1)
B.cKG=s([B.h4O,B.fV8,B.h9T,B.h4z,B.hcv,B.h58,B.h9F,B.hf1,B.hbJ,B.fZZ,B.hbc,B.fVR,B.h5m,B.h8r,B.fWj,B.hgL,B.fXK,B.fY2,B.hiw],t.G)
B.fvl=new A.dv("record","An INLINE single-row editor for a master-detail RIGHT pane: renders the record editor for the injected `rowId` (from explorer/pages) in place of a modal sheet, so selecting an item shows its full editable detail in the pane instead of a popup. Autosaves when the app sets app.autosave; otherwise carries its own Save.",B.cKG,!1)
B.fUa=new A.C("appletId",B.T,"Id of the applet to embed (passed to the host resolver).",B.k,null,!1)
B.h_V=new A.C("instanceId",B.T,"Optional instance id, when one applet is embedded more than once.",B.k,null,!1)
B.heY=new A.C("appletColumn",B.T,"Row-bound: read the applet id from this COLUMN of the injected row (table/rowId injected by a master-detail host) instead of appletId.",B.k,null,!1)
B.h7K=new A.C("instanceFromRow",B.ab,"Row-bound: use the injected row id as the instance, so each row holds its OWN dataset (e.g. a comment item embeds its own wireframe).",B.k,null,!1)
B.haD=new A.C("screen",B.T,"Which screen of the embedded applet to show; default = its first.",B.k,null,!1)
B.fWY=new A.C("bare",B.ab,"Render the child WITHOUT its own top-level chrome (a `header` or `backbutton` at the top of the embedded body) \u2014 for a host surface that already draws a header and would otherwise stack two. The resolver can ask for the same thing by returning an EmbeddedApplet with `chrome: false`; either side asking is enough. Default false = today's behavior, byte-identical.",B.k,null,!1)
B.hd9=new A.C("scope",B.a_,'Optional `{table, rowId}` to open the embedded applet ALREADY SCOPED to one row (e.g. `{"table":"boards","rowId":"..."}`) \u2014 reuses the child applet\'s OWN `scopeTargets` (the same explorer-driven scoping a user gets by picking that row), so the embed opens with no unscoped list flash. Absent = unscoped default screen (unchanged behavior).',B.k,null,!1)
B.h1r=new A.C("height",B.aM,"Slot height in px (default 520); set for taller/shorter embeds.",B.k,null,!1)
B.heX=new A.C("width",B.aM,"Optional fixed width; omit to fill the available width.",B.k,null,!1)
B.h1f=new A.C("presetScope",B.a_,"priorun-0802 unit2: `{table, column, value}` \u2014 directly calls BoardState.setScope(table, column, value) on the CHILD board so any scopeColumn-aware node inside it (e.g. bubl's `scopeColumn`) filters by that column, with no scopeTargets declaration needed. Distinct from `scope` above (opens on one specific row via the child's OWN declared scopeTargets). `value` supports the same live-token convention every filter-shaped prop uses ($rowId = this embed own injected row, $selected:<table> = the host board live selection, $playerId, or a literal). FAIL-CLOSED: a configured-but-unresolved token (nothing selected yet) sets the scope to a sentinel matching no real row \u2014 never falls back to unscoped \u2014 unless `scopeOptional: true` is also set. Absent = no setScope call at all (unchanged default).",B.k,null,!1)
B.fXN=new A.C("scopeOptional",B.ab,'Pairs with `presetScope` only. Default false keeps presetScope fail-closed (unresolved token -> sentinel, empty scoped set). Set true to instead CLEAR the scope on an unresolved token (full unscoped child) \u2014 for a user-driven selection-chip use where "nothing selected yet" should show everything, not nothing. Mirrors priolanes\' `scopeOptional`.',B.k,null,!1)
B.h2R=new A.C("embedSpecOverrides",B.a_,"Opt-in: a map SHALLOW-merged onto the embedded applet's picked ROOT node spec at mount \u2014 EMBED side wins, only for the keys given here (a present key replaces that key on the root node wholesale, it does not deep-merge nested maps/lists; every other key on the root node is untouched). Lets one host surface ask an embedded applet's root to render slightly differently (e.g. a canvas embed opting into `{\"gestureModel\": \"panFirst\"}`) WITHOUT changing the embedded applet's own JSON, so every other mount of that same applet stays byte-identical. Absent = today's exact behavior (root passed through unchanged).",B.k,null,!1)
B.dgD=s([B.fUa,B.h_V,B.heY,B.h7K,B.haD,B.fWY,B.hd9,B.h1r,B.heX,B.h1f,B.fXN,B.h2R],t.G)
B.fvT=new A.dv("embed",'Render another applet (a separate board + its own screens) nested inside this screen \u2014 the basis for "nested applets" (a suite shell that mounts Docs/Sheets/Notes, a dashboard built from other apps, or reusing an existing applet as a tab). The host wires a resolver that loads the applet by id; shows a placeholder if unsupported.',B.dgD,!1)
B.aVI=new A.C("table",B.T,"Table of the injected row.",B.k,null,!1)
B.hix=new A.C("rowId",B.T,'Id of the row to read `column` from (usually injected by a master-detail host \u2014 explorer/pages `detail`). A `$selected:<table>` token binds to the board-level `selectRow` pick instead, so a `switch` used outside a master-detail host can still key off "the row the user picked from a list".',B.k,null,!1)
B.hf2=new A.C("id",B.T,"Alias of `rowId` (either name works; `rowId` wins if both are set).",B.k,null,!1)
