B.h29=new A.C("groups",B.a_,'{ table, nameColumn?, colorColumn?, orderColumn? } (defaults name, color, order). njnest-1111: optional \u2014 without it every row is listed loose (no group headers, no "+ New group", no group filter) and a drop writes only the order column.',B.k,null,!1)
