B.hgI=new A.C("groupColumn",B.K,'Row column holding the group id (default "groupId").',B.k,null,!1)
B.h1u=new A.C("groupsColumn",B.K,'Opt-in multi-group membership (ndtags-1109): a list column of group ids (e.g. "groupIds"). A row shows under EACH of its groups (the same row, not a copy; group counts count it once per group). Empty list falls back to groupColumn, the PRIMARY group (first entry); drops write both.',B.k,null,!1)
