B.fvo=new A.dv("recordtypes",'Settings list of the record-type catalog: each type expands to its fields (drag handle to reorder, type label on the right, tap to rename or remove with a confirm, "+ Add field"); a muted "+ New type (later)" row.',B.d8L,!1)
B.h0W=new A.C("rowId",B.T,"The row id, or `$selected:<table>`, as on record.",B.k,null,!1)
B.h35=new A.C("titleColumn",B.K,'Title column (default "title").',B.k,null,!1)
B.fYo=new A.C("doneColumn",B.K,'Boolean done column for the title band checkbox (optional). njnest-1111: false \u2014 no done column at all: the subtasks have no ticks either ("N inside", plain "- " bullets when copied).',B.k,null,!1)
