B.e9x=new A.b(B.m,["Nothing to move.","No hay nada que mover.","Rien \xe0 d\xe9placer.","Nichts zu verschieben.","Niente da spostare.","Nada para mover.","Niets om te verplaatsen.","Inget att flytta.","Nen\xed co p\u0159esunout.","\u0394\u03b5\u03bd \u03c5\u03c0\u03ac\u03c1\u03c7\u03b5\u03b9 \u03c4\u03af\u03c0\u03bf\u03c4\u03b1 \u03c0\u03c1\u03bf\u03c2 \u03bc\u03b5\u03c4\u03b1\u03ba\u03af\u03bd\u03b7\u03c3\u03b7.","Nie ma czego przenie\u015b\u0107.","\u041d\u0435\u043c\u0430\u0454 \u0447\u043e\u0433\u043e \u043f\u0435\u0440\u0435\u043c\u0456\u0449\u0443\u0432\u0430\u0442\u0438.","\u041d\u0435\u0447\u0435\u0433\u043e \u043f\u0435\u0440\u0435\u043c\u0435\u0449\u0430\u0442\u044c.","Ta\u015f\u0131nacak bir \u015fey yok.","Kh\xf4ng c\xf3 g\xec \u0111\u1ec3 chuy\u1ec3n.","\uc62e\uae38 \ud56d\ubaa9\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.","\u79fb\u52d5\u3059\u308b\u3082\u306e\u304c\u3042\u308a\u307e\u305b\u3093\u3002","\u6ca1\u6709\u53ef\u79fb\u52a8\u7684\u5185\u5bb9\u3002","\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0627 \u064a\u0645\u0643\u0646 \u0646\u0642\u0644\u0647.","\u0932\u0947 \u091c\u093e\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0941\u091b \u0928\u0939\u0940\u0902 \u0939\u0948\u0964","\u0686\u06cc\u0632\u06cc \u0628\u0631\u0627\u06cc \u0627\u0646\u062a\u0642\u0627\u0644 \u0646\u06cc\u0633\u062a."],t.w)
B.ek1=new A.b(B.m,["That board is no longer here \u2014 nothing was moved.","Ese tablero ya no est\xe1 aqu\xed; no se movi\xf3 nada.","Ce tableau n\u2019existe plus \u2014 rien n\u2019a \xe9t\xe9 d\xe9plac\xe9.","Dieses Board ist nicht mehr vorhanden \u2013 es wurde nichts verschoben.","Quella bacheca non c\u2019\xe8 pi\xf9: non \xe8 stato spostato nulla.","Esse quadro n\xe3o est\xe1 mais aqui \u2014 nada foi movido.","Dat bord bestaat niet meer \u2014 er is niets verplaatst.","Den tavlan finns inte l\xe4ngre \u2013 inget flyttades.","Tato tabule u\u017e tu nen\xed \u2013 nic nebylo p\u0159esunuto.","\u0391\u03c5\u03c4\u03cc\u03c2 \u03bf \u03c0\u03af\u03bd\u03b1\u03ba\u03b1\u03c2 \u03b4\u03b5\u03bd \u03c5\u03c0\u03ac\u03c1\u03c7\u03b5\u03b9 \u03c0\u03bb\u03ad\u03bf\u03bd \u2014 \u03b4\u03b5\u03bd \u03bc\u03b5\u03c4\u03b1\u03ba\u03b9\u03bd\u03ae\u03b8\u03b7\u03ba\u03b5 \u03c4\u03af\u03c0\u03bf\u03c4\u03b1.","Tej tablicy ju\u017c nie ma \u2014 nic nie zosta\u0142o przeniesione.","\u0426\u0456\u0454\u0457 \u0434\u043e\u0448\u043a\u0438 \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435\u043c\u0430\u0454 \u2014 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u043f\u0435\u0440\u0435\u043c\u0456\u0449\u0435\u043d\u043e.","\u042d\u0442\u043e\u0439 \u0434\u043e\u0441\u043a\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435\u0442 \u2014 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u0449\u0435\u043d\u043e.","Bu pano art\u0131k burada de\u011fil \u2014 hi\xe7bir \u015fey ta\u015f\u0131nmad\u0131.","B\u1ea3ng \u0111\xf3 kh\xf4ng c\xf2n n\u1eefa \u2014 kh\xf4ng c\xf3 g\xec \u0111\u01b0\u1ee3c chuy\u1ec3n.","\ud574\ub2f9 \ubcf4\ub4dc\uac00 \ub354 \uc774\uc0c1 \uc5c6\uc5b4 \uc544\ubb34\uac83\ub3c4 \uc62e\uae30\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\u305d\u306e\u30dc\u30fc\u30c9\u306f\u3082\u3046\u3042\u308a\u307e\u305b\u3093\u3002\u4f55\u3082\u79fb\u52d5\u3057\u3066\u3044\u307e\u305b\u3093\u3002","\u8be5\u770b\u677f\u5df2\u4e0d\u5b58\u5728\u2014\u2014\u672a\u79fb\u52a8\u4efb\u4f55\u5185\u5bb9\u3002","\u0644\u0645 \u062a\u0639\u062f \u0647\u0630\u0647 \u0627\u0644\u0644\u0648\u062d\u0629 \u0645\u0648\u062c\u0648\u062f\u0629 \u2014 \u0644\u0645 \u064a\u062a\u0645 \u0646\u0642\u0644 \u0623\u064a \u0634\u064a\u0621.","\u0935\u0939 \u092c\u094b\u0930\u094d\u0921 \u0905\u092c \u092f\u0939\u093e\u0901 \u0928\u0939\u0940\u0902 \u0939\u0948 \u2014 \u0915\u0941\u091b \u092d\u0940 \u0928\u0939\u0940\u0902 \u0932\u0947 \u091c\u093e\u092f\u093e \u0917\u092f\u093e\u0964","\u0622\u0646 \u062a\u062e\u062a\u0647 \u062f\u06cc\u06af\u0631 \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0631\u062f \u2014 \u0686\u06cc\u0632\u06cc \u0645\u0646\u062a\u0642\u0644 \u0646\u0634\u062f."],t.w)
B.ecZ=new A.b(B.m,["This app version can't move items yet \u2014 nothing was changed.","Esta versi\xf3n de la app a\xfan no puede mover elementos; no se cambi\xf3 nada.","Cette version de l\u2019app ne peut pas encore d\xe9placer d\u2019\xe9l\xe9ments \u2014 rien n\u2019a \xe9t\xe9 modifi\xe9.","Diese App-Version kann Eintr\xe4ge noch nicht verschieben \u2013 es wurde nichts ge\xe4ndert.","Questa versione dell\u2019app non pu\xf2 ancora spostare elementi: non \xe8 stato modificato nulla.","Esta vers\xe3o do app ainda n\xe3o move itens \u2014 nada foi alterado.","Deze app-versie kan items nog niet verplaatsen \u2014 er is niets gewijzigd.","Den h\xe4r appversionen kan inte flytta objekt \xe4n \u2013 inget \xe4ndrades.","Tato verze aplikace zat\xedm neum\xed p\u0159esouvat polo\u017eky \u2013 nic se nezm\u011bnilo.","\u0391\u03c5\u03c4\u03ae \u03b7 \u03ad\u03ba\u03b4\u03bf\u03c3\u03b7 \u03c4\u03b7\u03c2 \u03b5\u03c6\u03b1\u03c1\u03bc\u03bf\u03b3\u03ae\u03c2 \u03b4\u03b5\u03bd \u03bc\u03c0\u03bf\u03c1\u03b5\u03af \u03b1\u03ba\u03cc\u03bc\u03b7 \u03bd\u03b1 \u03bc\u03b5\u03c4\u03b1\u03ba\u03b9\u03bd\u03ae\u03c3\u03b5\u03b9 \u03c3\u03c4\u03bf\u03b9\u03c7\u03b5\u03af\u03b1 \u2014 \u03b4\u03b5\u03bd \u03ac\u03bb\u03bb\u03b1\u03be\u03b5 \u03c4\u03af\u03c0\u03bf\u03c4\u03b1.","Ta wersja aplikacji nie potrafi jeszcze przenosi\u0107 element\xf3w \u2014 nic nie zosta\u0142o zmienione.","\u0426\u044f \u0432\u0435\u0440\u0441\u0456\u044f \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043a\u0443 \u0449\u0435 \u043d\u0435 \u0432\u043c\u0456\u0454 \u043f\u0435\u0440\u0435\u043c\u0456\u0449\u0443\u0432\u0430\u0442\u0438 \u0435\u043b\u0435\u043c\u0435\u043d\u0442\u0438 \u2014 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0437\u043c\u0456\u043d\u0435\u043d\u043e.","\u042d\u0442\u0430 \u0432\u0435\u0440\u0441\u0438\u044f \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043f\u043e\u043a\u0430 \u043d\u0435 \u0443\u043c\u0435\u0435\u0442 \u043f\u0435\u0440\u0435\u043c\u0435\u0449\u0430\u0442\u044c \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u044b \u2014 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u043e.","Bu uygulama s\xfcr\xfcm\xfc \xf6\u011feleri hen\xfcz ta\u015f\u0131yam\u0131yor \u2014 hi\xe7bir \u015fey de\u011fi\u015fmedi.","Phi\xean b\u1ea3n \u1ee9ng d\u1ee5ng n\xe0y ch\u01b0a th\u1ec3 chuy\u1ec3n m\u1ee5c \u2014 kh\xf4ng c\xf3 g\xec thay \u0111\u1ed5i.","\uc774 \uc571 \ubc84\uc804\uc5d0\uc11c\ub294 \uc544\uc9c1 \ud56d\ubaa9\uc744 \uc62e\uae38 \uc218 \uc5c6\uc5b4 \uc544\ubb34\uac83\ub3c4 \ubc14\ub00c\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","\u3053\u306e\u30a2\u30d7\u30ea\u306e\u30d0\u30fc\u30b8\u30e7\u30f3\u3067\u306f\u307e\u3060\u9805\u76ee\u3092\u79fb\u52d5\u3067\u304d\u307e\u305b\u3093\u3002\u4f55\u3082\u5909\u66f4\u3055\u308c\u3066\u3044\u307e\u305b\u3093\u3002","\u5f53\u524d\u5e94\u7528\u7248\u672c\u5c1a\u4e0d\u652f\u6301\u79fb\u52a8\u6761\u76ee\u2014\u2014\u672a\u505a\u4efb\u4f55\u66f4\u6539\u3002","\u0625\u0635\u062f\u0627\u0631 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0647\u0630\u0627 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0646\u0642\u0644 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0628\u0639\u062f \u2014 \u0644\u0645 \u064a\u062a\u063a\u064a\u0651\u0631 \u0634\u064a\u0621.","\u092f\u0939 \u0910\u092a \u0938\u0902\u0938\u094d\u0915\u0930\u0923 \u0905\u092d\u0940 \u0906\u0907\u091f\u092e \u0928\u0939\u0940\u0902 \u0932\u0947 \u091c\u093e \u0938\u0915\u0924\u093e \u2014 \u0915\u0941\u091b \u092d\u0940 \u0928\u0939\u0940\u0902 \u092c\u0926\u0932\u093e \u0917\u092f\u093e\u0964","\u0627\u06cc\u0646 \u0646\u0633\u062e\u0647\u0654 \u0628\u0631\u0646\u0627\u0645\u0647 \u0647\u0646\u0648\u0632 \u0646\u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0645\u0648\u0627\u0631\u062f \u0631\u0627 \u062c\u0627\u0628\u0647\u200c\u062c\u0627 \u06a9\u0646\u062f \u2014 \u0686\u06cc\u0632\u06cc \u062a\u063a\u06cc\u06cc\u0631 \u0646\u06a9\u0631\u062f."],t.w)
