B.e1d=new A.b(B.m,['Couldn\'t open "{title}" \u2014 check your connection and try again.','No se pudo abrir "{title}". Comprueba tu conexi\xf3n e int\xe9ntalo de nuevo.',"Impossible d'ouvrir \xab {title} \xbb \u2014 v\xe9rifiez votre connexion et r\xe9essayez.","\u201e{title}\u201c konnte nicht ge\xf6ffnet werden \u2014 \xfcberpr\xfcfe deine Verbindung und versuche es erneut.",'Impossibile aprire "{title}": controlla la connessione e riprova.','N\xe3o foi poss\xedvel abrir "{title}" \u2014 verifique sua conex\xe3o e tente novamente.','Kon "{title}" niet openen \u2014 controleer je verbinding en probeer het opnieuw.','Det gick inte att \xf6ppna "{title}" \u2013 kontrollera din anslutning och f\xf6rs\xf6k igen.','\u010cl\xe1nek "{title}" se nepoda\u0159ilo otev\u0159\xedt \u2013 zkontrolujte p\u0159ipojen\xed a zkuste to znovu.',"\u0394\u03b5\u03bd \u03ae\u03c4\u03b1\u03bd \u03b4\u03c5\u03bd\u03b1\u03c4\u03cc \u03c4\u03bf \u03ac\u03bd\u03bf\u03b9\u03b3\u03bc\u03b1 \u03c4\u03bf\u03c5 \xab{title}\xbb \u2014 \u03b5\u03bb\u03ad\u03b3\u03be\u03c4\u03b5 \u03c4\u03b7 \u03c3\u03cd\u03bd\u03b4\u03b5\u03c3\u03ae \u03c3\u03b1\u03c2 \u03ba\u03b1\u03b9 \u03b4\u03bf\u03ba\u03b9\u03bc\u03ac\u03c3\u03c4\u03b5 \u03be\u03b1\u03bd\u03ac.","Nie uda\u0142o si\u0119 otworzy\u0107 \u201e{title}\u201d \u2014 sprawd\u017a po\u0142\u0105czenie i spr\xf3buj ponownie.","\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \xab{title}\xbb \u2014 \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0437\u2019\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0456 \u0441\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437.","\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u043a\u0440\u044b\u0442\u044c \xab{title}\xbb \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0438 \u043f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0441\u043d\u043e\u0432\u0430.",'"{title}" a\xe7\u0131lamad\u0131 \u2014 ba\u011flant\u0131n\u0131z\u0131 kontrol edip tekrar deneyin.','Kh\xf4ng th\u1ec3 m\u1edf "{title}" \u2014 h\xe3y ki\u1ec3m tra k\u1ebft n\u1ed1i v\xe0 th\u1eed l\u1ea1i.','"{title}" \ubb38\uc11c\ub97c \uc5f4\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4 \u2014 \uc5f0\uacb0 \uc0c1\ud0dc\ub97c \ud655\uc778\ud55c \ub4a4 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uc138\uc694.',"\u300c{title}\u300d\u3092\u958b\u3051\u307e\u305b\u3093\u3067\u3057\u305f\u3002\u63a5\u7d9a\u3092\u78ba\u8a8d\u3057\u3066\u518d\u8a66\u884c\u3057\u3066\u304f\u3060\u3055\u3044\u3002","\u65e0\u6cd5\u6253\u5f00\u201c{title}\u201d \u2014 \u8bf7\u68c0\u67e5\u7f51\u7edc\u8fde\u63a5\u540e\u91cd\u8bd5\u3002",'\u062a\u0639\u0630\u0651\u0631 \u0641\u062a\u062d "{title}" \u2014 \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643 \u0648\u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.','"{title}" \u0928\u0939\u0940\u0902 \u0916\u094b\u0932\u093e \u091c\u093e \u0938\u0915\u093e \u2014 \u0905\u092a\u0928\u093e \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u091c\u093e\u0901\u091a\u0947\u0902 \u0914\u0930 \u092b\u093f\u0930 \u0938\u0947 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902\u0964','"{title}" \u0628\u0627\u0632 \u0646\u0634\u062f \u2014 \u0627\u062a\u0635\u0627\u0644 \u062e\u0648\u062f \u0631\u0627 \u0628\u0631\u0631\u0633\u06cc \u06a9\u0631\u062f\u0647 \u0648 \u062f\u0648\u0628\u0627\u0631\u0647 \u062a\u0644\u0627\u0634 \u06a9\u0646\u06cc\u062f.'],t.w)
B.e0o=new A.b(B.m,['Couldn\'t create the topic "{name}" \u2014 check your connection and try again.','No se pudo crear el tema "{name}". Comprueba tu conexi\xf3n e int\xe9ntalo de nuevo.',"Impossible de cr\xe9er le sujet \xab {name} \xbb \u2014 v\xe9rifiez votre connexion et r\xe9essayez.","Das Thema \u201e{name}\u201c konnte nicht erstellt werden \u2014 \xfcberpr\xfcfe deine Verbindung und versuche es erneut.",'Impossibile creare l\'argomento "{name}": controlla la connessione e riprova.','N\xe3o foi poss\xedvel criar o t\xf3pico "{name}" \u2014 verifique sua conex\xe3o e tente novamente.','Kon onderwerp "{name}" niet maken \u2014 controleer je verbinding en probeer het opnieuw.','Det gick inte att skapa \xe4mnet "{name}" \u2013 kontrollera din anslutning och f\xf6rs\xf6k igen.','T\xe9ma "{name}" se nepoda\u0159ilo vytvo\u0159it \u2013 zkontrolujte p\u0159ipojen\xed a zkuste to znovu.',"\u0394\u03b5\u03bd \u03ae\u03c4\u03b1\u03bd \u03b4\u03c5\u03bd\u03b1\u03c4\u03ae \u03b7 \u03b4\u03b7\u03bc\u03b9\u03bf\u03c5\u03c1\u03b3\u03af\u03b1 \u03c4\u03bf\u03c5 \u03b8\u03ad\u03bc\u03b1\u03c4\u03bf\u03c2 \xab{name}\xbb \u2014 \u03b5\u03bb\u03ad\u03b3\u03be\u03c4\u03b5 \u03c4\u03b7 \u03c3\u03cd\u03bd\u03b4\u03b5\u03c3\u03ae \u03c3\u03b1\u03c2 \u03ba\u03b1\u03b9 \u03b4\u03bf\u03ba\u03b9\u03bc\u03ac\u03c3\u03c4\u03b5 \u03be\u03b1\u03bd\u03ac.","Nie uda\u0142o si\u0119 utworzy\u0107 tematu \u201e{name}\u201d \u2014 sprawd\u017a po\u0142\u0105czenie i spr\xf3buj ponownie.","\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438 \u0442\u0435\u043c\u0443 \xab{name}\xbb \u2014 \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0437\u2019\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0456 \u0441\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437.","\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0442\u0435\u043c\u0443 \xab{name}\xbb \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0438 \u043f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0441\u043d\u043e\u0432\u0430.",'"{name}" konusu olu\u015fturulamad\u0131 \u2014 ba\u011flant\u0131n\u0131z\u0131 kontrol edip tekrar deneyin.','Kh\xf4ng th\u1ec3 t\u1ea1o ch\u1ee7 \u0111\u1ec1 "{name}" \u2014 h\xe3y ki\u1ec3m tra k\u1ebft n\u1ed1i v\xe0 th\u1eed l\u1ea1i.','"{name}" \ud1a0\ud53d\uc744 \ub9cc\ub4e4\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4 \u2014 \uc5f0\uacb0 \uc0c1\ud0dc\ub97c \ud655\uc778\ud55c \ub4a4 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uc138\uc694.',"\u300c{name}\u300d\u30c8\u30d4\u30c3\u30af\u3092\u4f5c\u6210\u3067\u304d\u307e\u305b\u3093\u3067\u3057\u305f\u3002\u63a5\u7d9a\u3092\u78ba\u8a8d\u3057\u3066\u518d\u8a66\u884c\u3057\u3066\u304f\u3060\u3055\u3044\u3002","\u65e0\u6cd5\u521b\u5efa\u4e3b\u9898\u201c{name}\u201d \u2014 \u8bf7\u68c0\u67e5\u7f51\u7edc\u8fde\u63a5\u540e\u91cd\u8bd5\u3002",'\u062a\u0639\u0630\u0651\u0631 \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0645\u0648\u0636\u0648\u0639 "{name}" \u2014 \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643 \u0648\u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.','"{name}" \u0935\u093f\u0937\u092f \u0928\u0939\u0940\u0902 \u092c\u0928\u093e\u092f\u093e \u091c\u093e \u0938\u0915\u093e \u2014 \u0905\u092a\u0928\u093e \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u091c\u093e\u0901\u091a\u0947\u0902 \u0914\u0930 \u092b\u093f\u0930 \u0938\u0947 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902\u0964','\u0645\u0648\u0636\u0648\u0639 "{name}" \u0627\u06cc\u062c\u0627\u062f \u0646\u0634\u062f \u2014 \u0627\u062a\u0635\u0627\u0644 \u062e\u0648\u062f \u0631\u0627 \u0628\u0631\u0631\u0633\u06cc \u06a9\u0631\u062f\u0647 \u0648 \u062f\u0648\u0628\u0627\u0631\u0647 \u062a\u0644\u0627\u0634 \u06a9\u0646\u06cc\u062f.'],t.w)
